                        try:
                            args = json.loads(json_accum) if json_accum else {}
                        except json.JSONDecodeError:
                            args = {}
                        yield ToolCallComplete(
                            tool_id=current_tool_id,
                            tool_name=current_tool_name,
                            arguments=args,
                        )
                        current_tool_name = ""
                        current_tool_id = ""
                        json_accum = ""
                elif event.type == "message_stop":
                    pass

