def on_key(self, event) -> None:
    if self._cursor != 2:
        return
    key = event.key
    if key == "backspace":
        if self._input:
            self._input = self._input[:-1]
            self._refresh()
        event.stop()
    elif len(key) == 1 and key.isprintable():
        self._input += key
        self._refresh()
        event.stop()

