def render(self) -> Text:
    if not self.teammates:
        return Text("")

    lines = Text()
    # Leader line
    lines.append("  ┌─ ", style="dim")
    lines.append("team-lead", style="cyan")
    lines.append(": thinking…", style="dim")
    if self.leader_tokens > 0:
        lines.append(
