        )
    lines.append("\n")

    for i, p in enumerate(self.teammates):
        is_last = i == len(self.teammates) - 1
        connector = "  └─ " if is_last else "  ├─ "

        lines.append(connector, style="dim")
        lines.append(f"@{p.name}", style="cyan")
        lines.append(": ")

        if p.status == "completed":
