@dataclass
class Snapshot:
    message_index: int
    user_text: str
    backups: dict[str, Backup] = field(default_factory=dict)
    timestamp: float = 0.0

def __init__(self, base_dir: str, session_id: str) -> None:
    self._session_dir = Path(base_dir) / ".mewcode" / "file-history" / session_id
    self._session_dir.mkdir(parents=True, exist_ok=True)
    self._tracked: dict[str, int] = {}
    self._snapshots: list[Snapshot] = []
    self._lock = threading.Lock()

def _backup_name(self, file_path: str, version: int) -> str:
    h = hashlib.sha256(file_path.encode()).hexdigest()[:16]
    return f"{h}@v{version}"

def make_snapshot(self, msg_index: int, user_text: str) -> None:
    with self._lock:
        backups: dict[str, Backup] = {}
        for path, ver in self._tracked.items():
            bp = self._session_dir / self._backup_name(path, ver)
            if not bp.exists():
                try:
                    data = Path(path).read_bytes()
                    bp.write_bytes(data)
                except (FileNotFoundError, OSError):
                    pass
            backups[path] = Backup(
                backup_path=str(bp), version=ver, timestamp=time.time(),
            )

        self._snapshots.append(Snapshot(
            message_index=msg_index,
            user_text=user_text,
            backups=backups,
            timestamp=time.time(),
        ))
        if len(self._snapshots) > MAX_SNAPSHOTS:
            self._snapshots = self._snapshots[-MAX_SNAPSHOTS:]

def get_snapshots(self) -> list[Snapshot]:
    with self._lock:
        return list(self._snapshots)

def has_snapshots(self) -> bool:
    with self._lock:
        return len(self._snapshots) > 0

def rewind(self, snapshot_index: int) -> list[str]:
    with self._lock:
        if snapshot_index < 0 or snapshot_index >= len(self._snapshots):
            return []

        target = self._snapshots[snapshot_index]
        changed: list[str] = []

        for file_path, backup in target.backups.items():
            bp = Path(backup.backup_path)
            try:
                backup_data = bp.read_bytes()
            except FileNotFoundError:
                fp = Path(file_path)
                if fp.exists():
                    fp.unlink()
                    changed.append(file_path)
                continue

            fp = Path(file_path)
            try:
                current_data = fp.read_bytes()
            except FileNotFoundError:
                current_data = b""

            if current_data != backup_data:
                fp.parent.mkdir(parents=True, exist_ok=True)
                fp.write_bytes(backup_data)
                changed.append(file_path)

        self._snapshots = self._snapshots[: snapshot_index + 1]
        for file_path, backup in target.backups.items():
            self._tracked[file_path] = backup.version

        return changed

@dataclass
class Condition:
    field: str
    operator: str
    value: str

def evaluate(self, ctx: HookContext) -> bool:
    field_value = ctx.get_field(self.field)
    if self.operator == "==":
        return field_value == self.value
    if self.operator == "!=":
        return field_value != self.value
    if self.operator == "=~":
        pattern = self.value
        if pattern.startswith("/") and pattern.endswith("/"):
            pattern = pattern[1:-1]
        try:
            return bool(re.search(pattern, field_value))
        except re.error:
            return False
    if self.operator == "~=":
        return fnmatch.fnmatch(field_value, self.value)
    return False

@dataclass
class ConditionGroup:
    conditions: list[Condition] = field(default_factory=list)
    logic: str = "and"

def evaluate(self, ctx: HookContext) -> bool:
    if not self.conditions:
        return True
    if self.logic == "and":
        return all(c.evaluate(ctx) for c in self.conditions)
    return any(c.evaluate(ctx) for c in self.conditions)

def _parse_single(expr: str) -> Condition:
    expr = expr.strip()
    for op in _OPERATORS:
        idx = expr.find(op)
        if idx == -1:
            continue
        field_part = expr[:idx].strip()
        value_part = expr[idx + len(op):].strip()
        if value_part.startswith('"') and value_part.endswith('"'):
            value_part = value_part[1:-1]
        return Condition(field=field_part, operator=op, value=value_part)
    raise ConditionParseError(f"No valid operator found in condition: '{expr}'")

def parse_condition(expr: str) -> ConditionGroup | None:
    if not expr or not expr.strip():
        return None

    expr = expr.strip()
    has_and = "&&" in expr
    has_or = "||" in expr

    if has_and and has_or:
        raise ConditionParseError(
            "Cannot mix '&&' and '||' in a single condition expression. "
            "Split into separate hooks instead."
        )

    if has_and:
        parts = expr.split("&&")
        logic = "and"
    elif has_or:
        parts = expr.split("||")
        logic = "or"
    else:
        parts = [expr]
        logic = "and"

    conditions = [_parse_single(p) for p in parts]
    return ConditionGroup(conditions=conditions, logic=logic)

@dataclass
