def _build_fork_context(self, mode: str) -> list[Message]:
    if mode == "none":
        return []

    history = self.agent._conversation.history if hasattr(self.agent, '_conversation') else []
    if not history:
        main_history = []
    else:
        main_history = history

    if mode == "recent":
        content_messages = [
            m for m in main_history
            if m.content and not m.tool_results
        ]
        return content_messages[-FORK_RECENT_COUNT:]

    if mode == "full":
        content_messages = [
            m for m in main_history
            if m.content and not m.tool_results
        ]
        if not content_messages:
            return []
        summary_parts = []
        for m in content_messages:
            prefix = "User" if m.role == "user" else "Assistant"
            text = m.content[:200]
            if len(m.content) > 200:
                text += "..."
            summary_parts.append(f"{prefix}: {text}")
        summary = "## Previous conversation summary\n\n" + "\n\n".join(summary_parts)
        return [Message(role="user", content=summary)]

    return []

def __init__(self, work_dir: str) -> None:
    self._work_dir = work_dir
    self._project_dir = Path(work_dir) / PROJECT_SKILLS_DIR
    self._user_dir = Path(USER_SKILLS_DIR).expanduser()
    self._skills: dict[str, SkillDef] = {}
    self._cache: dict[str, SkillDef] = {}

def load_all(self) -> dict[str, SkillDef]:
    seen: dict[str, SkillDef] = {}

    for skill in self._scan_directory(self._project_dir, "project"):
        if skill.name not in seen:
            seen[skill.name] = skill

    for skill in self._scan_directory(self._user_dir, "user"):
        if skill.name not in seen:
            seen[skill.name] = skill

    for skill in self._load_builtins():
        if skill.name not in seen:
            seen[skill.name] = skill

    self._skills = seen
    self._cache = {k: v for k, v in seen.items()}
    return seen

def _scan_directory(self, path: Path, source: str) -> list[SkillDef]:
    results: list[SkillDef] = []
    if not path.is_dir():
        return results

    for entry in sorted(path.iterdir()):
        try:
            if entry.is_file() and entry.suffix == ".md":
                skill = parse_skill_file(entry)
                skill.source_path = entry
                results.append(skill)
            elif entry.is_dir():
                skill_md = entry / "SKILL.md"
                if skill_md.is_file():
                    skill = parse_skill_file(skill_md)
                    skill.source_path = skill_md
                    skill.is_directory = True
                    results.append(skill)
        except SkillParseError as e:
            log.warning("Skipping %s skill '%s': %s", source, entry.name, e)

    return results

def get(self, name: str) -> SkillDef | None:
    skill = self._skills.get(name)
    if skill is None:
        return None

    if skill.source_path is not None:
        try:
            fresh = parse_skill_file(skill.source_path)
            fresh.is_directory = skill.is_directory
            self._skills[name] = fresh
            self._cache[name] = fresh
            return fresh
        except SkillParseError as e:
            log.warning(
                "Hot-reload failed for skill '%s', using cached version: %s",
                name, e,
            )
            return self._cache.get(name, skill)

    return skill

def get_source_label(self, name: str) -> str:
    skill = self._skills.get(name)
    if skill is None:
        return "unknown"
    if skill.source_path is None:
        return "builtin"
    path_str = str(skill.source_path)
    if path_str.startswith(str(self._project_dir)):
        return "project"
    if path_str.startswith(str(self._user_dir)):
        return "user"
    return "builtin"

def parse_frontmatter(raw: str) -> tuple[dict, str]:
    stripped = raw.lstrip()
    if not stripped.startswith("---"):
        raise SkillParseError("Missing YAML frontmatter (must start with ---)")

    end = stripped.find("---", 3)
    if end == -1:
        raise SkillParseError("Unclosed YAML frontmatter (missing closing ---)")

    yaml_block = stripped[3:end]
    body = stripped[end + 3:].lstrip("\n")

    try:
        meta = yaml.safe_load(yaml_block)
    except yaml.YAMLError as e:
        raise SkillParseError(f"Invalid YAML in frontmatter: {e}") from e

    if not isinstance(meta, dict):
        raise SkillParseError("Frontmatter must be a YAML mapping")

    return meta, body

def _validate_meta(meta: dict, source: str = "") -> None:
    ctx = f" in {source}" if source else ""

    if "name" not in meta:
        raise SkillParseError(f"Missing required field 'name'{ctx}")
    if "description" not in meta:
        raise SkillParseError(f"Missing required field 'description'{ctx}")

    name = meta["name"]
    if not isinstance(name, str) or not VALID_NAME_RE.match(name):
        raise SkillParseError(
            f"Invalid skill name '{name}'{ctx}: "
            "must be lowercase letters, digits, and hyphens, starting with a letter"
        )

    mode = meta.get("mode", "inline")
    if mode not in VALID_MODES:
        raise SkillParseError(f"Invalid mode '{mode}'{ctx}: must be one of {VALID_MODES}")

    context = meta.get("context", "full")
    if context not in VALID_CONTEXTS:
        raise SkillParseError(f"Invalid context '{context}'{ctx}: must be one of {VALID_CONTEXTS}")

