def _create_client_for_model(self, model_alias: str) -> LLMClient | None:
    if self._provider_config is None:
        return None

    from mewcode.client import create_client
    from mewcode.config import ProviderConfig

    model_map = {
        "haiku": "claude-haiku-4-5-20251001",
        "sonnet": "claude-sonnet-4-6-20250514",
        "opus": "claude-opus-4-6-20250514",
    }
    model_id = model_map.get(model_alias, model_alias)

    config = ProviderConfig(
        name=f"sub-{model_alias}",
        protocol=self._provider_config.protocol,
        base_url=self._provider_config.base_url,
        model=model_id,
        api_key=self._provider_config.api_key,
        context_window=self._provider_config.context_window,
    )
    try:
        return create_client(config)
    except Exception:
        return None

class AskUserParams(BaseModel):
    questions: list[QuestionItem] = Field(
        description="List of questions to ask the user"
    )

) -> None:
    self.questions = questions
    self.future = future

async def execute(self, params: AskUserParams) -> ToolResult:
    questions_data = [q.model_dump() for q in params.questions]

    loop = asyncio.get_running_loop()
    future: asyncio.Future[dict[str, str]] = loop.create_future()

    self._pending_event = AskUserEvent(questions=questions_data, future=future)

    try:
        answers = await asyncio.wait_for(future, timeout=300)
    except asyncio.TimeoutError:
        return ToolResult(
            output="User did not respond within 5 minutes", is_error=True
        )
    finally:
        self._pending_event = None

    lines = []
    for q in params.questions:
        answer = answers.get(q.name, "(no answer)")
        lines.append(f"{q.name}: {answer}")

    return ToolResult(output="\n".join(lines))

