class Params(BaseModel):
    command: str = Field(description="Shell command to execute")
    timeout: int = Field(default=120, description="Timeout in seconds (max 600)")

async def execute(self, params: Params) -> ToolResult:
    timeout = min(params.timeout, MAX_TIMEOUT)

    try:
        proc = await asyncio.create_subprocess_shell(
            params.command,
            stdout=asyncio.subprocess.PIPE,
            stderr=asyncio.subprocess.PIPE,
        )
        stdout, stderr = await asyncio.wait_for(proc.communicate(), timeout=timeout)
    except asyncio.TimeoutError:
        proc.kill()
        await proc.wait()
        return ToolResult(output=f"Error: command timed out after {timeout}s", is_error=True)
    except Exception as e:
        return ToolResult(output=f"Error executing command: {e}", is_error=True)

    parts: list[str] = []
    if stdout:
        parts.append(f"STDOUT:\n{stdout.decode(errors='replace')}")
    if stderr:
        parts.append(f"STDERR:\n{stderr.decode(errors='replace')}")
    if not parts:
        parts.append("(no output)")

    output = "\n".join(parts)
    return ToolResult(output=output, is_error=proc.returncode != 0)

async def execute(self, params: Params) -> ToolResult:
    if self.file_history is not None:
        self.file_history.track_edit(params.file_path)

    path = Path(params.file_path)
    if not path.exists():
        return ToolResult(output=f"Error: file not found: {params.file_path}", is_error=True)

    if self._state_cache:
        resolved = str(path.resolve())
        ok, err_msg = self._state_cache.check(resolved)
        if not ok:
            return ToolResult(output=err_msg, is_error=True)

    try:
        content = path.read_text(encoding="utf-8")
    except Exception as e:
        return ToolResult(output=f"Error reading file: {e}", is_error=True)

    count = content.count(params.old_string)
    if count == 0:
        return ToolResult(output="Error: old_string not found in file", is_error=True)
    if count > 1:
        return ToolResult(
            output=f"Error: old_string found {count} times, must be unique",
            is_error=True,
        )

    new_content = content.replace(params.old_string, params.new_string, 1)
    try:
        path.write_text(new_content, encoding="utf-8")
        if self._cache:
            self._cache.invalidate(str(path.resolve()))
        if self._state_cache:
            self._state_cache.update(str(path.resolve()))
    except Exception as e:
        return ToolResult(output=f"Error writing file: {e}", is_error=True)

    return ToolResult(output=f"Successfully edited {params.file_path}")

