        description='"keep" leaves the worktree and branch on disk; "remove" deletes both.',
    )
    discard_changes: Optional[bool] = Field(
        default=None,
        description=(
            'Required true when action is "remove" and the worktree has '
            "uncommitted files or unmerged commits. "
            "The tool will refuse and list them otherwise."
        ),
    )

async def execute(self, params: ExitWorktreeParams) -> ToolResult:
    session = self._manager.get_current_session()
    if session is None:
        return ToolResult(
            output=(
                "No-op: there is no active EnterWorktree session to exit. "
                "This tool only operates on worktrees created by EnterWorktree "
                "in the current session — it will not touch worktrees created "
                "manually or in a previous session. No filesystem changes were made."
            ),
            is_error=True,
        )

    action = params.action
    if action not in ("keep", "remove"):
        return ToolResult(
            output=f'Invalid action "{action}". Must be "keep" or "remove".',
            is_error=True,
        )

    discard = params.discard_changes or False

    if action == "remove" and not discard:
        changes = count_worktree_changes(
            session.worktree_path, session.original_head_commit
        )
        if changes.uncommitted > 0 or changes.new_commits > 0:
            parts = []
            if changes.uncommitted > 0:
                word = "file" if changes.uncommitted == 1 else "files"
                parts.append(f"{changes.uncommitted} uncommitted {word}")
            if changes.new_commits > 0:
                word = "commit" if changes.new_commits == 1 else "commits"
                parts.append(f"{changes.new_commits} {word}")
            return ToolResult(
                output=(
                    f"Worktree has {' and '.join(parts)}. "
                    "Removing will discard this work permanently. "
                    "Confirm with the user, then re-invoke with "
                    'discard_changes: true — or use action: "keep" '
                    "to preserve the worktree."
                ),
                is_error=True,
            )

    worktree_path = session.worktree_path
    original_cwd = session.original_cwd
    wt_name = session.worktree_name

    try:
        await self._manager.exit(wt_name, action=action, discard_changes=discard)
    except Exception as e:
        return ToolResult(
            output=f"Error exiting worktree: {e}", is_error=True
        )

    if action == "keep":
        return ToolResult(
            output=(
                f"Exited worktree. Your work is preserved at {worktree_path}. "
                f"Session is now back in {original_cwd}."
            )
        )

    return ToolResult(
        output=(
            f"Exited and removed worktree at {worktree_path}. "
            f"Session is now back in {original_cwd}."
        )
    )

def record(self, path: str, content: str, mtime_ns: int) -> None:
    """Record a file's content and mtime after a successful read."""
    self._cache[path] = (content, mtime_ns)

def update(self, path: str) -> None:
    """Update the cache entry after a successful edit/write."""
    try:
        p = Path(path)
        content = p.read_text(encoding="utf-8")
        mtime_ns = p.stat().st_mtime_ns
        self._cache[path] = (content, mtime_ns)
    except OSError:
        # If we can't read it back, just remove the stale entry.
        self._cache.pop(path, None)

class Params(BaseModel):
    pattern: str = Field(description="Glob pattern to match (e.g. '**/*.py')")
    path: str = Field(default=".", description="Base directory to search from")

async def execute(self, params: Params) -> ToolResult:
    base = Path(params.path)
    if not base.exists():
        return ToolResult(output=f"Error: path not found: {params.path}", is_error=True)

    try:
        matches = sorted(
            str(p.relative_to(base))
            for p in base.glob(params.pattern)
            if p.is_file() and not any(part in SKIP_DIRS for part in p.parts)
        )
    except Exception as e:
        return ToolResult(output=f"Error: {e}", is_error=True)

    if not matches:
        return ToolResult(output="No files matched the pattern.")
    return ToolResult(output="\n".join(matches))

async def execute(self, params: Params) -> ToolResult:
    base = Path(params.path)
    if not base.exists():
        return ToolResult(output=f"Error: path not found: {params.path}", is_error=True)

    try:
        regex = re.compile(params.pattern)
    except re.error as e:
        return ToolResult(output=f"Error: invalid regex: {e}", is_error=True)

    glob_pattern = params.include if params.include else "**/*"
    if not glob_pattern.startswith("**/"):
        glob_pattern = "**/" + glob_pattern

    results: list[str] = []
    for file_path in sorted(base.glob(glob_pattern)):
        if not file_path.is_file():
            continue
        if any(part in SKIP_DIRS for part in file_path.parts):
            continue
        try:
            text = file_path.read_text(encoding="utf-8", errors="ignore")
        except (OSError, UnicodeDecodeError):
            continue
        for line_num, line in enumerate(text.splitlines(), 1):
            if regex.search(line):
                rel = file_path.relative_to(base)
                results.append(f"{rel}:{line_num}:{line}")

    if not results:
        return ToolResult(output="No matches found.")
    return ToolResult(output="\n".join(results))

def __init__(self) -> None:
    self._loader: SkillLoader | None = None
    self._agent: Agent | None = None

async def execute(self, params: BaseModel) -> ToolResult:
    assert isinstance(params, LoadSkillParams)

    if self._loader is None or self._agent is None:
        return ToolResult(
            output="Error: LoadSkill not properly initialized",
            is_error=True,
        )

    skill = self._loader.get(params.name)
    if skill is None:
        available = ", ".join(n for n, _ in self._loader.get_catalog())
        return ToolResult(
            output=f"Error: unknown skill '{params.name}'. Available skills: {available}",
            is_error=True,
        )

    self._agent.activate_skill(skill.name, skill.prompt_body)

    tool_count = 0
    if skill.is_directory and skill.source_path is not None:
        from mewcode.skills.directory import register_skill_tools
        skill_dir = skill.source_path.parent
        tool_count = register_skill_tools(skill_dir, self._agent.registry)

    parts = [f"Skill '{skill.name}' activated. SOP pinned to environment context."]
    if tool_count > 0:
        parts.append(f"{tool_count} specialized tool(s) registered.")
    return ToolResult(output=" ".join(parts))

def __init__(self, file_cache: FileCache | None = None, file_state_cache: FileStateCache | None = None) -> None:
    self._cache = file_cache
    self._state_cache = file_state_cache

async def execute(self, params: Params) -> ToolResult:
    path = Path(params.file_path)
    if not path.exists():
        return ToolResult(output=f"Error: file not found: {params.file_path}", is_error=True)
    if not path.is_file():
        return ToolResult(output=f"Error: not a file: {params.file_path}", is_error=True)

    resolved = str(path.resolve())

    try:
        text = self._cache.get(resolved) if self._cache else None
        if text is None:
            text = path.read_text(encoding="utf-8")
            if self._cache:
                self._cache.put(resolved, text)
    except Exception as e:
        return ToolResult(output=f"Error reading file: {e}", is_error=True)

    if self._state_cache:
        try:
            mtime_ns = path.stat().st_mtime_ns
            self._state_cache.record(resolved, text, mtime_ns)
        except OSError:
            pass

    lines = text.splitlines()
    selected = lines[params.offset : params.offset + params.limit]
    numbered = [f"{i + params.offset + 1}\t{line}" for i, line in enumerate(selected)]
    return ToolResult(output="\n".join(numbered))

async def execute(self, params: BaseModel) -> ToolResult:
    p: SendMessageParams = params  # type: ignore[assignment]

    if p.message_type not in VALID_MESSAGE_TYPES:
        return ToolResult(
            output=f"Invalid message_type '{p.message_type}'. Must be one of: {', '.join(sorted(VALID_MESSAGE_TYPES))}",
            is_error=True,
        )

    if p.message_type == "text" and not p.summary:
        return ToolResult(
            output="Text messages require a 'summary' field (5-10 words).",
            is_error=True,
        )

    from mewcode.teams.mailbox import create_message
    from mewcode.teams.registry import AgentNameRegistry

    team = self._team_manager.get_team(self._team_name)
    if team is None:
        return ToolResult(output=f"Team '{self._team_name}' not found", is_error=True)

    mailbox = self._team_manager.get_mailbox(self._team_name)
    if mailbox is None:
        return ToolResult(output=f"Mailbox not found for team '{self._team_name}'", is_error=True)

    msg = create_message(
        from_agent=self._from_agent_name or self._from_agent_id,
        to_agent=p.to,
        content=p.message,
        summary=p.summary,
        message_type=p.message_type,
        metadata=p.metadata,
    )

    registry = AgentNameRegistry.instance()

    if p.to == "*":
        member_ids = [
            m.agent_id for m in team.members
            if m.agent_id != self._from_agent_id
        ]
        if team.lead_agent_id != self._from_agent_id:
            member_ids.append(team.lead_agent_id)
        mailbox.broadcast(member_ids, msg, exclude=self._from_agent_id)
        self._wake_pane_members(team, member_ids)
        return ToolResult(output=f"Message broadcast to {len(member_ids)} teammates.")

    target_id = registry.resolve(p.to)
    if target_id is None:
        return ToolResult(
            output=f"Cannot resolve recipient '{p.to}'. Check the name or agent ID.",
            is_error=True,
        )

    mailbox.write(target_id, msg)
    self._wake_pane(target_id)

    return ToolResult(output=f"Message sent to '{p.to}'.")

def _wake_pane(self, agent_id: str) -> None:
    pane_id = self._team_manager.get_pane_id(agent_id)
    if pane_id is None:
        return
    try:
        from mewcode.teams.spawn_tmux import send_keys_to_pane
        send_keys_to_pane(pane_id, "")
    except Exception:
        pass

def _wake_pane_members(self, team: Any, agent_ids: list[str]) -> None:
    for aid in agent_ids:
        self._wake_pane(aid)

async def execute(self, params: BaseModel) -> ToolResult:
    p: SyntheticOutputParams = params  # type: ignore[assignment]

    if self._json_schema is not None:
        error = self._validate_schema(p.output)
        if error:
            return ToolResult(output=f"Output does not match required schema: {error}", is_error=True)

    if isinstance(p.output, str):
        return ToolResult(output=p.output)

    return ToolResult(output=json.dumps(p.output, ensure_ascii=False, indent=2))

def _validate_schema(self, data: Any) -> str | None:
    schema = self._json_schema
    if schema is None:
        return None

    if "type" in schema:
        expected_type = schema["type"]
        if expected_type == "object" and not isinstance(data, dict):
            return f"Expected object, got {type(data).__name__}"
        if expected_type == "array" and not isinstance(data, list):
            return f"Expected array, got {type(data).__name__}"
        if expected_type == "string" and not isinstance(data, str):
            return f"Expected string, got {type(data).__name__}"

    if "required" in schema and isinstance(data, dict):
        missing = [k for k in schema["required"] if k not in data]
        if missing:
            return f"Missing required fields: {', '.join(missing)}"

    return None

