async def handle_permission(ctx: CommandContext) -> None:
    if ctx.agent is None:
        ctx.ui.add_system_message("Agent 未初始化")
        return

    parts = ctx.args.split(None, 1)
    sub = parts[0] if parts else ""

    if sub == "":
        mode = ctx.agent.permission_mode
        checker = ctx.agent.permission_checker
        rule_count = 0
        if checker and checker.rule_engine:
            tiers = checker.rule_engine._load_tiers()
            rule_count = sum(len(t) for t in tiers)
        ctx.ui.add_system_message(
            f"权限状态\n"
            f"  当前模式: {mode.value}\n"
            f"  规则数量: {rule_count}"
        )

    elif sub == "mode":
        mode_str = parts[1].strip() if len(parts) > 1 else ""
        if not mode_str:
            modes = ", ".join(_MODE_NAMES.keys())
            ctx.ui.add_system_message(f"用法: /permission mode <模式>\n可选: {modes}")
            return
        mode = _MODE_NAMES.get(mode_str)
        if mode is None:
            modes = ", ".join(_MODE_NAMES.keys())
            ctx.ui.add_system_message(f"未知模式: {mode_str}\n可选: {modes}")
            return
        ctx.agent.set_permission_mode(mode)
        ctx.ui.refresh_status()
        ctx.ui.add_system_message(f"权限模式已切换为: {mode.value}")

    elif sub == "rules":
        checker = ctx.agent.permission_checker
        if not checker or not checker.rule_engine:
            ctx.ui.add_system_message("规则引擎未初始化")
            return
        tiers = checker.rule_engine._load_tiers()
        names = ["用户级", "项目级", "本地级"]
        lines: list[str] = ["权限规则："]
        for name, rules in zip(names, tiers):
            if rules:
                lines.append(f"  [{name}]")
                for r in rules:
                    lines.append(f"    {r.tool_name}({r.pattern}) → {r.effect}")
            else:
                lines.append(f"  [{name}] (无规则)")
        ctx.ui.add_system_message("\n".join(lines))

    elif sub == "add":
        rule_str = parts[1].strip() if len(parts) > 1 else ""
        if not rule_str:
            ctx.ui.add_system_message("用法: /permission add <规则> <效果>")
            return
        from mewcode.permissions.rules import Rule, parse_rule
        rule_parts = rule_str.rsplit(None, 1)
        if len(rule_parts) < 2 or rule_parts[1] not in ("allow", "deny"):
            ctx.ui.add_system_message(
                "用法: /permission add <Tool(pattern)> <allow|deny>\n"
                "示例: /permission add Bash(git*) allow"
            )
            return
        try:
            rule = parse_rule(rule_parts[0], rule_parts[1])
        except ValueError as e:
            ctx.ui.add_system_message(str(e))
            return
        checker = ctx.agent.permission_checker
        if checker and checker.rule_engine:
            checker.rule_engine.append_local_rule(rule)
            ctx.ui.add_system_message(f"规则已添加: {rule.tool_name}({rule.pattern}) → {rule.effect}")
        else:
            ctx.ui.add_system_message("规则引擎未初始化")


    elif sub == "reset":
        checker = ctx.agent.permission_checker
        if checker and checker.rule_engine and checker.rule_engine._local_path:
            path = checker.rule_engine._local_path
            if path.exists():
                path.write_text("", encoding="utf-8")
            ctx.ui.add_system_message("本地规则已清空")
        else:
            ctx.ui.add_system_message("无本地规则文件")

    else:
        ctx.ui.add_system_message(
            "用法: /permission [mode <模式> | rules | add <规则> <效果> | reset]"
        )

async def handle_session(ctx: CommandContext) -> None:
    sm = ctx.session_manager
    if sm is None:
        ctx.ui.add_system_message("会话管理器未初始化")
        return

    parts = ctx.args.split(None, 1)
    sub = parts[0] if parts else ""

    if sub == "":
        if ctx.session:
            m = ctx.session.meta
            ts = m.last_active.strftime("%Y-%m-%d %H:%M")
            ctx.ui.add_system_message(
                f"当前会话: {m.id}\n"
                f"  标题: {m.title or '(未命名)'}\n"
                f"  消息: {m.message_count} 条\n"
                f"  Token: {m.total_tokens:,}\n"
                f"  最后活跃: {ts}"
            )
        else:
            ctx.ui.add_system_message("当前没有活跃会话")
        return

    if sub == "list":
        metas = sm.list()
        if not metas:
            ctx.ui.add_system_message("没有已保存的会话。")
            return
        lines: list[str] = ["会话列表："]
        for m in metas[:10]:
            ts = m.last_active.strftime("%Y-%m-%d %H:%M")
            title = m.title or "(未命名)"
            lines.append(f"  {m.id}  {title}  [{m.message_count} msgs, {ts}]")
        ctx.ui.add_system_message("\n".join(lines))

    elif sub == "resume":
        session_id = parts[1].strip() if len(parts) > 1 else ""
        if not session_id:
            metas = sm.list()
            if not metas:
                ctx.ui.add_system_message("没有已保存的会话。")
                return
            lines: list[str] = ["可恢复的会话（使用 /session resume <id> 或 /session resume <序号>）："]
            for i, m in enumerate(metas[:15], 1):
                ts = m.last_active.strftime("%Y-%m-%d %H:%M")
                title = m.title or "(未命名)"
                lines.append(f"  {i}. [{m.id[:8]}]  {title}  ({m.message_count} msgs, {ts})")
            ctx.ui.add_system_message("\n".join(lines))
            ctx.config["_resume_candidates"] = [m.id for m in metas[:15]]
            return
        candidates = ctx.config.get("_resume_candidates", [])
        if session_id.isdigit() and candidates:
            idx = int(session_id) - 1
            if 0 <= idx < len(candidates):
                session_id = candidates[idx]
        result = sm.resume(session_id)
        if result is None:
            ctx.ui.add_system_message(f"会话未找到: {session_id}")
            return
        if ctx.session:
            ctx.session.close()
        ctx.config["set_session"](result.session)
        conv = ConversationManager()
        for msg in result.messages:
            conv.history.append(msg)
        ctx.config["set_conversation"](conv)
        if ctx.agent:
            ctx.agent._loop_count = 0
        await ctx.config["render_restored"](result.messages)
        ctx.ui.add_system_message(
            f"会话已恢复: {session_id} ({result.session.meta.message_count} msgs)"
        )


    elif sub == "new":
        if ctx.session:
            ctx.session.close()
        new_session = sm.create()
        ctx.config["set_session"](new_session)
        ctx.config["set_conversation"](ConversationManager())
        if ctx.agent:
            ctx.agent._loop_count = 0
        ctx.config["clear_chat"]()
        ctx.ui.add_system_message(f"新会话已创建: {new_session.session_id}")

    elif sub == "delete":
        session_id = parts[1].strip() if len(parts) > 1 else ""
        if not session_id:
            ctx.ui.add_system_message("用法: /session delete <id>")
            return
        if ctx.session and ctx.session.session_id == session_id:
            ctx.ui.add_system_message("不能删除当前活跃的会话。")
            return
        if sm.delete(session_id):
            ctx.ui.add_system_message(f"会话已删除: {session_id}")
        else:
            ctx.ui.add_system_message(f"会话未找到: {session_id}")


    else:
        ctx.ui.add_system_message(
            "用法: /session [list | resume <id> | new | delete <id>]"
        )

