def validate_profile(request: SubmitRequest, settings: Settings) -> None:
    if PROFILES.get(request.solver_profile) != request.analysis_type:
        raise AgentError("SUBMIT_REJECTED", "Unknown or incompatible solver profile")
    if request.analysis_type not in settings.solver_tags:
        raise AgentError("SUBMIT_REJECTED", "Node does not support the requested analysis")
    if (
        request.resource.cpu > settings.cpu_total
        or request.resource.memory_gb > settings.memory_total_gb
    ):
        raise AgentError("SUBMIT_REJECTED", "Requested resources exceed node capacity")

_ADAPTERS: dict[str, SolverAdapter] = {
    "STRUCTURE": MockOptiStructAdapter(),
    "NVH": MockNvhAdapter(),
    "CRASH": MockCrashAdapter(),
    "CFD": MockCfdAdapter(),
}

def public_solver(analysis: str) -> SolverAdapter:
    if analysis not in _ADAPTERS:
        raise AgentError("SUBMIT_REJECTED", "Unknown public Solver adapter")
    return _ADAPTERS[analysis]

def __init__(self, manager: ExecutionManager):
    self.manager = manager
    self.generation = uuid.uuid4().hex
    self.cursors = {False: "", True: ""}
    self._slots = asyncio.Semaphore(MAX_CONCURRENCY)

async def callback_loop(manager: ExecutionManager) -> None:
    """Dedicated bounded HTTP loop; failure does not block heartbeat or Agent API requests."""
    notifier = CallbackNotifier(manager)
    async with httpx.AsyncClient(
        timeout=3,
        trust_env=False,
        follow_redirects=False,
        limits=httpx.Limits(
            max_connections=MAX_CONCURRENCY, max_keepalive_connections=MAX_CONCURRENCY
        ),
    ) as client:
        while True:
            if manager.settings.backend_url:
                try:
                    await notifier.scan(client)
                except Exception as error:
                    logger.warning(
                        "nodeId=%s callback scan deferred: %s",
                        manager.settings.node_id,
                        type(error).__name__,
                    )
            await asyncio.sleep(manager.settings.callback_interval)

def __init__(self, settings: Settings):
    self.settings = settings
    self.registry = ProcessRegistry(settings.registry_path)
    self._launch_lock = threading.RLock()
    self._children: dict[int, subprocess.Popen] = {}

@staticmethod
def _matching_process(pid: int | None, create_time: float | None) -> psutil.Process | None:
    if pid is None or create_time is None:
        return None
    try:
        process = psutil.Process(pid)
        if (
            abs(process.create_time() - create_time) > 0.001
            or process.status() == psutil.STATUS_ZOMBIE
        ):
            return None
        return process
    except (psutil.NoSuchProcess, psutil.AccessDenied):
        return None

def query(self, external_id: str) -> dict:
    row = self.registry.by_external(external_id)
    if not row:
        raise AgentError("EXECUTION_NOT_FOUND", "Execution is not present on this node", 404)
    payload = json.loads(row["payload_json"])
    if payload["state"] not in TERMINAL:
        state_file = Path(row["workspace"]) / "state.json"
        if state_file.is_file():
            try:
                child_state = json.loads(state_file.read_text(encoding="utf-8"))
                if child_state.get("externalExecutionId") == external_id:
                    payload = child_state
            except (OSError, ValueError):
                pass  # Atomic file writer makes this rare; preserve previous runtime facts.
        process = self._matching_process(payload.get("pid"), payload.get("createTime"))
        age = (datetime.now(UTC) - datetime.fromisoformat(row["created_at"])).total_seconds()
        if payload["state"] not in TERMINAL and not process and age > 5:
            payload.update(
                state="UNKNOWN", rawMessage="No matching live solver identity or terminal state"
            )
        self.registry.update_payload(row["request_id"], payload)
    for pid, child in list(self._children.items()):
        if child.poll() is not None:
            self._children.pop(pid, None)
    payload.pop("createTime", None)
    payload["cancelRequested"] = bool(row["cancel_requested"])
    return payload

def query_by_request(self, request_id: str) -> dict:
    row = self.registry.by_request(request_id)
    if not row:
        raise AgentError(
            "EXECUTION_NOT_FOUND", "Execution request is not present on this node", 404
        )
    return self.query(row["external_id"])

def cancel(self, external_id: str) -> dict:
    with self._launch_lock:
        payload = self.query(external_id)
        if payload["state"] in TERMINAL:
            return payload
        row = self.registry.by_external(external_id)
        self.registry.mark_cancel(row["request_id"])
        output = Path(row["workspace"])
        ensure_contained(self.settings.data_root, output)
        output.mkdir(parents=True, exist_ok=True)
        atomic_json(output / "cancel.request", {"requestedAt": utc_now()})
        # A cancellation marker also protects the window before a child's signal handler exists.
        process = self._matching_process(row["pid"], row["create_time"])
        if process and payload.get("startedAt"):
            try:
                if os.getpgid(process.pid) == process.pid:
                    os.killpg(process.pid, signal.SIGTERM)
            except ProcessLookupError:
                pass
        return self.query(external_id)

def ensure_contained(root: Path, path: Path) -> None:
    if not path.is_relative_to(root):
        raise AgentError("INPUT_INVALID", "Workspace is outside the configured data root")
    current = root
    if current.is_symlink():
        raise AgentError("INPUT_INVALID", "Symbolic links are not allowed in workspace paths")
    for part in path.relative_to(root).parts:
        if part in (".", ".."):
            raise AgentError("INPUT_INVALID", "Workspace traversal is not allowed")
        current /= part
        if current.is_symlink():
            raise AgentError("INPUT_INVALID", "Symbolic links are not allowed in workspace paths")

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for chunk in iter(lambda: stream.read(8192), b""):
            digest.update(chunk)
    return digest.hexdigest()

def aggregate_checksum(files: dict[str, str]) -> str:
    encoded = "".join(f"{name}:{files[name]}\n" for name in sorted(files)).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()

def verify_snapshot(request: SubmitRequest, data_root: Path) -> tuple[Path, dict]:
    workspace = Path(request.workspace)
    expected = data_root / "jobs" / request.job_no
    if not workspace.is_absolute() or workspace != expected or ".." in workspace.parts:
        raise AgentError("INPUT_INVALID", "Workspace must match the job under DATA_ROOT/jobs")
    ensure_contained(data_root, workspace)
    try:
        checksum_path = workspace / "input-checksums.json"
        ensure_contained(workspace, checksum_path)
        record = json.loads(checksum_path.read_text(encoding="utf-8"))
        files = record.get("files")
        if not isinstance(files, dict) or not files or "manifest.json" not in files:
            raise AgentError("INPUT_INVALID", "Snapshot checksum file map is invalid")
        actual: dict[str, str] = {}
        inputs = workspace / "input"
        ensure_contained(workspace, inputs)
        for name, checksum in files.items():
            relative = Path(name)
            if (
                not isinstance(name, str)
                or not name
                or relative.is_absolute()
                or any(part in (".", "..") for part in name.split("/"))
                or "\\" in name
                or ":" in name
                or "\0" in name
            ):
                raise AgentError("INPUT_INVALID", "Snapshot contains an unsafe relative path")
            path = inputs / relative
            ensure_contained(inputs, path)
            if not path.is_file() or sha256_file(path) != checksum:
                raise AgentError("INPUT_INVALID", "Immutable snapshot file checksum does not match")
            actual[name] = checksum
        snapshot_paths = list(inputs.rglob("*"))
        if any(path.is_symlink() for path in snapshot_paths):
            raise AgentError("INPUT_INVALID", "Symbolic links are not allowed in snapshots")
        if {str(p.relative_to(inputs)) for p in snapshot_paths if not p.is_dir()} != set(files):
            raise AgentError("INPUT_INVALID", "Snapshot contains unregistered files")
        aggregate = aggregate_checksum(actual)
        if aggregate != request.snapshot_checksum or aggregate != record.get("checksum"):
            raise AgentError(
                "INPUT_INVALID", "Immutable snapshot aggregate checksum does not match"
            )
        manifest = json.loads((inputs / "manifest.json").read_text(encoding="utf-8"))
        if (
            manifest.get("analysisType") != request.analysis_type
            or manifest.get("conditionCode") != request.condition_code
        ):
            raise AgentError(
                "INPUT_INVALID", "Snapshot analysis or condition does not match request"
            )
        parameters = manifest.get("parameters", {})
        if not isinstance(parameters, dict):
            raise AgentError("INPUT_INVALID", "Synthetic case parameters must be an object")
        scale = parameters.get("thicknessScale", 1)
        if (
            isinstance(scale, bool)
            or not isinstance(scale, int | float)
            or not math.isfinite(scale)
            or not 0 < scale <= 10
        ):
            raise AgentError(
                "INPUT_INVALID", "Synthetic thicknessScale must be finite and positive"
            )
        seed = parameters.get("seed", 42)
        subcase = parameters.get("subcase", 1)
        if type(seed) is not int or not 0 <= seed <= 2**32 - 1:
            raise AgentError("INPUT_INVALID", "Synthetic seed must be an unsigned 32-bit integer")
        if type(subcase) is not int or not 1 <= subcase <= 1000:
            raise AgentError("INPUT_INVALID", "Synthetic subcase must be an integer from 1 to 1000")
        return workspace, manifest
    except (OSError, ValueError, TypeError, AttributeError) as error:
        raise AgentError("INPUT_INVALID", "Input snapshot could not be verified") from error

async def heartbeat_loop(manager: ExecutionManager, control: dict[str, bool]) -> None:
    settings = manager.settings
    async with httpx.AsyncClient(timeout=3, trust_env=False) as client:
        while True:
            if control["enabled"] and settings.backend_url:
                try:
                    response = await client.post(
                        f"{settings.backend_url.rstrip('/')}/internal/v1/agents/{settings.node_id}/heartbeat",
                        json=await asyncio.to_thread(manager.node_status),
                        headers={"X-Service-Token": settings.service_token},
                    )
                    response.raise_for_status()
                except httpx.HTTPError as error:
                    logger.warning(
                        "nodeId=%s heartbeat unavailable: %s",
                        settings.node_id,
                        type(error).__name__,
                    )
            await asyncio.sleep(settings.heartbeat_interval)

