def table(current, headers, rows, x=0.5, y=1.7, width=12.3, height=4.8):
    shape = current.shapes.add_table(
        len(rows) + 1, len(headers), Inches(x), Inches(y), Inches(width), Inches(height)
    )
    for row_index, row in enumerate([headers, *rows]):
        for column, value in enumerate(row):
            cell = shape.table.cell(row_index, column)
            cell.text = str(value) if value is not None else "N/A"
            for paragraph in cell.text_frame.paragraphs:
                paragraph.font.size = Pt(13)

def fingerprint(payload):
    return hashlib.sha256(
        json.dumps(
            payload, sort_keys=True, ensure_ascii=False, separators=(",", ":"), allow_nan=False
        ).encode()
    ).hexdigest()

def __init__(self, settings):
    self.settings = settings
    self.processor = MockHyperViewPostProcessor()
    self.generator = PptxDraftReportGenerator()
    self.faults = {"post": 0, "report": 0}
    self.delays = {"post": 0, "report": 0}
    self.fault_jobs = {"post": None, "report": None}
    self.fault_lock = threading.Lock()

def fault(self, stage, count, delay=0, job_no=None):
    with self.fault_lock:
        self.faults[stage] = count
        self.delays[stage] = delay
        self.fault_jobs[stage] = job_no
    return {"stage": stage, "failuresRemaining": count, "delaySeconds": delay, "jobNo": job_no}

def render(self, request, stage):
    payload = request.model_dump(by_alias=True, mode="json")
    root = self.settings.data_root
    job = root / "jobs" / request.job_no
    version = request.post_version if stage == "post" else request.report_version
    parent = job / ("derived" if stage == "post" else "reports") / request.parser_version
    output = parent / f"{stage}-v{version}"
    ensure_contained(root, output)
    parent.mkdir(parents=True, exist_ok=True)
    ensure_contained(root, output)
    descriptor = os.open(
        parent / f".{stage}-v{version}.lock", os.O_CREAT | os.O_RDWR | os.O_NOFOLLOW, 0o600
    )
    with os.fdopen(descriptor, "a") as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        raw = verify_source(self.settings, request)
        expected = fingerprint(payload)
        if output.exists():
            return self._replay(output, request, stage, expected)
        with self.fault_lock:
            applies = self.fault_jobs[stage] is None or self.fault_jobs[stage] == request.job_no
            delay = self.delays[stage] if applies else 0
            if applies and self.faults[stage] > 0:
                self.faults[stage] -= 1
                raise AgentError(
                    "MOCK_RENDER_FAILURE", "Injected synthetic render failure", 503
                )
        if delay:
            time.sleep(delay)
        temporary = Path(tempfile.mkdtemp(prefix=f".{stage}-", dir=parent))
        try:
            extra = {}
            if stage == "post":
                self.processor.process(request, raw, temporary)
                items = []
                for spec in request.specs:
                    metadata = spec.model_dump(by_alias=True)
                    metadata["synthetic"] = True
                    items.append(
                        self._descriptor(
                            temporary / spec.output_name,
                            output / spec.output_name,
                            "IMAGE",
                            "image/png",
                            metadata,
                        )
                    )
            else:
                post = (
                    job / "derived" / request.parser_version / f"post-v{request.post_version}"
                )
                manifest, checksum = load_json(root, post / "post-manifest.json")
                if (
                    checksum != request.post_manifest_checksum
                    or manifest.get("requestFingerprint") != request.post_request_fingerprint
                ):
                    fail("Selected post manifest mismatch")
                source = manifest.get("request", {})
                common = set(payload) - {
                    "reportVersion",
                    "templateCode",
                    "templateVersion",
                    "generatedAt",
                    "postManifestChecksum",
                    "postRequestFingerprint",
                }
                if any(source.get(key) != payload[key] for key in common):
                    fail("Report source differs from selected post context")
                images = self._verify_outputs(post, manifest, "post")
                slides = self.generator.generate(request, images, temporary / "report.pptx")
                extra = {
                    "reportStatus": "DRAFT",
                    "slideCount": slides,
                    "imageChecksums": {
                        name: hashlib.sha256(data).hexdigest() for name, data in images.items()
                    },
                }
                items = [
                    self._descriptor(
                        temporary / "report.pptx",
                        output / "report.pptx",
                        "REPORT_PPTX",
                        "application/vnd.openxmlformats-officedocument.presentationml.presentation",
                        {
                            "conditionCode": request.condition_code,
                            "subcase": request.subcase,
                            **extra,
                        },
                    )
                ]
            for path in temporary.iterdir():
                with path.open("rb") as stream:
                    os.fsync(stream.fileno())
            manifest = {
                "request": payload,
                "requestFingerprint": expected,
                "status": "COMPLETE",
                "artifacts": items,
                **extra,
            }
            name = f"{stage}-manifest.json"
            with (temporary / name).open("x", encoding="utf-8") as stream:
                json.dump(manifest, stream, sort_keys=True, ensure_ascii=False, allow_nan=False)
                stream.flush()
                os.fsync(stream.fileno())
            self._verify_outputs(temporary, manifest, stage)
            if output.exists():
                raise AgentError(
                    "IDEMPOTENCY_CONFLICT", "Stage output appeared during publication", 409
                )
            os.rename(temporary, output)
            directory = os.open(parent, os.O_RDONLY | os.O_DIRECTORY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        finally:
            if temporary.exists():
                shutil.rmtree(temporary)
        return self._replay(output, request, stage, expected)

def _verify_outputs(self, directory, manifest, stage):
    expected = (
        {"contour.png", "mode-shape.png", "comparison.png", "curve.png"}
        if stage == "post"
        else {"report.pptx"}
    )
    items = manifest.get("artifacts", [])
    if {row.get("fileName") for row in items} != expected or len(items) != len(expected):
        fail("Stage artifact set is invalid")
    actual = {path.name for path in directory.iterdir()}
    if actual not in (expected, expected | {f"{stage}-manifest.json"}):
        fail("Unexpected immutable stage files")
    contents = {}
    for row in items:
        data = read_bytes(self.settings.data_root, directory / row["fileName"])
        if len(data) != row["sizeBytes"] or hashlib.sha256(data).hexdigest() != row["checksum"]:
            fail("Immutable stage artifact checksum mismatch")
        if stage == "post":
            with Image.open(io.BytesIO(data)) as image:
                if (
                    image.format != "PNG"
                    or image.width < 400
                    or image.height < 300
                    or image.width * image.height > 8_000_000
                ):
                    fail("PNG dimensions are invalid")
                image.verify()
        else:
            presentation = Presentation(io.BytesIO(data))
            if len(presentation.slides) < 4 or manifest.get("reportStatus") != "DRAFT":
                fail("Draft PPTX is incomplete")
        contents[row["fileName"]] = data
    return contents

def read_bytes(root: Path, path: Path, limit=32 * 1024 * 1024):
    ensure_contained(root, path)
    try:
        descriptor = os.open(path, os.O_RDONLY | os.O_NOFOLLOW)
        with os.fdopen(descriptor, "rb") as stream:
            if not path.is_file() or os.fstat(stream.fileno()).st_size > limit:
                fail("Source size/type is invalid")
            data = stream.read(limit + 1)
        if len(data) > limit:
            fail("Source exceeds size limit")
        ensure_contained(root, path)
        return data
    except OSError as error:
        raise AgentError("RENDER_SOURCE_INVALID", "Source file unavailable", 409) from error

def unique(pairs):
    result = {}
    for key, value in pairs:
        if key in result:
            fail("Duplicate JSON key")
        result[key] = value
    return result

encoded = read_bytes(root, path, 2 * 1024 * 1024)
try:
    value = json.loads(
        encoded,
        parse_float=Decimal,
        parse_constant=lambda _: fail("Nonfinite JSON"),
        object_pairs_hook=unique,
    )
except (ValueError, TypeError) as error:
    raise AgentError("RENDER_SOURCE_INVALID", "Invalid source JSON", 409) from error
if not isinstance(value, dict):
    fail("JSON source must be an object")
return value, hashlib.sha256(encoded).hexdigest()

def verify_source(settings, request):
    root = settings.data_root
    job = root / "jobs" / request.job_no
    workspace = job / "executions" / request.execution_request_id
    config, _ = load_json(root, workspace / "execution-config.json")
    state, _ = load_json(root, workspace / "state.json")
    for key, expected in {
        "jobNo": request.job_no,
        "executionRequestId": request.execution_request_id,
        "externalExecutionId": request.external_execution_id,
        "nodeId": settings.node_id,
        "workspace": str(workspace),
        "inputDirectory": str(job / "input"),
        "analysisType": request.analysis_type,
        "conditionCode": request.condition_code,
        "snapshotChecksum": request.snapshot_checksum,
    }.items():
        if config.get(key) != expected:
            fail("Execution configuration identity mismatch: " + key)
    if request.node_id != settings.node_id:
        fail("Wrong rendering node")
    for key, expected in {
        "state": "SUCCESS",
        "exitCode": 0,
        "executionRequestId": request.execution_request_id,
        "externalExecutionId": request.external_execution_id,
        "workspace": str(workspace),
        "pid": request.pid,
        "processIdentity": request.process_identity,
    }.items():
        if state.get(key) != expected:
            fail("Successful execution identity mismatch: " + key)
    submit_data = {
        (field.alias or name): config[field.alias or name]
        for name, field in SubmitRequest.model_fields.items()
    }
    submit_data["workspace"] = str(job)
    submit = SubmitRequest.model_validate(submit_data)
    verify_snapshot(submit, root)
    manifest, _ = load_json(root, job / "input" / "manifest.json")
    parameters = manifest.get("parameters", {})
    raw, raw_sha = load_json(root, workspace / "raw_result.json")
    result, result_sha = load_json(root, job / "derived" / request.parser_version / "result.json")
    if raw_sha != request.raw_checksum or result_sha != request.result_json_checksum:
        fail("Selected result checksum mismatch")
    if (
        parameters != config.get("parameters")
        or parameters != raw.get("parameters")
        or raw.get("seed")
        != (
            config["mock"].get("seed")
            if config["mock"].get("seed") is not None
            else parameters.get("seed", 42)
        )
    ):
        fail("Synthetic parameter identity mismatch")
    for document in (raw, result):
        if (
            document.get("analysisType"),
            document.get("conditionCode"),
            document.get("subcase"),
        ) != (request.analysis_type, request.condition_code, request.subcase):
            fail("Source condition/subcase mismatch")
    for key, expected in {
        "jobNo": request.job_no,
        "executionId": request.execution_id,
        "executionRequestId": request.execution_request_id,
        "parserVersion": request.parser_version,
        "rawChecksum": request.raw_checksum,
        "maturity": request.context.maturity,
    }.items():
        if result.get(key) != expected:
            fail("Selected parser identity mismatch: " + key)
    if parameters.get("subcase", 1) != request.subcase:
        fail("Snapshot subcase mismatch")
    exported = {row["metricCode"]: row for row in result.get("metrics", [])}
    if len(exported) != len(request.metrics):
        fail("Incomplete canonical metric set")
    for metric in request.metrics:
        row = exported.get(metric.metric_code, {})
        expected = metric.model_dump(by_alias=True)
        for key, value in expected.items():
            actual = row.get(key)
            if key == "valueNum" and value is not None:
                if actual is None or Decimal(str(actual)) != Decimal(value):
                    fail("Canonical numeric value mismatch")
            elif actual != value:
                fail("Canonical metric metadata mismatch: " + key)
    if (
        request.parser_version == "v2"
        and result.get("provenance", {}).get("snapshotChecksum") != request.snapshot_checksum
    ):
        fail("Parser provenance mismatch")
    return raw

