export const getAuthorization = () => authorization

export const api = axios.create({
  baseURL: '/api/v1',
  timeout: 15_000,
  headers: { Accept: 'application/json' },
})

api.interceptors.request.use(config => {
  if (authorization) config.headers.Authorization = authorization
  return config
})
api.interceptors.response.use(response => response, error => {
  if (error.response?.status === 401) window.dispatchEvent(new Event('cae-session-expired'))
  return Promise.reject(error)
})

export function errorText(error: unknown): string {
  if (axios.isAxiosError(error)) {
    const data = error.response?.data as {message?: string; code?: string; traceId?: string} | undefined
    if (data) return `${data.message ?? '请求失败'}${data.code ? ` · ${data.code}` : ''}${data.traceId ? ` · Trace ${data.traceId}` : ''}`
    return error.code === 'ECONNABORTED' ? '请求超时，请使用原请求重试。' : '网络暂不可用，请重试。'
  }
  return error instanceof Error ? error.message : '操作失败，请重试。'
}

export async function download(url: string, name: string) {
  const response = await api.get(url.startsWith('/api/v1/') ? url.slice(7) : url, {responseType: 'blob'})
  const blob = URL.createObjectURL(response.data)
  try { const anchor = document.createElement('a'); anchor.href = blob; anchor.download = name; anchor.click() }
  finally { setTimeout(() => URL.revokeObjectURL(blob), 1000) }
}

export function time(value?: string | null) {
  return value ? new Intl.DateTimeFormat('zh-CN', {timeZone: 'Asia/Shanghai', dateStyle: 'short', timeStyle: 'medium', hour12: false}).format(new Date(value)) : '—'
}

const run = async () => {
  let failures = 0
  while (!stopped) {
    controller = new AbortController()
    try {
      state('连接中')
      const headers: Record<string, string> = {Authorization: getAuthorization(), Accept: 'text/event-stream'}
      if (lastId) headers['Last-Event-ID'] = lastId
      const response = await fetch('/api/v1/events/stream?' + new URLSearchParams(params), {headers, signal: controller.signal})
      if (response.status === 401 || response.status === 403) { state('无访问权限'); if (response.status === 401) window.dispatchEvent(new Event('cae-session-expired')); stop(); return }
      if (!response.ok || !response.body) throw new Error('Event stream unavailable')
      state('实时连接'); failures = 0; refresh()
      const reader = response.body.getReader(); const decoder = new TextDecoder(); let pending = ''; let event = ''; let data = ''
      while (!stopped) {
        const result = await reader.read(); if (result.done) break
        pending += decoder.decode(result.value, {stream: true})
        let newline: number
        while ((newline = pending.indexOf('\n')) >= 0) {
          const line = pending.slice(0, newline).replace(/\r$/, ''); pending = pending.slice(newline + 1)
          if (!line) { if (data && (event === 'ready' || event === 'job')) refresh(); event = ''; data = ''; continue }
          if (line.startsWith('id:')) lastId = line.slice(3).trim()
          if (line.startsWith('event:')) event = line.slice(6).trim()
          if (line.startsWith('data:')) data += line.slice(5).trimStart() + '\n'
        }
      }
    } catch (error) { if (stopped || (error instanceof DOMException && error.name === 'AbortError')) return }
    if (!stopped) { state('重连中 · 轮询兜底'); await new Promise(resolve => setTimeout(resolve, Math.min(15_000, 1000 * 2 ** Math.min(failures++, 4)) + Math.random() * 300)) }
  }
}

  void run()
  return stop
}

import { defineStore } from 'pinia'
import { ref } from 'vue'
import { api, setAuthorization } from '../api/client'

export const useSessionStore = defineStore('session', () => {
  const username = ref<string | null>(null)
  const roles = ref<string[]>([])

async function login(name: string, password: string) {
  const bytes = new TextEncoder().encode(`${name}:${password}`)
  setAuthorization('Basic ' + btoa(String.fromCharCode(...bytes)))
  try { const response = await api.get<{username: string; roles: string[]}>('/auth/me'); username.value = response.data.username; roles.value = response.data.roles }
  catch (error) { logout(); throw error }
}

  const admin = () => roles.value.includes('ADMIN')
  const lead = () => admin() || roles.value.includes('PROJECT_LEAD')
  return { username, roles, login, logout, admin, lead }
})

