import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/** Only configured Agent URLs can receive control-plane requests and service credentials. */
@Component
public class ComputeAgentClient {
  private static final Set<String> REMOTE_STATES =
      Set.of(
          "SUBMITTED", "RUNNING", "SUCCESS", "RUNTIME_FAILED", "TIMEOUT", "CANCELLED", "UNKNOWN");
  private final Map<String, URI> nodes;
  private final String token;
  private final Duration timeout;
  private final JsonCodec json;
  private final HttpClient client;

  @Autowired
  public ComputeAgentClient(
      @Value(
              "${WORKER_URLS:node-a=http://127.0.0.1:8001,node-b=http://127.0.0.1:8002,node-c=http://127.0.0.1:8003}")
          String configuredNodes,
      @Value("${SERVICE_TOKEN:demo-service-token}") String token,
      @Value("${cae.agent.request-timeout-ms:2000}") long timeoutMs,
      JsonCodec json) {
    this(parseNodes(configuredNodes), token, Duration.ofMillis(timeoutMs), json);
  }

public ComputeAgentClient(
    Map<String, URI> nodes, String token, Duration timeout, JsonCodec json) {
  if (nodes.isEmpty()
      || token == null
      || token.isBlank()
      || timeout.isZero()
      || timeout.isNegative())
    throw new IllegalArgumentException("Agent configuration is incomplete");
  nodes.forEach(
      (id, uri) -> {
        identifier(id);
        if (!("http".equals(uri.getScheme()) || "https".equals(uri.getScheme()))
            || uri.getHost() == null
            || uri.getUserInfo() != null
            || uri.getQuery() != null
            || uri.getFragment() != null
            || !(uri.getPath().isEmpty() || uri.getPath().equals("/")))
          throw new IllegalArgumentException("Agent base URL must be a plain HTTP(S) origin");
      });
  this.nodes = Map.copyOf(nodes);
  this.token = token;
  this.timeout = timeout;
  this.json = json;
  this.client =
      HttpClient.newBuilder()
          .connectTimeout(timeout)
          .followRedirects(HttpClient.Redirect.NEVER)
          .build();
}

public Map<String, URI> nodes() {
  return nodes;
}

public Map<String, Object> submit(String nodeId, Map<String, Object> request) {
  Map<String, Object> result = request(nodeId, "POST", "/worker/v1/jobs/submit", request, true);
  if (!Boolean.TRUE.equals(result.get("accepted"))) throw invalidResponse(true);
  validateExecution(result, null, null, true);
  return result;
}

public Map<String, Object> query(String nodeId, String externalExecutionId) {
  Map<String, Object> result =
      request(nodeId, "GET", "/worker/v1/jobs/" + identifier(externalExecutionId), null, false);
  validateExecution(result, externalExecutionId, null, false);
  return result;
}

public Map<String, Object> queryByRequest(String nodeId, String executionRequestId) {
  Map<String, Object> result =
      request(
          nodeId,
          "GET",
          "/worker/v1/jobs/by-request/" + identifier(executionRequestId),
          null,
          false);
  validateExecution(result, null, executionRequestId, false);
  return result;
}

public Map<String, Object> cancel(String nodeId, String externalExecutionId) {
  Map<String, Object> result =
      request(
          nodeId,
          "POST",
          "/worker/v1/jobs/" + identifier(externalExecutionId) + "/cancel",
          Map.of(),
          true);
  validateExecution(result, externalExecutionId, null, true);
  return result;
}

public Map<String, Object> nodeStatus(String nodeId) {
  Map<String, Object> result = request(nodeId, "GET", "/worker/v1/node/status", null, false);
  if (!nodeId.equals(result.get("nodeId"))) throw invalidResponse(false);
  return result;
}

private static void validateExecution(
    Map<String, Object> result, String externalId, String requestId, boolean mutating) {
  Object actualId = result.get("externalExecutionId");
  Object state = result.get("state");
  if (!(actualId instanceof String id)
      || !id.matches("[A-Za-z0-9][A-Za-z0-9_-]{0,127}")
      || !(state instanceof String status)
      || !REMOTE_STATES.contains(status)
      || (externalId != null && !externalId.equals(id))
      || (requestId != null && !requestId.equals(result.get("executionRequestId"))))
    throw invalidResponse(mutating);
}

private static AgentException invalidResponse(boolean mutating) {
  return new AgentException(
      FailureCode.UNKNOWN_REMOTE_STATE,
      "Agent response violates the execution protocol",
      200,
      mutating);
}

private Map<String, Object> request(
    String nodeId, String method, String path, Map<String, Object> body, boolean mutating) {
  URI origin = nodes.get(nodeId);
  if (origin == null) throw ApiException.invalid("Unknown compute node");
  HttpRequest.Builder request =
      HttpRequest.newBuilder(origin.resolve(path))
          .timeout(timeout)
          .header("X-Service-Token", token)
          .header("Accept", "application/json");
  if (body == null) request.GET();
  else
    request
        .header("Content-Type", "application/json")
        .method(method, HttpRequest.BodyPublishers.ofString(json.write(body)));
  try {
    HttpResponse<String> response =
        client.send(request.build(), HttpResponse.BodyHandlers.ofString());
    if (response.statusCode() < 200 || response.statusCode() >= 300) {
      boolean uncertain = mutating && response.statusCode() >= 500;
      throw new AgentException(
          uncertain ? FailureCode.UNKNOWN_REMOTE_STATE : FailureCode.SUBMIT_REJECTED,
          "Agent returned HTTP " + response.statusCode(),
          response.statusCode(),
          uncertain);
    }
    try {
      Map<String, Object> result = json.readMap(response.body());
      if (result == null || result.isEmpty())
        throw new IllegalArgumentException("Empty Agent response");
      return result;
    } catch (IllegalArgumentException e) {
      throw new AgentException(
          FailureCode.UNKNOWN_REMOTE_STATE,
          "Agent response is not a JSON object",
          response.statusCode(),
          mutating);
    }
  } catch (HttpTimeoutException e) {
    throw new AgentException(FailureCode.AGENT_TIMEOUT, "Agent request timed out", 0, mutating);
  } catch (InterruptedException e) {
    Thread.currentThread().interrupt();
    throw new AgentException(
        FailureCode.UNKNOWN_REMOTE_STATE, "Agent request interrupted", 0, mutating);
  } catch (IOException e) {
    throw new AgentException(
        FailureCode.NODE_OFFLINE, "Agent connection unavailable", 0, mutating);
  }
}

private static Map<String, URI> parseNodes(String configuration) {
  Map<String, URI> nodes = new LinkedHashMap<>();
  for (String entry : configuration.split(",")) {
    String[] pair = entry.trim().split("=", 2);
    if (pair.length != 2 || nodes.putIfAbsent(pair[0], URI.create(pair[1])) != null)
      throw new IllegalArgumentException("Agent nodes must be unique node-id=URL entries");
  }
  return nodes;
}

private static String identifier(String value) {
  if (value == null || !value.matches("[A-Za-z0-9][A-Za-z0-9_-]{0,127}"))
    throw ApiException.invalid("Invalid Agent identifier");
  return value;
}

package com.example.cae.artifact;

import com.example.cae.auth.ProjectAccess;
import com.example.cae.common.ApiException;
import com.example.cae.common.SqlRows;
import com.example.cae.job.repository.JobRepository;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import org.springframework.core.io.InputStreamResource;
import org.springframework.http.ContentDisposition;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RestController;

@RestController
public class ArtifactController {
  private final ArtifactRepository artifacts;
  private final ArtifactFileStore files;
  private final JobRepository jobs;
  private final ProjectAccess access;

public ArtifactController(
    ArtifactRepository artifacts,
    ArtifactFileStore files,
    JobRepository jobs,
    ProjectAccess access) {
  this.artifacts = artifacts;
  this.files = files;
  this.jobs = jobs;
  this.access = access;
}

@GetMapping("/api/v1/jobs/{jobNo}/artifacts")
public List<Map<String, Object>> list(Authentication user, @PathVariable String jobNo) {
  Map<String, Object> job = jobs.findByNo(jobNo);
  access.requireJob(user, job);
  return artifacts.list(SqlRows.id(job));
}

@GetMapping("/api/v1/jobs/{jobNo}/artifacts/{artifactId}/download")
public ResponseEntity<InputStreamResource> downloadForJob(
    Authentication user, @PathVariable String jobNo, @PathVariable long artifactId) {
  Map<String, Object> job = jobs.findByNo(jobNo);
  access.requireJob(user, job);
  Map<String, Object> artifact = artifacts.find(artifactId);
  if (((Number) artifact.get("jobId")).longValue() != SqlRows.id(job))
    throw ApiException.notFound("Artifact");
  return stream(artifact, job);
}

@GetMapping("/api/v1/artifacts/{artifactId}/download")
public ResponseEntity<InputStreamResource> download(
    Authentication user, @PathVariable long artifactId) {
  Map<String, Object> artifact = artifacts.find(artifactId);
  Map<String, Object> job = jobs.findById(((Number) artifact.get("jobId")).longValue());
  access.requireJob(user, job);
  return stream(artifact, job);
}

private ResponseEntity<InputStreamResource> stream(
    Map<String, Object> artifact, Map<String, Object> job) {
  try {
    files.requireJob(artifact.get("uri").toString(), job.get("jobNo").toString());
    MediaType type = MediaType.parseMediaType(artifact.get("contentType").toString());
    long size = ((Number) artifact.get("sizeBytes")).longValue();
    String disposition =
        ContentDisposition.attachment()
            .filename(artifact.get("fileName").toString(), StandardCharsets.UTF_8)
            .build()
            .toString();
    var response =
        ResponseEntity.ok()
            .contentType(type)
            .contentLength(size)
            .header(HttpHeaders.CONTENT_DISPOSITION, disposition)
            .header("X-Content-Type-Options", "nosniff");
    return response.body(new InputStreamResource(files.openVerified(artifact)));
  } catch (IllegalArgumentException invalid) {
    throw ApiException.conflict("Artifact is unavailable or its integrity check failed");
  }
}

package com.example.cae.artifact;

import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.DeserializationFeature;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.ByteArrayOutputStream;
import java.io.FilterInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.nio.ByteBuffer;
import java.nio.channels.SeekableByteChannel;
import java.nio.file.Files;
import java.nio.file.LinkOption;
import java.nio.file.Path;
import java.nio.file.StandardOpenOption;
import java.nio.file.attribute.BasicFileAttributes;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;
import java.util.Map;
import java.util.Set;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;

/** Only DATA_ROOT relative, regular files can be registered or served. */
@Service
public class ArtifactFileStore {
  public static final long JSON_LIMIT = 2 * 1024 * 1024;
  private final Path root;
  private final ObjectMapper mapper;

public ArtifactFileStore(@Value("${DATA_ROOT:../.data}") String dataRoot, ObjectMapper mapper) {
  root = Path.of(dataRoot).toAbsolutePath().normalize();
  this.mapper =
      mapper
          .copy()
          .enable(JsonParser.Feature.STRICT_DUPLICATE_DETECTION)
          .enable(DeserializationFeature.FAIL_ON_TRAILING_TOKENS);
}

public Path root() {
  return root;
}

public Path jobRoot(String jobNo) {
  if (jobNo == null || !jobNo.matches("CAE-[0-9]{8}-[0-9]{6,}"))
    throw new IllegalArgumentException("Unsafe Job workspace identity");
  return safe("jobs/" + jobNo);
}

public Path safe(String relative) {
  if (relative == null
      || relative.isBlank()
      || relative.startsWith("/")
      || relative.contains("\\")
      || relative.contains(":")
      || relative.indexOf('\0') >= 0
      || relative.length() > 500)
    throw new IllegalArgumentException("Unsafe artifact relative path");
  for (String part : relative.split("/", -1))
    if (part.isEmpty() || part.equals(".") || part.equals(".."))
      throw new IllegalArgumentException("Artifact traversal is not allowed");
  Path path = root.resolve(relative).normalize();
  check(path);
  return path;
}

public Path requireJob(String relative, String jobNo) {
  Path path = safe(relative);
  if (!path.startsWith(jobRoot(jobNo)) || path.equals(jobRoot(jobNo)))
    throw new IllegalArgumentException(
        "Artifact URI does not belong to the requested Job workspace");
  return path;
}

public void check(Path path) {
  if (!path.isAbsolute() || !path.normalize().equals(path) || !path.startsWith(root))
    throw new IllegalArgumentException("Artifact is outside DATA_ROOT");
  Path current = root;
  if (Files.isSymbolicLink(current))
    throw new IllegalArgumentException("DATA_ROOT cannot be a symbolic link");
  for (Path part : root.relativize(path)) {
    current = current.resolve(part);
    if (Files.isSymbolicLink(current))
      throw new IllegalArgumentException("Artifact symbolic links are forbidden");
  }
}

try (SeekableByteChannel channel = open(path)) {
  if (channel.size() > JSON_LIMIT)
    throw new IllegalArgumentException("Synthetic JSON exceeds 2 MiB");
  BasicFileAttributes before = attributes(path);
  ByteArrayOutputStream bytes = new ByteArrayOutputStream();
  ByteBuffer buffer = ByteBuffer.allocate(8192);
  while (channel.read(buffer) != -1) {
    buffer.flip();
    if ((long) bytes.size() + buffer.remaining() > JSON_LIMIT)
      throw new IllegalArgumentException("Synthetic JSON exceeds 2 MiB");
    bytes.write(buffer.array(), 0, buffer.remaining());
    buffer.clear();
  }
  byte[] encoded = bytes.toByteArray();
  check(path);
  BasicFileAttributes after = attributes(path);
  if (before.size() != encoded.length
      || before.size() != after.size()
      || !before.lastModifiedTime().equals(after.lastModifiedTime())
      || !java.util.Objects.equals(before.fileKey(), after.fileKey()))
    throw new IllegalArgumentException("Artifact changed during JSON reading");
  Map<String, Object> value =
      mapper.readValue(encoded, new TypeReference<Map<String, Object>>() {});
  return new JsonDocument(path, value, hex(encoded), encoded.length);
} catch (IOException error) {

    throw new IllegalArgumentException("Synthetic result JSON is unavailable or invalid", error);
  }
}

public FileDescriptor describe(Path path) {
  check(path);

try (SeekableByteChannel channel = open(path)) {
  BasicFileAttributes before = attributes(path);
  String checksum = digest(channel);
  check(path);
  BasicFileAttributes after = attributes(path);
  if (channel.size() != before.size()
      || before.size() != after.size()
      || !before.lastModifiedTime().equals(after.lastModifiedTime())
      || !java.util.Objects.equals(before.fileKey(), after.fileKey()))
    throw new IllegalArgumentException("Artifact changed during checksum calculation");
  return new FileDescriptor(
      root.relativize(path).toString().replace('\\', '/'),
      path.getFileName().toString(),
      before.size(),
      checksum);
} catch (IOException error) {

    throw new IllegalArgumentException("Artifact could not be read", error);
  }
}

public FileDescriptor writeImmutable(Path path, byte[] bytes) {
  check(path);
  String expected = hex(bytes);
  try {
    if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS)) {
      Files.createDirectories(path.getParent());
      check(path);
      Path temporary = Files.createTempFile(path.getParent(), ".result-", ".tmp");
      try {
        Files.write(temporary, bytes, StandardOpenOption.TRUNCATE_EXISTING);

try (var channel =
    java.nio.channels.FileChannel.open(temporary, StandardOpenOption.WRITE)) {
  channel.force(true);
}

        // A hard-link create is atomic and cannot overwrite an existing parser version.
        try {
          Files.createLink(path, temporary);
        } catch (java.nio.file.FileAlreadyExistsException concurrentWriter) {
          /* verify below */
        }
      } finally {
        Files.deleteIfExists(temporary);
      }
    }
    FileDescriptor existing = describe(path);
    if (existing.sizeBytes() != bytes.length || !existing.checksum().equals(expected))
      throw new IllegalArgumentException("Existing derived artifact cannot be overwritten");
    return existing;
  } catch (IOException error) {
    throw new IllegalArgumentException("Derived artifact could not be committed", error);
  }
}

public InputStream openVerified(Map<String, Object> artifact) {
  Path path = safe(artifact.get("uri").toString());
  Path temporary = null;
  Path directory = null;
  try (SeekableByteChannel channel = open(path)) {
    long size = ((Number) artifact.get("sizeBytes")).longValue();
    if (channel.size() != size) throw new IllegalArgumentException("Artifact size changed");
    directory = Files.createTempDirectory("cae-download-");
    temporary = Files.createTempFile(directory, "artifact-", ".tmp");
    MessageDigest digest = sha();
    long copied = 0;
    ByteBuffer buffer = ByteBuffer.allocate(8192);

try (var output = java.nio.channels.FileChannel.open(temporary, StandardOpenOption.WRITE)) {
  while (channel.read(buffer) != -1) {
    buffer.flip();
    copied += buffer.remaining();
    if (copied > size)
      throw new IllegalArgumentException("Artifact grew during download verification");
    digest.update(buffer.asReadOnlyBuffer());
    while (buffer.hasRemaining()) output.write(buffer);
    buffer.clear();
  }
  output.force(true);
}

if (copied != size
    || !HexFormat.of().formatHex(digest.digest()).equals(artifact.get("checksum")))
  throw new IllegalArgumentException(
      "Artifact checksum or size no longer matches its metadata");
check(path);
Path snapshot = temporary;
Path privateDirectory = directory;
InputStream source =
    Files.newInputStream(snapshot, StandardOpenOption.READ, LinkOption.NOFOLLOW_LINKS);
temporary = null;
directory = null;
// Return the private verified snapshot. An in-place source mutation cannot alter these bytes.
return new FilterInputStream(source) {

@Override
public void close() throws IOException {
  try {
    super.close();
  } finally {
    try {
      Files.deleteIfExists(snapshot);
    } finally {
      Files.deleteIfExists(privateDirectory);
    }
  }
}

    };
  } catch (RuntimeException | IOException error) {
    if (temporary != null)
      try {
        Files.deleteIfExists(temporary);
      } catch (IOException ignored) {
      }
    if (directory != null)
      try {
        Files.deleteIfExists(directory);
      } catch (IOException ignored) {
      }
    throw new IllegalArgumentException("Registered artifact is unavailable or changed", error);
  }
}

private SeekableByteChannel open(Path path) throws IOException {
  if (!attributes(path).isRegularFile())
    throw new IllegalArgumentException("Artifact must be a regular file");
  return Files.newByteChannel(path, Set.of(StandardOpenOption.READ, LinkOption.NOFOLLOW_LINKS));
}

private static BasicFileAttributes attributes(Path path) throws IOException {
  return Files.readAttributes(path, BasicFileAttributes.class, LinkOption.NOFOLLOW_LINKS);
}

private static String digest(SeekableByteChannel channel) throws IOException {
  MessageDigest digest = sha();
  ByteBuffer bytes = ByteBuffer.allocate(8192);
  while (channel.read(bytes) != -1) {
    bytes.flip();
    digest.update(bytes);
    bytes.clear();
  }
  return HexFormat.of().formatHex(digest.digest());
}

public static String hex(byte[] value) {
  return HexFormat.of().formatHex(sha().digest(value));
}

private static MessageDigest sha() {
  try {
    return MessageDigest.getInstance("SHA-256");
  } catch (NoSuchAlgorithmException impossible) {
    throw new IllegalStateException(impossible);
  }
}

package com.example.cae.artifact;

import com.example.cae.common.ApiException;
import com.example.cae.common.JsonCodec;
import com.example.cae.common.SqlRows;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Repository
public class ArtifactRepository {
  private final JdbcTemplate jdbc;
  private final JsonCodec json;
  private final ArtifactFileStore files;

public ArtifactRepository(JdbcTemplate jdbc, JsonCodec json, ArtifactFileStore files) {
  this.jdbc = jdbc;
  this.json = json;
  this.files = files;
}

  public Map<String, Object> find(long id) {
    return jdbc.query("SELECT * FROM cae_artifact WHERE id=?", SqlRows.MAPPER, id).stream()
        .findFirst()
        .map(this::decode)
        .orElseThrow(() -> ApiException.notFound("Artifact"));
  }

  public List<Map<String, Object>> list(long jobId) {
    return jdbc
        .query("SELECT * FROM cae_artifact WHERE job_id=? ORDER BY id", SqlRows.MAPPER, jobId)
        .stream()
        .map(this::decode)
        .toList();
  }

  @Transactional(propagation = Propagation.MANDATORY)
  public Map<String, Object> register(
      long jobId,
      long executionId,
      Long parseRecordId,
      String parserVersion,
      int stageVersion,
      String artifactType,
      ArtifactFileStore.FileDescriptor file,
      String contentType,
      Map<String, Object> metadata) {
    List<Map<String, Object>> identities =
        jdbc.query(
            "SELECT j.job_no,e.job_id FROM cae_job_execution e JOIN cae_job j ON j.id=e.job_id WHERE e.id=? AND e.job_id=?",
            SqlRows.MAPPER,
            executionId,
            jobId);
    if (identities.isEmpty())
      throw new IllegalArgumentException("Artifact execution does not belong to the Job");
    files.requireJob(file.uri(), identities.get(0).get("jobNo").toString());
    if (parseRecordId != null
        && jdbc.queryForObject(
                "SELECT COUNT(*) FROM cae_result_parse_record WHERE id=? AND job_id=? AND execution_id=? AND parser_version=?",
                Integer.class,
                parseRecordId,
                jobId,
                executionId,
                parserVersion)
            != 1)
      throw new IllegalArgumentException(
          "Artifact parse identity does not belong to this Job and execution");
    if (stageVersion < 0
        || artifactType == null
        || !artifactType.matches("[A-Z_]{1,32}")
        || !file.checksum().matches("[a-f0-9]{64}")
        || file.sizeBytes() < 0) throw new IllegalArgumentException("Artifact metadata is invalid");
    jdbc.update(
        "INSERT INTO cae_artifact(job_id,execution_id,parse_record_id,parser_version,stage_version,artifact_type,uri,file_name,size_bytes,checksum,content_type,metadata) VALUES(?,?,?,?,?,?,?,?,?,?,?,?) ON DUPLICATE KEY UPDATE id=id",
        jobId,
        executionId,
        parseRecordId,
        parserVersion,
        stageVersion,
        artifactType,
        file.uri(),
        file.fileName(),
        file.sizeBytes(),
        file.checksum(),
        contentType,
        json.write(metadata));
    Map<String, Object> row =
        jdbc.query(
                "SELECT * FROM cae_artifact WHERE job_id=? AND uri=?",
                SqlRows.MAPPER,
                jobId,
                file.uri())
            .get(0);
    if (((Number) row.get("executionId")).longValue() != executionId
        || !row.get("checksum").equals(file.checksum())
        || ((Number) row.get("sizeBytes")).longValue() != file.sizeBytes()
        || !row.get("artifactType").equals(artifactType)
        || !row.get("parserVersion").equals(parserVersion)
        || ((Number) row.get("stageVersion")).intValue() != stageVersion
        || !row.get("contentType").equals(contentType)
        || !json.readMap(row.get("metadata")).equals(json.readMap(json.write(metadata))))
      throw new IllegalArgumentException("Registered artifact identity cannot be overwritten");
    return decode(row);
  }

  private Map<String, Object> decode(Map<String, Object> row) {
    row.put("metadata", json.readMap(row.get("metadata")));
    row.put("downloadUrl", "/api/v1/artifacts/" + row.get("id") + "/download");
    return row;
  }
}

