package com.example.cae.batch;

import com.example.cae.auth.ProjectAccess;
import com.example.cae.common.*;
import com.example.cae.job.repository.JobRepository;
import com.example.cae.report.RenderFingerprint;
import java.util.*;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class BatchService {
  private final BatchRepository batches;
  private final ProjectAccess access;
  private final JobRepository jobs;
  private final JsonCodec json;
  private final RenderFingerprint fingerprints;
  private final BackpressureService pressure;

  public BatchService(
      BatchRepository batches,
      ProjectAccess access,
      JobRepository jobs,
      JsonCodec json,
      RenderFingerprint fingerprints,
      BackpressureService pressure) {
    this.batches = batches;
    this.access = access;
    this.jobs = jobs;
    this.json = json;
    this.fingerprints = fingerprints;
    this.pressure = pressure;
  }

  @Transactional
  public Map<String, Object> create(Authentication user, BatchRequest request) {
    access.require(user, request.projectId());
    if (request.jobs().stream().anyMatch(job -> !request.projectId().equals(job.projectId())))
      throw ApiException.invalid("Every child must belong to the batch project");
    String encoded = json.write(request);
    if (encoded.getBytes(java.nio.charset.StandardCharsets.UTF_8).length > 2 * 1024 * 1024)
      throw ApiException.invalid("Batch intent exceeds 2 MiB");
    var canonical = new LinkedHashMap<>(json.readMap(encoded));
    canonical.remove("idempotencyKey");
    var batch =
        batches.claim(
            user.getName(),
            request.idempotencyKey(),
            fingerprints.of(canonical),
            request.name(),
            request.projectId(),
            request.jobs().size());
    if (Boolean.TRUE.equals(batch.remove("newIntent"))) {
      batches.items(SqlRows.id(batch), request.jobs());
      jobs.audit(
          user.getName(),
          "BATCH_CREATE",
          "BATCH",
          batch.get("batchNo").toString(),
          null,
          Map.of("total", request.jobs().size()));
    }
    return view(batch);
  }

  public Map<String, Object> detail(Authentication user, String no) {
    var batch = batches.find(no);
    access.require(user, ((Number) batch.get("projectId")).longValue());
    return view(batch);
  }

  public List<Map<String, Object>> list(Authentication user, Long project) {
    if (project != null) access.require(user, project);
    return batches.list(user.getName(), access.admin(user), project).stream()
        .map(this::view)
        .toList();
  }

  private Map<String, Object> view(Map<String, Object> batch) {
    var children = batches.children(SqlRows.id(batch));
    long waiting = 0, running = 0, success = 0, failed = 0, cancelled = 0;
    for (var child : children) {
      String admission = child.get("admissionStatus").toString();
      String state = Objects.toString(child.get("status"), "PENDING");
      if (admission.equals("REJECTED") || state.endsWith("FAILED")) failed++;
      else if (state.equals("SUCCESS")) success++;
      else if (state.equals("CANCELLED")) cancelled++;
      else if (Set.of(
              "SUBMITTING",
              "SUBMITTED",
              "RUNNING",
              "UNKNOWN",
              "CANCEL_REQUESTED",
              "POST_PROCESSING",
              "REPORTING")
          .contains(state)) running++;
      else waiting++;
    }
    long total = ((Number) batch.get("total")).longValue(), done = success + failed + cancelled;
    var result = new LinkedHashMap<>(batch);
    result.remove("requestFingerprint");
    result.remove("idempotencyKey");
    result.put(
        "counts",
        Map.of(
            "total",
            total,
            "waiting",
            waiting,
            "running",
            running,
            "success",
            success,
            "failed",
            failed,
            "cancelled",
            cancelled));
    result.put("progress", total == 0 ? 0 : Math.round(done * 100.0 / total));
    result.put(
        "status",
        done == total
            ? (failed == 0
                ? (cancelled == total ? "CANCELLED" : "COMPLETED")
                : (failed == total ? "FAILED" : "PARTIAL_FAILED"))
            : (running > 0 ? "RUNNING" : "QUEUED"));
    result.put(
        "createdChildren", children.stream().filter(row -> row.get("jobNo") != null).count());
    result.put("children", children);
    result.put("backpressure", pressure.snapshot());
    return result;
  }
}

package com.example.cae.common;

import jakarta.servlet.http.HttpServletRequest;
import jakarta.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.util.LinkedHashMap;
import java.util.Map;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.http.HttpStatus;
import org.springframework.http.ResponseEntity;
import org.springframework.http.converter.HttpMessageNotReadableException;
import org.springframework.security.access.AccessDeniedException;
import org.springframework.web.bind.MethodArgumentNotValidException;
import org.springframework.web.bind.annotation.ExceptionHandler;
import org.springframework.web.bind.annotation.RestControllerAdvice;
import org.springframework.web.method.annotation.MethodArgumentTypeMismatchException;

@RestControllerAdvice
public class ApiErrors {
  private static final Logger LOG = LoggerFactory.getLogger(ApiErrors.class);
  private final JsonCodec json;

public ApiErrors(JsonCodec json) {
  this.json = json;
}

public Map<String, Object> body(
    String code, String message, HttpServletRequest request, Map<String, Object> details) {
  Map<String, Object> result = new LinkedHashMap<>();
  result.put("success", false);
  result.put("code", code);
  result.put("message", message);
  result.put("traceId", request.getAttribute(TraceFilter.ATTRIBUTE));
  result.put("details", details);
  return result;
}

public void write(
    HttpServletRequest request,
    HttpServletResponse response,
    int status,
    String code,
    String message)
    throws IOException {
  response.setStatus(status);
  response.setContentType("application/json;charset=UTF-8");
  response.getWriter().write(json.write(body(code, message, request, Map.of())));
}

@ExceptionHandler(ApiException.class)
ResponseEntity<Map<String, Object>> domain(ApiException error, HttpServletRequest request) {
  return ResponseEntity.status(error.status())
      .body(body(error.code(), error.getMessage(), request, error.details()));
}

@ExceptionHandler(PlatformFailure.class)
ResponseEntity<Map<String, Object>> failure(PlatformFailure error, HttpServletRequest request) {
  Map<String, Object> result =
      body(error.code().name(), error.getMessage(), request, error.details());
  result.put("stage", error.stage());
  result.put("retryable", error.code().retryable());
  return ResponseEntity.unprocessableEntity().body(result);
}

@ExceptionHandler(MethodArgumentNotValidException.class)
ResponseEntity<Map<String, Object>> validation(
    MethodArgumentNotValidException error, HttpServletRequest request) {
  Map<String, Object> fields = new LinkedHashMap<>();
  error
      .getBindingResult()
      .getFieldErrors()
      .forEach(e -> fields.put(e.getField(), e.getDefaultMessage()));
  return ResponseEntity.badRequest()
      .body(body("INVALID_INPUT", "Request fields are invalid", request, fields));
}

@ExceptionHandler(HttpMessageNotReadableException.class)
ResponseEntity<Map<String, Object>> malformed(HttpServletRequest request) {
  return ResponseEntity.badRequest()
      .body(
          body(
              "INVALID_INPUT",
              "Request JSON is malformed or contains an unsupported value",
              request,
              Map.of()));
}

@ExceptionHandler(MethodArgumentTypeMismatchException.class)
ResponseEntity<Map<String, Object>> queryType(HttpServletRequest request) {
  return ResponseEntity.badRequest()
      .body(
          body(
              "INVALID_INPUT",
              "Query or path parameter has an unsupported type",
              request,
              Map.of()));
}

@ExceptionHandler(DataIntegrityViolationException.class)
ResponseEntity<Map<String, Object>> constraint(HttpServletRequest request) {
  return ResponseEntity.status(HttpStatus.CONFLICT)
      .body(
          body(
              "DATA_CONFLICT",
              "A unique value or referenced record conflicts",
              request,
              Map.of()));
}

@ExceptionHandler(AccessDeniedException.class)
ResponseEntity<Map<String, Object>> denied(HttpServletRequest request) {
  return ResponseEntity.status(HttpStatus.FORBIDDEN)
      .body(body("FORBIDDEN", "Access is denied", request, Map.of()));
}

@ExceptionHandler(
    org.springframework.web.context.request.async.AsyncRequestNotUsableException.class)
void disconnected() {
  // The response transport has closed; writing an error body is no longer possible.
}

  @ExceptionHandler(IOException.class)
  ResponseEntity<Map<String, Object>> ioFailure(
      IOException error, HttpServletRequest request, HttpServletResponse response) {
    if (response.isCommitted() && request.getRequestURI().equals("/api/v1/events/stream"))
      return null;
    return unexpected(error, request);
  }

  @ExceptionHandler(Exception.class)
  ResponseEntity<Map<String, Object>> unexpected(Exception error, HttpServletRequest request) {
    LOG.error(
        "Unexpected API error traceId={}", request.getAttribute(TraceFilter.ATTRIBUTE), error);
    return ResponseEntity.internalServerError()
        .body(body("INTERNAL_ERROR", "Unexpected server error", request, Map.of()));
  }
}

