package com.example.cae.common;

import com.fasterxml.jackson.core.JsonProcessingException;
import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.util.Map;
import org.springframework.stereotype.Component;

@Component
public class JsonCodec {
  private final ObjectMapper mapper;

public JsonCodec(ObjectMapper mapper) {
  this.mapper = mapper;
}

public String write(Object value) {
  try {
    return mapper.writeValueAsString(value);
  } catch (JsonProcessingException e) {
    throw new IllegalArgumentException("Value cannot be encoded as JSON", e);
  }
}

  public Map<String, Object> readMap(Object value) {
    if (value == null) return Map.of();
    if (value instanceof Map<?, ?> map)
      return mapper.convertValue(map, new TypeReference<Map<String, Object>>() {});
    try {
      return mapper.readValue(value.toString(), new TypeReference<Map<String, Object>>() {});
    } catch (JsonProcessingException e) {
      throw new IllegalArgumentException("Stored JSON is invalid", e);
    }
  }
}

public class PlatformFailure extends RuntimeException {
  private final FailureCode code;
  private final String stage;
  private final Map<String, Object> details;

public PlatformFailure(
    FailureCode code, String stage, String message, Map<String, Object> details) {
  super(message);
  this.code = code;
  this.stage = stage;
  this.details = details;
}

public FailureCode code() {
  return code;
}

public String stage() {
  return stage;
}

  public Map<String, Object> details() {
    return details;
  }

  public Map<String, Object> toMap() {
    return Map.of(
        "code",
        code.name(),
        "stage",
        stage,
        "message",
        getMessage(),
        "retryable",
        code.retryable(),
        "details",
        details);
  }
}

