package com.example.cae.events;

import com.example.cae.auth.ProjectAccess;
import com.example.cae.common.ApiException;
import com.example.cae.common.SqlRows;
import com.example.cae.job.repository.JobRepository;
import jakarta.annotation.PreDestroy;
import java.io.IOException;
import java.time.Instant;
import java.util.Map;
import java.util.UUID;
import java.util.concurrent.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.springframework.http.HttpStatus;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.web.servlet.mvc.method.annotation.SseEmitter;

/** Notifications read committed MySQL events; reconnect always refreshes authoritative views. */
@Service
public class EventStreamService {
  private final JdbcTemplate jdbc;
  private final ProjectAccess access;
  private final JobRepository jobs;
  private final ConcurrentMap<String, Connection> connections = new ConcurrentHashMap<>();
  private final ThreadPoolExecutor senders =
      new ThreadPoolExecutor(
          4,
          4,
          0,
          TimeUnit.MILLISECONDS,
          new ArrayBlockingQueue<>(256),
          new ThreadPoolExecutor.AbortPolicy());

public EventStreamService(JdbcTemplate jdbc, ProjectAccess access, JobRepository jobs) {
  this.jdbc = jdbc;
  this.access = access;
  this.jobs = jobs;
}

public synchronized SseEmitter connect(
    Authentication user, String jobNo, Long project, String last) throws IOException {
  if (jobNo != null) access.requireJob(user, jobs.findByNo(jobNo));
  if (project != null) access.require(user, project);
  if (connections.size() >= 200
      || connections.values().stream().filter(c -> c.username.equals(user.getName())).count()
          >= 60)
    throw new ApiException(
        HttpStatus.TOO_MANY_REQUESTS, "STREAM_LIMIT", "Too many open event streams");
  long maximum = jdbc.queryForObject("SELECT COALESCE(MAX(id),0) FROM cae_job_event", Long.class);
  long cursor = maximum;
  if (last != null) {
    try {
      cursor = Math.min(maximum, Math.max(0, Long.parseLong(last)));
    } catch (NumberFormatException invalid) {
      throw ApiException.invalid("Invalid event cursor");
    }
  }
  var emitter = new SseEmitter(30 * 60 * 1000L);
  String key = UUID.randomUUID().toString();
  var connection =
      new Connection(emitter, user.getName(), access.admin(user), jobNo, project, cursor);
  connections.put(key, connection);
  emitter.onCompletion(() -> connections.remove(key));
  emitter.onTimeout(
      () -> {
        connections.remove(key);
        emitter.complete();
      });
  emitter.onError(error -> connections.remove(key));
  try {
    emitter.send(
        SseEmitter.event()
            .name("ready")
            .data(Map.of("cursor", maximum, "asOf", Instant.now().toString())));
  } catch (IOException error) {
    connections.remove(key);
    throw error;
  }
  return emitter;
}

@Scheduled(fixedDelay = 1000)
public void poll() {
  connections.forEach(
      (key, connection) -> {
        if (!connection.sending.compareAndSet(false, true)) return;
        try {
          senders.execute(() -> send(key, connection));
        } catch (RejectedExecutionException full) {
          connection.sending.set(false);
        }
      });
}

private void send(String key, Connection c) {
  try {
    var events =
        jdbc.query(
            "SELECT e.id AS event_id,e.event_type AS type,e.job_id,j.job_no,j.status,j.version,e.created_at AS occurred_at FROM cae_job_event e JOIN cae_job j ON j.id=e.job_id WHERE e.id>? AND (? IS NULL OR j.job_no=?) AND (? IS NULL OR j.project_id=?) AND (? OR EXISTS(SELECT 1 FROM cae_project_member m WHERE m.project_id=j.project_id AND m.username=?)) ORDER BY e.id LIMIT 100",
            SqlRows.MAPPER,
            c.cursor,
            c.jobNo,
            c.jobNo,
            c.project,
            c.project,
            c.admin,
            c.username);
    for (var event : events) {
      long id = ((Number) event.get("eventId")).longValue();
      c.emitter.send(SseEmitter.event().id(Long.toString(id)).name("job").data(event));
      c.cursor = id;
    }
    if (System.nanoTime() - c.heartbeat > TimeUnit.SECONDS.toNanos(15)) {
      c.emitter.send(SseEmitter.event().comment("heartbeat"));
      c.heartbeat = System.nanoTime();
    }
  } catch (IOException disconnected) {
    // Spring already completes an emitter when a transport write fails.
    connections.remove(key);
  } catch (IllegalStateException closed) {
    connections.remove(key);
  } catch (org.springframework.dao.DataAccessException unavailable) {
    /* Keep the cursor for recovery. */
  } finally {
    c.sending.set(false);
  }
}

public int connectionCount() {
  return connections.size();
}

@PreDestroy
public void close() {
  connections.values().forEach(c -> c.emitter.complete());
  connections.clear();
  senders.shutdownNow();
}

private static class Connection {
  final SseEmitter emitter;
  final String username;
  final boolean admin;
  final String jobNo;
  final Long project;
  final AtomicBoolean sending = new AtomicBoolean();
  volatile long cursor;
  volatile long heartbeat = System.nanoTime();

  Connection(
      SseEmitter emitter,
      String username,
      boolean admin,
      String jobNo,
      Long project,
      long cursor) {
    this.emitter = emitter;
    this.username = username;
    this.admin = admin;
    this.jobNo = jobNo;
    this.project = project;
    this.cursor = cursor;
  }
}

package com.example.cae.messaging;

import java.time.Instant;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.UUID;

/** eventId identifies business handling; deliveryId identifies one physical outbox publication. */
public record CommandEnvelope(
    String eventId,
    String deliveryId,
    String eventType,
    long jobId,
    String jobNo,
    Instant occurredAt,
    int payloadVersion,
    int deliveryAttempt,
    Map<String, Object> payload) {

  public CommandEnvelope {
    identifier(eventId);
    identifier(deliveryId);
    if (eventType == null
        || !eventType.matches("[A-Z][A-Z0-9_]{0,63}")
        || jobId <= 0
        || jobNo == null
        || !jobNo.matches("CAE-[0-9]{8}-[0-9]{6,}")
        || occurredAt == null
        || payloadVersion != 1
        || deliveryAttempt < 0
        || deliveryAttempt > 100
        || payload == null)
      throw new IllegalArgumentException("Message violates command envelope version 1");
    payload = Collections.unmodifiableMap(new LinkedHashMap<>(payload));
  }

public static CommandEnvelope create(
    String type, long jobId, String jobNo, Map<String, Object> payload) {
  String id = "evt-" + UUID.randomUUID();
  return new CommandEnvelope(id, id, type, jobId, jobNo, Instant.now(), 1, 0, payload);
}

public CommandEnvelope retry(int attempt) {
  return new CommandEnvelope(
      eventId,
      "evt-" + UUID.randomUUID(),
      eventType,
      jobId,
      jobNo,
      occurredAt,
      payloadVersion,
      attempt,
      payload);
}

@SuppressWarnings("unchecked")
public static CommandEnvelope from(Map<String, Object> values) {
  return new CommandEnvelope(
      string(values, "eventId"),
      string(values, "deliveryId"),
      string(values, "eventType"),
      number(values, "jobId").longValue(),
      string(values, "jobNo"),
      Instant.parse(string(values, "occurredAt")),
      Math.toIntExact(number(values, "payloadVersion").longValue()),
      Math.toIntExact(number(values, "deliveryAttempt").longValue()),
      (Map<String, Object>) values.get("payload"));
}

public Map<String, Object> asMap() {
  Map<String, Object> values = new LinkedHashMap<>();
  values.put("eventId", eventId);
  values.put("deliveryId", deliveryId);
  values.put("eventType", eventType);
  values.put("jobId", jobId);
  values.put("jobNo", jobNo);
  values.put("occurredAt", occurredAt.toString());
  values.put("payloadVersion", payloadVersion);
  values.put("deliveryAttempt", deliveryAttempt);
  values.put("payload", payload);
  return values;
}

private static String string(Map<String, Object> values, String key) {
  if (!(values.get(key) instanceof String value))
    throw new IllegalArgumentException("Missing message field: " + key);
  return value;
}

private static Number number(Map<String, Object> values, String key) {
  if (!(values.get(key) instanceof Number value))
    throw new IllegalArgumentException("Missing message field: " + key);
  if (value.doubleValue() != value.longValue())
    throw new IllegalArgumentException("Non-integral message field: " + key);
  return value;
}

private static void identifier(String id) {
  if (id == null || !id.matches("[A-Za-z0-9][A-Za-z0-9_-]{0,63}"))
    throw new IllegalArgumentException("Invalid message identifier");
}

package com.example.cae.messaging;

import com.example.cae.common.SqlRows;
import com.example.cae.outbox.OutboxRepository;
import java.sql.Timestamp;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Transactional;

/** Durable handling lease; a transport redelivery never creates a new logical business attempt. */
@Repository
public class InboxRepository {
  private final JdbcTemplate jdbc;
  private final OutboxRepository outbox;

public InboxRepository(JdbcTemplate jdbc, OutboxRepository outbox) {
  this.jdbc = jdbc;
  this.outbox = outbox;
}

@Transactional
public Claim claim(CommandEnvelope message, String consumer, Duration lease) {
  validateConsumer(consumer);
  if (lease.isNegative() || lease.isZero())
    throw new IllegalArgumentException("Inbox lease must be positive");
  // The duplicate branch obtains an exclusive unique-row lock directly. INSERT IGNORE followed
  // by FOR UPDATE would let concurrent duplicates deadlock while upgrading shared locks.
  jdbc.update(
      "INSERT INTO cae_message_inbox(logical_event_id,consumer_name,job_id,last_delivery_id) VALUES(?,?,?,?) ON DUPLICATE KEY UPDATE id=id",
      message.eventId(),
      consumer,
      message.jobId(),
      message.deliveryId());
  Map<String, Object> row = locked(message, consumer);
  if (((Number) row.get("jobId")).longValue() != message.jobId())
    throw new IllegalArgumentException("Logical event ID was reused for another Job");
  int failures = ((Number) row.get("retryCount")).intValue();
  String status = row.get("status").toString();
  if (status.equals("DONE")) return new Claim(Disposition.DONE, null, null, failures);
  if (status.equals("DEAD")) return new Claim(Disposition.DEAD, null, null, failures);
  Instant now = Instant.now();
  Instant claimUntil = instant(row.get("claimUntil"));
  Instant retryAt = instant(row.get("nextRetryTime"));
  if (status.equals("PROCESSING") && claimUntil != null && claimUntil.isAfter(now))
    return new Claim(Disposition.BUSY, null, claimUntil.plusMillis(100), failures);
  if (status.equals("RETRY") && retryAt != null && retryAt.isAfter(now))
    return new Claim(Disposition.BUSY, null, retryAt, failures);
  String owner = UUID.randomUUID().toString();
  jdbc.update(
      "UPDATE cae_message_inbox SET status='PROCESSING',claim_owner=?,claim_until=?,next_retry_time=NULL,last_delivery_id=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",
      owner,
      Timestamp.from(now.plus(lease)),
      message.deliveryId(),
      SqlRows.id(row));
  return new Claim(Disposition.ACQUIRED, owner, null, failures);
}

@Transactional
public void complete(CommandEnvelope message, String consumer, String owner) {
  if (jdbc.update(
          "UPDATE cae_message_inbox SET status='DONE',claim_owner=NULL,claim_until=NULL,next_retry_time=NULL,last_error=NULL,completed_at=UTC_TIMESTAMP(6),updated_at=UTC_TIMESTAMP(6) WHERE logical_event_id=? AND consumer_name=? AND status='PROCESSING' AND claim_owner=?",
          message.eventId(),
          consumer,
          owner)
      != 1) throw new LostLeaseException();
}

/** A retry Outbox row and release of the inbox lease commit before ACK of the old delivery. */
@Transactional
public FailureDisposition fail(
    CommandEnvelope message,
    String consumer,
    String owner,
    String reason,
    int maxAttempts,
    Duration base,
    Runnable onExhaustion) {
  if (maxAttempts < 1 || maxAttempts > 100 || base.isNegative() || base.isZero())
    throw new IllegalArgumentException("Message retry policy is invalid");
  Map<String, Object> row = locked(message, consumer);
  if (!"PROCESSING".equals(row.get("status")) || !owner.equals(row.get("claimOwner")))
    throw new LostLeaseException();
  int failures = ((Number) row.get("retryCount")).intValue() + 1;
  boolean dead = failures >= maxAttempts;
  Instant retryAt = Instant.now().plus(OutboxRepository.backoff(base, failures));
  if (dead) onExhaustion.run();
  else outbox.appendRetry(message, failures, retryAt, reason);
  jdbc.update(
      "UPDATE cae_message_inbox SET status=?,retry_count=?,claim_owner=NULL,claim_until=NULL,next_retry_time=?,last_error=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",
      dead ? "DEAD" : "RETRY",
      failures,
      dead ? null : Timestamp.from(retryAt),
      OutboxRepository.bounded(reason),
      SqlRows.id(row));
  return dead ? FailureDisposition.DEAD : FailureDisposition.RETRY;
}

/** A concurrent delivery is durably deferred; it is neither dropped nor immediately requeued. */
@Transactional
public void await(CommandEnvelope message, String consumer, String owner, Duration delay) {
  Map<String, Object> row = locked(message, consumer);
  if (!"PROCESSING".equals(row.get("status")) || !owner.equals(row.get("claimOwner")))
    throw new LostLeaseException();
  Instant retryAt = Instant.now().plus(delay);
  outbox.appendRetry(
      message,
      ((Number) row.get("retryCount")).intValue(),
      retryAt,
      "Awaiting the existing stage lease");
  jdbc.update(
      "UPDATE cae_message_inbox SET status='RETRY',claim_owner=NULL,claim_until=NULL,next_retry_time=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",
      Timestamp.from(retryAt),
      SqlRows.id(row));
}

/** A concurrent delivery is durably deferred; it is neither dropped nor immediately requeued. */
@Transactional
public void defer(CommandEnvelope message, String consumer) {
  Map<String, Object> row = locked(message, consumer);
  if (List.of("DONE", "DEAD").contains(row.get("status"))) return;
  Instant retryAt = instant(row.get("nextRetryTime"));
  Instant leaseUntil = instant(row.get("claimUntil"));
  Instant now = Instant.now();
  Instant availableAt = now.plusMillis(100);
  if (retryAt != null && retryAt.isAfter(availableAt)) availableAt = retryAt;
  if (leaseUntil != null && leaseUntil.isAfter(availableAt))
    availableAt = leaseUntil.plusMillis(100);
  outbox.appendRetry(
      message,
      ((Number) row.get("retryCount")).intValue(),
      availableAt,
      "Logical command is already being handled or awaits its retry time");
}

private static Instant instant(Object value) {
  return value == null ? null : Instant.parse(value.toString());
}

private static void validateConsumer(String consumer) {
  if (consumer == null || !consumer.matches("[A-Za-z0-9_-]{1,64}"))
    throw new IllegalArgumentException("Invalid consumer identity");
}

public enum Disposition {
  ACQUIRED,
  DONE,
  DEAD,
  BUSY
}

public enum FailureDisposition {
  RETRY,
  DEAD
}

public LostLeaseException() {
  super("Inbox handling lease was superseded");
}

package com.example.cae.messaging;

import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.springframework.amqp.core.BindingBuilder;
import org.springframework.amqp.core.Declarable;
import org.springframework.amqp.core.Declarables;
import org.springframework.amqp.core.DirectExchange;
import org.springframework.amqp.core.Queue;
import org.springframework.amqp.core.QueueBuilder;
import org.springframework.amqp.core.TopicExchange;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;

@Configuration
public class RabbitTopology {
  public static final String COMMAND_EXCHANGE = "cae.command";
  public static final String EVENT_EXCHANGE = "cae.event";
  public static final String DEAD_EXCHANGE = "cae.dead";
  public static final String SUBMIT_QUEUE = "cae.job.submit";
  public static final String EVENT_QUEUE = "cae.event.audit";
  private static final Map<String, String> COMMAND_ROUTES =
      Map.of(
          "JOB_SUBMIT_REQUESTED",
          "job.submit",
          "EXECUTION_SUBMIT_REQUESTED",
          "job.submit",
          "RESULT_PARSE_REQUESTED",
          "job.parse",
          "POST_PROCESS_REQUESTED",
          "job.postprocess",
          "REPORT_REQUESTED",
          "job.report");

public static String route(String eventType) {
  String route = COMMAND_ROUTES.get(eventType);
  if (route == null)
    throw new IllegalArgumentException("Unsupported command event: " + eventType);
  return route;
}

public static boolean isCommand(String eventType) {
  return COMMAND_ROUTES.containsKey(eventType);
}

@Bean
Declarables caeTopology() {
  DirectExchange commands = new DirectExchange(COMMAND_EXCHANGE, true, false);
  DirectExchange dead = new DirectExchange(DEAD_EXCHANGE, true, false);
  TopicExchange events = new TopicExchange(EVENT_EXCHANGE, true, false);
  List<Declarable> definitions = new ArrayList<>(List.of(commands, dead, events));
  for (String stage : List.of("submit", "parse", "postprocess", "report")) {
    String routing = "job." + stage;
    Queue queue =
        QueueBuilder.durable("cae.job." + stage)
            .deadLetterExchange(DEAD_EXCHANGE)
            .deadLetterRoutingKey(routing + ".dead")
            .build();
    Queue dlq = QueueBuilder.durable(queue.getName() + ".dlq").build();
    definitions.addAll(
        List.of(
            queue,
            dlq,
            BindingBuilder.bind(queue).to(commands).with(routing),
            BindingBuilder.bind(dlq).to(dead).with(routing + ".dead")));
  }
  // Every event has a durable route even before the SSE observer is installed.
  Queue audit = QueueBuilder.durable(EVENT_QUEUE).build();
  definitions.addAll(List.of(audit, BindingBuilder.bind(audit).to(events).with("#")));
  return new Declarables(definitions);
}

package com.example.cae.messaging;

import com.example.cae.common.JsonCodec;
import com.example.cae.job.execution.ExecutionRepository;
import com.example.cae.job.repository.JobRepository;
import com.example.cae.job.submission.DispatchOutcome;
import com.example.cae.job.submission.ExecutionDispatchService;
import com.example.cae.job.submission.JobAllocationService;
import com.example.cae.messaging.InboxRepository.Claim;
import com.example.cae.messaging.InboxRepository.FailureDisposition;
import com.rabbitmq.client.Channel;
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.MeterRegistry;
import io.micrometer.core.instrument.Timer;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.Map;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicInteger;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.amqp.core.Message;
import org.springframework.amqp.rabbit.annotation.RabbitListener;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DataAccessException;
import org.springframework.stereotype.Component;

/** Only asynchronous Agent acceptance is awaited. The Solver process is never awaited here. */
@Component
public class SubmitCommandListener {
  public static final String CONSUMER = "job-submit-v1";
  private static final Logger LOG = LoggerFactory.getLogger(SubmitCommandListener.class);
  private final io.micrometer.core.instrument.Counter consumeFailures;
  private final JsonCodec json;
  private final InboxRepository inbox;
  private final JobAllocationService allocation;
  private final ExecutionDispatchService dispatch;
  private final JobRepository jobs;
  private final ExecutionRepository executions;
  private final int maxAttempts;
  private final Duration retryBase;
  private final Counter acked;
  private final Counter retries;
  private final Counter dead;
  private final Timer acceptance;
  private final AtomicInteger infrastructureFailures = new AtomicInteger();

  public SubmitCommandListener(
      JsonCodec json,
      InboxRepository inbox,
      JobAllocationService allocation,
      ExecutionDispatchService dispatch,
      JobRepository jobs,
      ExecutionRepository executions,
      MeterRegistry metrics,
      @Value("${cae.mq.max-delivery-attempts:4}") int maxAttempts,
      @Value("${cae.mq.retry-base-ms:500}") long retryBaseMs) {
    this.json = json;
    this.inbox = inbox;
    this.allocation = allocation;
    this.dispatch = dispatch;
    this.jobs = jobs;
    this.executions = executions;
    this.maxAttempts = maxAttempts;
    this.retryBase = Duration.ofMillis(retryBaseMs);
    if (maxAttempts < 1 || maxAttempts > 100 || retryBaseMs < 1)
      throw new IllegalArgumentException("Submit retry configuration is invalid");
    consumeFailures = metrics.counter("cae.mq.consume.failure");
    acked = metrics.counter("cae.mq.commands.acked");
    retries = metrics.counter("cae.mq.commands.retry");
    dead = metrics.counter("cae.mq.commands.dead");
    acceptance = metrics.timer("cae.mq.command.acceptance");
  }

@RabbitListener(
    queues = RabbitTopology.SUBMIT_QUEUE,
    ackMode = "MANUAL",
    autoStartup = "${cae.mq.listeners-enabled:true}",
    concurrency = "${cae.mq.submit-concurrency:2}")
public void consume(Message message, Channel channel) throws IOException {
  long tag = message.getMessageProperties().getDeliveryTag();
  CommandEnvelope envelope;
  try {
    envelope =
        CommandEnvelope.from(json.readMap(new String(message.getBody(), StandardCharsets.UTF_8)));
    validate(envelope);
  } catch (DataAccessException databaseUnavailable) {
    recoverPersistence(channel, tag);
    return;
  } catch (RuntimeException invalid) {
    LOG.warn("Rejected invalid submit envelope reason={}", invalid.getClass().getSimpleName());
    consumeFailures.increment();
    dead.increment();
    channel.basicReject(tag, false);
    return;
  }
  try {
    Claim claim = inbox.claim(envelope, CONSUMER, Duration.ofSeconds(45));
    switch (claim.disposition()) {
      case DONE -> acknowledge(channel, tag);
      case DEAD -> {
        consumeFailures.increment();
        dead.increment();
        channel.basicReject(tag, false);
      }
      case BUSY -> {
        inbox.defer(envelope, CONSUMER);
        acknowledge(channel, tag);
      }
      case ACQUIRED -> handle(envelope, claim, channel, tag);
    }
  } catch (DataAccessException | InboxRepository.LostLeaseException failure) {
    LOG.warn(
        "Submit delivery awaits durable database acceptance eventId={} reason={}",
        envelope.eventId(),
        failure.getClass().getSimpleName());
    recoverPersistence(channel, tag);
  } catch (IllegalArgumentException invalidIdentity) {
    consumeFailures.increment();
    dead.increment();
    channel.basicReject(tag, false);
  }
}

private void handle(CommandEnvelope envelope, Claim claim, Channel channel, long tag)
    throws IOException {
  RuntimeException failure = null;
  long started = System.nanoTime();
  try {
    if (envelope.eventType().equals("JOB_SUBMIT_REQUESTED"))
      allocation.allocate(envelope.jobId());
    else if (dispatch.submit(executionId(envelope)) == DispatchOutcome.RETRYABLE_UNCERTAIN)
      throw new RetryableCommandException("Agent acceptance remains uncertain");
  } catch (RuntimeException businessFailure) {
    failure = businessFailure;
  } finally {
    acceptance.record(System.nanoTime() - started, java.util.concurrent.TimeUnit.NANOSECONDS);
  }
  if (failure == null) {
    inbox.complete(envelope, CONSUMER, claim.owner());
    acknowledge(channel, tag);
    return;
  }
  String reason = failure.getClass().getSimpleName() + ": " + failure.getMessage();
  FailureDisposition disposition =
      inbox.fail(
          envelope,
          CONSUMER,
          claim.owner(),
          reason,
          maxAttempts,
          retryBase,
          () -> {
            if (envelope.eventType().equals("EXECUTION_SUBMIT_REQUESTED"))
              dispatch.deliveryExhausted(
                  executionId(envelope), envelope.eventId(), maxAttempts, reason);
          });
  if (disposition == FailureDisposition.RETRY) {
    consumeFailures.increment();
    retries.increment();
    acknowledge(channel, tag);
  } else {
    consumeFailures.increment();
    dead.increment();
    channel.basicReject(tag, false);
  }
}

private void validate(CommandEnvelope envelope) {
  if (!envelope.eventType().equals("JOB_SUBMIT_REQUESTED")
      && !envelope.eventType().equals("EXECUTION_SUBMIT_REQUESTED"))
    throw new IllegalArgumentException("Command is not a submit command");
  Map<String, Object> job = jobs.findById(envelope.jobId());
  if (!envelope.jobNo().equals(job.get("jobNo")))
    throw new IllegalArgumentException("Command Job identity mismatch");
  if (envelope.eventType().equals("EXECUTION_SUBMIT_REQUESTED")) {
    Map<String, Object> execution = executions.find(executionId(envelope));
    if (((Number) execution.get("jobId")).longValue() != envelope.jobId())
      throw new IllegalArgumentException("Command execution belongs to another Job");
  }
}

private static long executionId(CommandEnvelope envelope) {
  if (!(envelope.payload().get("executionId") instanceof Number id)
      || id.longValue() < 1
      || id.doubleValue() != id.longValue())
    throw new IllegalArgumentException("Missing positive executionId in submit command");
  return id.longValue();
}

private void acknowledge(Channel channel, long tag) throws IOException {
  channel.basicAck(tag, false);
  infrastructureFailures.set(0);
  acked.increment();
}

private void recoverPersistence(Channel channel, long tag) throws IOException {
  int consecutive = infrastructureFailures.updateAndGet(value -> Math.min(value + 1, 16));
  long delayMs = Math.min(5000, 250L << (consecutive - 1));
  // The broker retains the unacked message throughout recovery, including an abrupt shutdown.
  try {
    TimeUnit.MILLISECONDS.sleep(delayMs);
  } catch (InterruptedException interrupted) {
    Thread.currentThread().interrupt();
  }
  channel.basicNack(tag, false, true);
}

RetryableCommandException(String message) {
  super(message);
}

