package com.example.cae.monitoring;

import com.example.cae.agent.AgentException;
import com.example.cae.agent.ComputeAgentClient;
import com.example.cae.common.ApiException;
import com.example.cae.job.execution.ExecutionRepository;
import com.example.cae.job.submission.JobCancellationService;
import jakarta.annotation.PreDestroy;
import java.time.Duration;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

/** Reconciliation observes the durable attempt; it never allocates or submits a solver. */
@Component
public class ExecutionMonitor {
  private static final Logger LOG = LoggerFactory.getLogger(ExecutionMonitor.class);
  private final ExecutionRepository executions;
  private final ComputeAgentClient agents;
  private final RemoteExecutionStateService states;
  private final ExecutionPollLeaseRepository leases;
  private final JobCancellationService cancellation;
  private final boolean enabled;
  private final Duration pollDelay;
  private final Duration leaseDuration;
  private final String owner = "monitor-" + UUID.randomUUID();
  private final ExecutorService workers = Executors.newFixedThreadPool(4);
  private final Set<Long> inFlight = ConcurrentHashMap.newKeySet();

  public ExecutionMonitor(
      ExecutionRepository executions,
      ComputeAgentClient agents,
      RemoteExecutionStateService states,
      ExecutionPollLeaseRepository leases,
      JobCancellationService cancellation,
      @Value("${cae.background.enabled:true}") boolean enabled,
      @Value("${cae.monitor.poll-ms:5000}") long pollMs,
      @Value("${cae.monitor.lease-ms:15000}") long leaseMs) {
    if (pollMs < 100 || leaseMs < 1000)
      throw new IllegalArgumentException("Monitoring intervals are invalid");
    this.executions = executions;
    this.agents = agents;
    this.states = states;
    this.leases = leases;
    this.cancellation = cancellation;
    this.enabled = enabled;
    this.pollDelay = Duration.ofMillis(pollMs);
    this.leaseDuration = Duration.ofMillis(leaseMs);
  }

@Scheduled(fixedDelayString = "${cae.monitor.scan-ms:5000}")
public void scan() {
  if (!enabled || inFlight.size() >= 12) return;
  for (ExecutionPollLeaseRepository.PollClaim claim :
      leases.claim(owner, 12 - inFlight.size(), leaseDuration, List.of())) {
    if (!inFlight.add(claim.executionId())) {
      leases.finish(claim, pollDelay, null);
      continue;
    }
    workers.execute(
        () -> {
          try {
            reconcile(claim);
          } finally {
            inFlight.remove(claim.executionId());
          }
        });
  }
}

/** Scoped synchronous reconciliation is also useful for deterministic recovery verification. */
public void reconcileExecution(long executionId) {
  leases.makeDue(executionId);
  for (ExecutionPollLeaseRepository.PollClaim claim :
      leases.claim(owner, 1, leaseDuration, List.of(executionId))) reconcile(claim);
}

private void reconcile(ExecutionPollLeaseRepository.PollClaim claim) {
  String failure = null;
  try {
    Map<String, Object> execution = executions.find(claim.executionId());
    if (RemoteExecutionStateService.TERMINAL.contains(execution.get("status"))) {
      states.applyStoredPolled(claim);
      return;
    }
    String nodeId = execution.get("nodeId").toString();
    if (states.nodeOffline(nodeId)) {
      failure = "Node heartbeat is unavailable; capacity is retained";
      if (awaitingSubmitDelivery(execution)) return;
      states.unknown(claim.executionId(), "NODE_OFFLINE", failure, claim);
      return;
    }
    Map<String, Object> remote =
        execution.get("externalExecutionId") == null
            ? agents.queryByRequest(nodeId, execution.get("submitRequestId").toString())
            : agents.query(nodeId, execution.get("externalExecutionId").toString());
    states.applyPolled(claim, remote);
    checkWalltime(execution, remote);
    if (RemoteExecutionStateService.cancellationRequested(executions.find(claim.executionId()))
        && !RemoteExecutionStateService.TERMINAL.contains(remote.get("state")))
      cancellation.continueCancel(claim.jobId());
  } catch (AgentException error) {
    if (awaitingSubmitDelivery(executions.find(claim.executionId()))) {
      // A queued/in-flight submit has no receipt yet. Its durable consumer owns bounded retries.
      // Turning it UNKNOWN here would prevent that original command from ever being sent.
      failure = "Awaiting original submit delivery: " + error.code();
      return;
    }
    failure =
        error.notFound()
            ? "Agent has no matching execution; absence does not prove the solver stopped"
            : error.getMessage();
    states.unknown(
        claim.executionId(),
        error.notFound() ? "UNKNOWN_REMOTE_STATE" : error.code().name(),
        failure,
        claim);
  } catch (ApiException error) {
    failure = "Remote execution observation could not be validated: " + error.code();
    states.unknown(claim.executionId(), "UNKNOWN_REMOTE_STATE", failure, claim);
  } catch (RuntimeException error) {
    failure = "Reconciliation deferred: " + error.getClass().getSimpleName();
    LOG.warn(
        "Execution reconciliation deferred executionId={} cause={}",
        claim.executionId(),
        error.getClass().getSimpleName());
  } finally {
    leases.finish(claim, pollDelay, failure);
  }
}

private static boolean awaitingSubmitDelivery(Map<String, Object> execution) {
  return "SUBMITTING".equals(execution.get("status"))
      && execution.get("externalExecutionId") == null;
}

private static void checkWalltime(Map<String, Object> execution, Map<String, Object> remote) {
  if (!"RUNNING".equals(remote.get("state")) || remote.get("startedAt") == null) return;
  Map<String, Object> request = (Map<String, Object>) execution.get("request");
  Map<String, Object> resource = (Map<String, Object>) request.get("resource");
  double minutes = ((Number) resource.get("walltimeMin")).doubleValue();
  if (Instant.parse(remote.get("startedAt").toString())
      .plusMillis((long) (minutes * 60_000))
      .isBefore(Instant.now()))
    LOG.warn(
        "Remote execution exceeds requested walltime executionId={} requestId={}; awaiting confirmed terminal evidence",
        execution.get("id"),
        execution.get("submitRequestId"));
}

@PreDestroy
public void close() {
  workers.shutdownNow();
}

package com.example.cae.monitoring;

import com.example.cae.common.SqlRows;
import java.sql.Timestamp;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.transaction.support.TransactionTemplate;

/**
 * Poll ownership only limits duplicate work; business CAS and identity checks remain authoritative.
 */
@Repository
public class ExecutionPollLeaseRepository {
  private final JdbcTemplate jdbc;
  private final TransactionTemplate tx;

public ExecutionPollLeaseRepository(JdbcTemplate jdbc, TransactionTemplate tx) {
  this.jdbc = jdbc;
  this.tx = tx;
}

/** Each initialization commits before the lease-only claim transaction begins. */
public void ensure(List<Long> executionIds) {
  checkedIds(executionIds);
  for (long id : executionIds.stream().distinct().sorted().toList()) {
    long jobId =
        jdbc.queryForObject("SELECT job_id FROM cae_job_execution WHERE id=?", Long.class, id);
    jdbc.update(
        "INSERT INTO cae_execution_poll_lease(execution_id,job_id) VALUES(?,?)"
            + " ON DUPLICATE KEY UPDATE execution_id=execution_id",
        id,
        jobId);
  }
}

public List<PollClaim> claim(
    String owner, int limit, Duration lease, List<Long> scopeExecutionIds) {
  if (owner == null
      || !owner.matches("[A-Za-z0-9_-]{1,64}")
      || limit < 1
      || limit > 200
      || lease.isNegative()
      || lease.isZero()) throw new IllegalArgumentException("Poll lease is invalid");
  List<Long> ids =
      scopeExecutionIds.isEmpty() ? candidates(limit) : List.copyOf(scopeExecutionIds);
  checkedIds(ids);
  if (ids.isEmpty()) return List.of();
  ensure(ids);
  return tx.execute(
      status -> {
        List<Object> parameters = new ArrayList<>(ids);
        parameters.add(limit);
        List<Map<String, Object>> rows =
            jdbc.query(
                "SELECT * FROM cae_execution_poll_lease WHERE execution_id IN ("
                    + String.join(",", ids.stream().map(id -> "?").toList())
                    + ")"
                    + " AND next_poll_at<=UTC_TIMESTAMP(6)"
                    + " AND (lease_until IS NULL OR lease_until<=UTC_TIMESTAMP(6))"
                    + " ORDER BY next_poll_at,execution_id LIMIT ? FOR UPDATE SKIP LOCKED",
                SqlRows.MAPPER,
                parameters.toArray());
        List<PollClaim> claims = new ArrayList<>();
        for (Map<String, Object> row : rows) {
          long id = ((Number) row.get("executionId")).longValue();
          long generation = ((Number) row.get("generation")).longValue() + 1;
          jdbc.update(
              "UPDATE cae_execution_poll_lease SET owner_token=?,generation=?,lease_until=?"
                  + " WHERE execution_id=?",
              owner,
              generation,
              Timestamp.from(Instant.now().plus(lease)),
              id);
          claims.add(
              new PollClaim(id, ((Number) row.get("jobId")).longValue(), owner, generation));
        }
        return claims;
      });
}

/** Called after locking Job and Execution, never before those business rows. */
@Transactional(propagation = Propagation.MANDATORY)
public boolean owns(PollClaim claim) {
  return !jdbc.queryForList(
          "SELECT execution_id FROM cae_execution_poll_lease WHERE execution_id=?"
              + " AND owner_token=? AND generation=? AND lease_until>UTC_TIMESTAMP(6) FOR UPDATE",
          Long.class,
          claim.executionId(),
          claim.owner(),
          claim.generation())
      .isEmpty();
}

public boolean finish(PollClaim claim, Duration delay, String failure) {
  if (delay.isNegative()) throw new IllegalArgumentException("Poll delay cannot be negative");
  String bounded =
      failure == null ? null : failure.substring(0, Math.min(1000, failure.length()));
  return jdbc.update(
          "UPDATE cae_execution_poll_lease SET owner_token=NULL,lease_until=NULL,next_poll_at=?,"
              + " failure_count=CASE WHEN ? IS NULL THEN 0 ELSE failure_count+1 END,"
              + " last_observed_at=CASE WHEN ? IS NULL THEN UTC_TIMESTAMP(6) ELSE last_observed_at END,"
              + " last_error=? WHERE execution_id=? AND owner_token=? AND generation=?"
              + " AND lease_until>UTC_TIMESTAMP(6)",
          Timestamp.from(Instant.now().plus(delay)),
          bounded,
          bounded,
          bounded,
          claim.executionId(),
          claim.owner(),
          claim.generation())
      == 1;
}

public void makeDue(long executionId) {
  ensure(List.of(executionId));
  jdbc.update(
      "UPDATE cae_execution_poll_lease SET next_poll_at=UTC_TIMESTAMP(6)"
          + " WHERE execution_id=? AND (lease_until IS NULL OR lease_until<=UTC_TIMESTAMP(6))",
      executionId);
}

private static void checkedIds(List<Long> ids) {
  if (ids.size() > 200 || ids.stream().anyMatch(id -> id == null || id <= 0))
    throw new IllegalArgumentException("Execution IDs must be a bounded positive list");
}

package com.example.cae.monitoring;

import com.example.cae.agent.ComputeAgentClient;
import com.example.cae.common.ApiException;
import com.example.cae.common.SqlRows;
import com.example.cae.job.domain.JobStatus;
import com.example.cae.job.execution.ExecutionRepository;
import com.example.cae.job.execution.RemoteExecutionFields;
import com.example.cae.job.repository.JobRepository;
import com.example.cae.resource.NodeRegistryService;
import com.example.cae.resource.ResourceReservationService;
import java.math.BigDecimal;
import java.sql.Timestamp;
import java.time.Instant;
import java.time.format.DateTimeParseException;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

/** One identity-checked, monotonic transaction for callback, poll and cancellation observations. */
@Service
public class RemoteExecutionStateService {
  public static final Set<String> TERMINAL =
      Set.of("SUCCESS", "RUNTIME_FAILED", "TIMEOUT", "CANCELLED", "SUBMIT_FAILED");
  private static final Set<String> WIRE_STATES =
      Set.of(
          "SUBMITTED", "RUNNING", "SUCCESS", "RUNTIME_FAILED", "TIMEOUT", "CANCELLED", "UNKNOWN");
  private static final Set<String> ACTIVE_JOBS =
      Set.of("SUBMITTING", "SUBMITTED", "RUNNING", "UNKNOWN", "CANCEL_REQUESTED");
  private final JobRepository jobs;
  private final ExecutionRepository executions;
  private final ComputeAgentClient agents;
  private final NodeRegistryService nodes;
  private final ResourceReservationService resources;
  private final ExecutionPollLeaseRepository leases;
  private final TransactionTemplate tx;
  private final long offlineSeconds;

  public RemoteExecutionStateService(
      JobRepository jobs,
      ExecutionRepository executions,
      ComputeAgentClient agents,
      NodeRegistryService nodes,
      ResourceReservationService resources,
      ExecutionPollLeaseRepository leases,
      TransactionTemplate tx,
      @Value("${cae.nodes.offline-seconds:20}") long offlineSeconds) {
    this.jobs = jobs;
    this.executions = executions;
    this.agents = agents;
    this.nodes = nodes;
    this.resources = resources;
    this.leases = leases;
    this.tx = tx;
    this.offlineSeconds = offlineSeconds;
  }

public ApplyResult callback(String nodeId, Map<String, Object> remote) {
  validate(remote);
  Map<String, Object> execution =
      executions.findByRequest(remote.get("executionRequestId").toString());
  return apply(SqlRows.id(execution), nodeId, remote, "CALLBACK");
}

public ApplyResult apply(
    long executionId, String nodeId, Map<String, Object> remote, String source) {
  validate(remote);
  return observe(executionId, nodeId, remote, source, null, false);
}

public ApplyResult applyPolled(
    ExecutionPollLeaseRepository.PollClaim claim, Map<String, Object> remote) {
  validate(remote);
  return observe(
      claim.executionId(),
      executions.find(claim.executionId()).get("nodeId").toString(),
      remote,
      "POLL",
      claim,
      false);
}

/** Durable terminal evidence also repairs pre-monitoring completion and reservation windows. */
public ApplyResult applyStoredPolled(ExecutionPollLeaseRepository.PollClaim claim) {
  return applyStored(claim.executionId(), "DURABLE_TERMINAL_REPAIR", claim);
}

public ApplyResult applyStored(long executionId, String source) {
  return applyStored(executionId, source, null);
}

private ApplyResult applyStored(
    long executionId, String source, ExecutionPollLeaseRepository.PollClaim claim) {
  Map<String, Object> execution = executions.find(executionId);
  if (!TERMINAL.contains(execution.get("status")))
    return result(false, execution, jobs.findById(((Number) execution.get("jobId")).longValue()));
  Map<String, Object> remote = new LinkedHashMap<>();
  remote.put("executionRequestId", execution.get("submitRequestId"));
  remote.put("externalExecutionId", execution.get("externalExecutionId"));
  remote.put("state", execution.get("status"));
  for (String key :
      new String[] {
        "progress",
        "pid",
        "processIdentity",
        "exitCode",
        "rawSolverCode",
        "rawMessage",
        "startedAt",
        "finishedAt"
      }) remote.put(key, execution.get(key));
  return observe(executionId, execution.get("nodeId").toString(), remote, source, claim, true);
}

public boolean nodeOffline(String nodeId) {
  Map<String, Object> node = nodes.find(nodeId);
  Object heartbeat = node.get("lastHeartbeat");
  return "OFFLINE".equals(node.get("status"))
      || heartbeat == null
      || Instant.parse(heartbeat.toString()).isBefore(Instant.now().minusSeconds(offlineSeconds));
}

public ApplyResult unknown(
    long executionId,
    String failureCode,
    String reason,
    ExecutionPollLeaseRepository.PollClaim claim) {
  Map<String, Object> snapshot = executions.find(executionId);
  return tx.execute(
      status -> {
        Map<String, Object> job = jobs.lockById(((Number) snapshot.get("jobId")).longValue());
        Map<String, Object> execution = executions.locked(executionId);
        if ((claim != null && !leases.owns(claim))
            || !isCurrent(job, executionId)
            || TERMINAL.contains(execution.get("status"))
            || !ACTIVE_JOBS.contains(job.get("status"))) return result(false, execution, job);
        return markUnknown(job, execution, failureCode, reason);
      });
}

private ApplyResult observe(
    long executionId,
    String nodeId,
    Map<String, Object> remote,
    String source,
    ExecutionPollLeaseRepository.PollClaim claim,
    boolean stored) {
  if (!agents.nodes().containsKey(nodeId))
    throw ApiException.invalid("Execution node must be configured");
  Map<String, Object> snapshot = executions.find(executionId);
  return tx.execute(
      status -> {
        Map<String, Object> job = jobs.lockById(((Number) snapshot.get("jobId")).longValue());
        Map<String, Object> execution = executions.locked(executionId);
        if (claim != null && !leases.owns(claim)) return result(false, execution, job);
        identity(execution, nodeId, remote, stored);
        String state = remote.get("state").toString();
        if (TERMINAL.contains(execution.get("status")) && !execution.get("status").equals(state))
          return result(false, execution, job);
        if (!isCurrent(job, executionId)) {
          // A late event can repair a proven terminal old reservation, never mutate the new
          // attempt.
          boolean released =
              TERMINAL.contains(execution.get("status"))
                  && resources.releaseByExecution(executionId);
          return result(released, execution, job);
        }
        if (TERMINAL.contains(state)) return terminal(job, execution, remote, source);
        if (JobStatus.valueOf(job.get("status").toString()).terminal()
            || !ACTIVE_JOBS.contains(job.get("status"))) return result(false, execution, job);
        if ("UNKNOWN".equals(state) || nodeOffline(nodeId)) {
          Map<String, Object> facts = facts(execution, remote);
          facts.put("externalExecutionId", remote.get("externalExecutionId"));
          execution = patchExecution(execution, facts);
          resources.accepted(((Number) execution.get("reservationId")).longValue());
          return markUnknown(
              job,
              execution,
              nodeOffline(nodeId) ? "NODE_OFFLINE" : "UNKNOWN_REMOTE_STATE",
              nodeOffline(nodeId)
                  ? "Node heartbeat is unavailable; remote capacity is retained"
                  : "Agent cannot establish a confirmed execution state");
        }
        Map<String, Object> fields = facts(execution, remote);
        fields.put("externalExecutionId", remote.get("externalExecutionId"));
        fields.put(
            "status",
            "RUNNING".equals(execution.get("status"))
                    || execution.get("runningObservedAt") != null
                ? "RUNNING"
                : state);
        if (execution.get("submittedAt") == null)
          fields.put("submittedAt", Timestamp.from(Instant.now()));
        Object oldVersion = execution.get("version");
        execution = patchExecution(execution, fields);
        boolean applied = !oldVersion.equals(execution.get("version"));
        applied |= resources.accepted(((Number) execution.get("reservationId")).longValue());
        Map<String, Object> metadata = new LinkedHashMap<>();
        if (job.get("submittedAt") == null)
          metadata.put(
              "submittedAt",
              Timestamp.from(Instant.parse(execution.get("submittedAt").toString())));
        if (execution.get("startedAt") != null && job.get("startedAt") == null)
          metadata.put(
              "startedAt", Timestamp.from(Instant.parse(execution.get("startedAt").toString())));
        boolean cancel =
            cancellationRequested(execution) || "CANCEL_REQUESTED".equals(job.get("status"));
        if (!cancel) {
          metadata.put("failureCode", null);
          metadata.put("failureMessage", null);
        }
        Object jobVersion = job.get("version");
        job = patchJob(job, metadata);
        applied |= !jobVersion.equals(job.get("version"));
        if (cancel) {
          if (!"CANCEL_REQUESTED".equals(job.get("status"))) {
            job =
                jobs.transition(
                    job,
                    JobStatus.CANCEL_REQUESTED,
                    "CANCELLATION_INTENT_RECOVERED",
                    detail(executionId, state, source));
            applied = true;
          }
        } else {
          if ("SUBMITTING".equals(job.get("status")) || "UNKNOWN".equals(job.get("status"))) {
            job =
                jobs.transition(
                    job,
                    JobStatus.SUBMITTED,
                    "REMOTE_ACCEPTANCE_RECONCILED",
                    detail(executionId, state, source));
            applied = true;
          }
          if ("RUNNING".equals(execution.get("status"))
              && "SUBMITTED".equals(job.get("status"))) {
            job =
                jobs.transition(
                    job, JobStatus.RUNNING, "SOLVER_RUNNING", detail(executionId, state, source));
            applied = true;
          }
        }
        return result(applied, execution, job);
      });
}

private ApplyResult markUnknown(
    Map<String, Object> job, Map<String, Object> execution, String failureCode, String reason) {
  long id = SqlRows.id(execution);
  Object executionVersion = execution.get("version"), jobVersion = job.get("version");
  execution = patchExecution(execution, Map.of("status", "UNKNOWN"));
  String bounded = reason.substring(0, Math.min(1000, reason.length()));
  Map<String, Object> metadata = new LinkedHashMap<>();
  // Cancellation failure remains inspectable while the independent offline state is reconciled.
  if (!"CANCEL_FAILED".equals(job.get("failureCode"))) {
    metadata.put("failureCode", failureCode);
    metadata.put("failureMessage", bounded);
  }
  job = patchJob(job, metadata);
  boolean applied =
      !executionVersion.equals(execution.get("version"))
          || !jobVersion.equals(job.get("version"));
  if (!"UNKNOWN".equals(job.get("status"))) {
    job =
        jobs.transition(
            job,
            JobStatus.UNKNOWN,
            "REMOTE_STATE_UNKNOWN",
            Map.of("executionId", id, "failureCode", failureCode, "resourcesRetained", true));
    applied = true;
  }
  return result(applied, execution, job);
}

private ApplyResult terminal(
    Map<String, Object> job,
    Map<String, Object> execution,
    Map<String, Object> remote,
    String source) {
  long id = SqlRows.id(execution);
  String state = remote.get("state").toString();
  Map<String, Object> fields = facts(execution, remote);
  fields.put("status", state);
  if (remote.get("externalExecutionId") != null)
    fields.put("externalExecutionId", remote.get("externalExecutionId"));
  if (execution.get("finishedAt") == null && !fields.containsKey("finishedAt"))
    fields.put("finishedAt", Timestamp.from(Instant.now()));
  if (execution.get("terminalAppliedAt") == null)
    fields.put("terminalAppliedAt", Timestamp.from(Instant.now()));
  Object version = execution.get("version");
  execution = patchExecution(execution, fields);
  boolean applied = !version.equals(execution.get("version"));
  applied |= resources.releaseByExecution(id);
  if (JobStatus.valueOf(job.get("status").toString()).terminal())
    return result(applied, execution, job);
  if (!ACTIVE_JOBS.contains(job.get("status")) && !"POST_PROCESSING".equals(job.get("status")))
    return result(applied, execution, job);
  Map<String, Object> metadata = new LinkedHashMap<>();
  metadata.put("rawSolverCode", execution.get("rawSolverCode"));
  metadata.put("rawMessage", execution.get("rawMessage"));
  metadata.put(
      "finishedAt",
      "SUCCESS".equals(state)
          ? null
          : Timestamp.from(Instant.parse(execution.get("finishedAt").toString())));
  if (execution.get("startedAt") != null && job.get("startedAt") == null)
    metadata.put(
        "startedAt", Timestamp.from(Instant.parse(execution.get("startedAt").toString())));
  String failure =
      switch (state) {
        case "RUNTIME_FAILED" -> "SOLVER_RUNTIME_FAILED";
        case "TIMEOUT" -> "SOLVER_TIMEOUT";
        case "SUBMIT_FAILED" -> "SUBMIT_REJECTED";
        default -> null;
      };
  metadata.put("failureCode", failure);
  metadata.put("failureMessage", failure == null ? null : execution.get("rawMessage"));
  Object jobVersion = job.get("version");
  job = patchJob(job, metadata);
  applied |= !jobVersion.equals(job.get("version"));
  if ("SUBMITTING".equals(job.get("status")) && !"SUBMIT_FAILED".equals(state)) {
    job =
        jobs.transition(
            job, JobStatus.SUBMITTED, "REMOTE_ACCEPTANCE_RECONCILED", detail(id, state, source));
    applied = true;
  }
  if ("CANCELLED".equals(state)
      && !Set.of("CANCEL_REQUESTED", "UNKNOWN").contains(job.get("status"))) {
    job =
        jobs.transition(
            job,
            JobStatus.CANCEL_REQUESTED,
            "REMOTE_CANCELLATION_OBSERVED",
            detail(id, state, source));
    applied = true;
  }
  JobStatus target =
      switch (state) {
        case "SUCCESS" -> JobStatus.POST_PROCESSING;
        case "CANCELLED" -> JobStatus.CANCELLED;
        case "SUBMIT_FAILED" ->
            "CANCEL_REQUESTED".equals(job.get("status"))
                ? JobStatus.CANCELLED
                : JobStatus.SUBMIT_FAILED;
        default -> JobStatus.RUNTIME_FAILED;
      };
  if (!target.name().equals(job.get("status"))) {
    String event = "SUCCESS".equals(state) ? "SOLVER_SUCCESS" : "SOLVER_TERMINAL_CONFIRMED";
    job = jobs.transition(job, target, event, detail(id, state, source));
    applied = true;
  }
  if ("SUCCESS".equals(state) && execution.get("resultParseRequestedAt") == null) {
    executions.patch(execution, Map.of("resultParseRequestedAt", Timestamp.from(Instant.now())));
    jobs.recordEvent(
        SqlRows.id(job),
        "RESULT_PARSE_REQUESTED",
        Map.of(
            "executionId",
            id,
            "executionRequestId",
            execution.get("submitRequestId"),
            "source",
            source));
    applied = true;
  }
  return result(applied, execution, job);
}

private static Map<String, Object> facts(
    Map<String, Object> execution, Map<String, Object> remote) {
  Map<String, Object> result = RemoteExecutionFields.from(remote);
  result.values().removeIf(value -> value == null);
  // Persist knowledge independently of transient UNKNOWN and optional remote start facts.
  if ("RUNNING".equals(remote.get("state")) && execution.get("runningObservedAt") == null)
    result.put("runningObservedAt", Timestamp.from(Instant.now()));
  if (result.get("progress") instanceof Number progress) {
    double current = ((Number) execution.get("progress")).doubleValue();
    result.put("progress", BigDecimal.valueOf(Math.max(current, progress.doubleValue())));
  }
  // Start/finish facts are immutable after first confirmation.
  if (execution.get("startedAt") != null) result.remove("startedAt");
  if (execution.get("finishedAt") != null) result.remove("finishedAt");
  return result;
}

private Map<String, Object> patchExecution(
    Map<String, Object> current, Map<String, Object> fields) {
  Map<String, Object> changed = changed(current, fields);
  return changed.isEmpty() ? current : executions.patch(current, changed);
}

private Map<String, Object> patchJob(Map<String, Object> current, Map<String, Object> fields) {
  Map<String, Object> changed = changed(current, fields);
  return changed.isEmpty() ? current : jobs.patch(current, changed);
}

private static Map<String, Object> changed(
    Map<String, Object> current, Map<String, Object> fields) {
  Map<String, Object> changed = new LinkedHashMap<>();
  fields.forEach(
      (key, value) -> {
        Object old = current.get(key);
        boolean same = java.util.Objects.equals(old, value);
        if (old instanceof Number a && value instanceof Number b)
          same = new BigDecimal(a.toString()).compareTo(new BigDecimal(b.toString())) == 0;
        if (old instanceof String timestamp && value instanceof Timestamp time)
          same = timestamp.equals(time.toInstant().toString());
        if (!same) changed.put(key, value);
      });
  return changed;
}

public static boolean cancellationRequested(Map<String, Object> execution) {
  Object value = execution.get("cancelRequested");
  return Boolean.TRUE.equals(value) || (value instanceof Number n && n.intValue() == 1);
}

private static boolean isCurrent(Map<String, Object> job, long id) {
  return job.get("currentExecutionId") instanceof Number current && current.longValue() == id;
}

private static void identity(
    Map<String, Object> execution, String nodeId, Map<String, Object> remote, boolean stored) {
  if (!nodeId.equals(execution.get("nodeId"))
      || !execution.get("submitRequestId").equals(remote.get("executionRequestId"))
      || (execution.get("externalExecutionId") != null
          && !execution.get("externalExecutionId").equals(remote.get("externalExecutionId"))))
    throw ApiException.conflict("Remote execution identity does not match the durable attempt");
  if (!stored
      && execution.get("processIdentity") != null
      && remote.get("processIdentity") != null
      && !execution.get("processIdentity").equals(remote.get("processIdentity")))
    throw ApiException.conflict("Remote process identity changed for the same execution");
  if (!stored
      && execution.get("pid") instanceof Number expectedPid
      && remote.get("pid") instanceof Number observedPid
      && expectedPid.longValue() != observedPid.longValue())
    throw ApiException.conflict("Remote process ID changed for the same execution");
}

private static void validate(Map<String, Object> remote) {
  if (remote == null) throw ApiException.invalid("Execution observation is required");
  safeIdentifier(remote.get("executionRequestId"), 100);
  safeIdentifier(remote.get("externalExecutionId"), 128);
  if (!(remote.get("state") instanceof String state) || !WIRE_STATES.contains(state))
    throw ApiException.invalid("Execution state is invalid");
  for (String key : new String[] {"progress", "pid", "exitCode"}) {
    Object value = remote.get(key);
    if (value == null) continue;
    if (!(value instanceof Number number) || !Double.isFinite(number.doubleValue()))
      throw ApiException.invalid("Execution numeric fact is invalid");
    double numeric = number.doubleValue();
    if ((key.equals("progress") && (numeric < 0 || numeric > 100))
        || (key.equals("pid")
            && (numeric <= 0 || numeric > Long.MAX_VALUE || numeric != Math.rint(numeric)))
        || (key.equals("exitCode")
            && (numeric < Integer.MIN_VALUE
                || numeric > Integer.MAX_VALUE
                || numeric != Math.rint(numeric))))
      throw ApiException.invalid("Execution numeric fact is outside its valid range");
  }
  for (String key : new String[] {"processIdentity", "rawSolverCode", "rawMessage"}) {
    Object value = remote.get(key);
    if (value != null
        && (!(value instanceof String text)
            || text.length() > (key.equals("rawMessage") ? 2000 : 128)))
      throw ApiException.invalid("Execution text fact exceeds its valid range");
  }
  for (String key : new String[] {"startedAt", "finishedAt"}) {
    Object value = remote.get(key);
    if (value == null) continue;
    try {
      Instant.parse(value.toString());
    } catch (DateTimeParseException error) {
      throw ApiException.invalid("Execution timestamp must be an ISO-8601 instant");
    }
  }
}

private static void safeIdentifier(Object value, int maximum) {
  if (!(value instanceof String text)
      || text.length() > maximum
      || !text.matches("[A-Za-z0-9][A-Za-z0-9_-]*"))
    throw ApiException.invalid("Execution identity is invalid");
}

private static Map<String, Object> detail(long id, String state, String source) {
  return Map.of("executionId", id, "remoteState", state, "source", source);
}

private static ApplyResult result(
    boolean applied, Map<String, Object> execution, Map<String, Object> job) {
  return new ApplyResult(true, applied, SqlRows.id(execution), job.get("status").toString());
}

package com.example.cae.observability;

import com.example.cae.events.EventStreamService;
import com.example.cae.job.domain.*;
import io.micrometer.core.instrument.*;
import java.time.Instant;
import java.util.*;
import java.util.concurrent.atomic.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class PlatformMetrics {
  private final JdbcTemplate jdbc;
  private final AtomicReference<Map<String, Double>> snapshot = new AtomicReference<>(Map.of());
  private final AtomicLong updated = new AtomicLong();
  private final Counter failures;

public PlatformMetrics(JdbcTemplate jdbc, MeterRegistry registry, EventStreamService streams) {
  this.jdbc = jdbc;
  failures = registry.counter("cae.metrics.refresh.error");
  for (var status : JobStatus.values())
    for (var analysis : AnalysisType.values())
      gauge(
          registry,
          "cae.jobs.total",
          status + ":" + analysis,
          "status",
          status.name(),
          "analysis_type",
          analysis.name());
  for (String name :
      List.of(
          "jobs.running",
          "jobs.waiting.resource",
          "job.queue.seconds",
          "job.queue.samples",
          "reports.generated.total",
          "resource.reservation.total",
          "agent.offline.total",
          "outbox.oldest.pending.seconds",
          "batches.active")) gauge(registry, "cae." + name, name);
  Gauge.builder("cae.sse.connections", streams, EventStreamService::connectionCount)
      .register(registry);
  Gauge.builder("cae.metrics.last.success.timestamp.seconds", updated, AtomicLong::get)
      .register(registry);
  for (String node : List.of("node-a", "node-b", "node-c"))
    for (String field :
        List.of(
            "cpu.used",
            "cpu.reserved",
            "cpu.total",
            "memory.used.gb",
            "memory.reserved.gb",
            "memory.total.gb"))
      gauge(registry, "cae.node." + field, node + ":" + field, "node", node);
  for (String feature : List.of("OPTISTRUCT", "NVH", "CRASH", "CFD"))
    for (String field : List.of("reserved", "in.use", "total"))
      gauge(
          registry,
          "cae.license.tokens",
          feature + ":" + field,
          "feature",
          feature,
          "state",
          field);
}

private void gauge(MeterRegistry registry, String name, String key, String... tags) {
  Gauge.builder(name, snapshot, ref -> ref.get().getOrDefault(key, 0d))
      .tags(tags)
      .register(registry);
}

@Scheduled(fixedDelay = 5000)
public void refresh() {
  try {
    Map<String, Double> values = new HashMap<>();
    jdbc.query(
        "SELECT status,analysis_type,COUNT(*) AS n FROM cae_job GROUP BY status,analysis_type",
        (org.springframework.jdbc.core.RowCallbackHandler)
            row ->
                values.put(
                    row.getString("status") + ":" + row.getString("analysis_type"),
                    row.getDouble("n")));
    values.put("jobs.running", count("SELECT COUNT(*) FROM cae_job WHERE status='RUNNING'"));
    values.put(
        "jobs.waiting.resource",
        count("SELECT COUNT(*) FROM cae_job WHERE status='WAITING_RESOURCE'"));
    values.put(
        "job.queue.seconds",
        count(
            "SELECT COALESCE(AVG(TIMESTAMPDIFF(MICROSECOND,j.queued_at,x.started_at)/1000000),0) FROM cae_job j JOIN cae_job_execution x ON x.id=j.current_execution_id WHERE x.started_at>=j.queued_at"));
    values.put(
        "job.queue.samples",
        count(
            "SELECT COUNT(*) FROM cae_job j JOIN cae_job_execution x ON x.id=j.current_execution_id WHERE x.started_at>=j.queued_at"));
    values.put("reports.generated.total", count("SELECT COUNT(*) FROM cae_report"));
    values.put(
        "resource.reservation.total", count("SELECT COUNT(*) FROM cae_resource_reservation"));
    values.put(
        "agent.offline.total",
        count("SELECT COUNT(*) FROM cae_compute_node WHERE status='OFFLINE'"));
    values.put(
        "outbox.oldest.pending.seconds",
        count(
            "SELECT COALESCE(GREATEST(0,TIMESTAMPDIFF(MICROSECOND,MIN(created_at),UTC_TIMESTAMP(6))/1000000),0) FROM cae_outbox_event WHERE status IN ('NEW','RETRY','PUBLISHING')"));
    values.put(
        "batches.active",
        count(
            "SELECT COUNT(DISTINCT b.id) FROM cae_batch b JOIN cae_batch_item i ON i.batch_id=b.id LEFT JOIN cae_job j ON j.id=i.job_id WHERE i.status='PENDING' OR j.status IN ('CREATED','VALIDATING','READY','QUEUED','WAITING_RESOURCE','SUBMITTING','SUBMITTED','RUNNING','UNKNOWN','CANCEL_REQUESTED','POST_PROCESSING','REPORTING')"));
    jdbc.query(
        "SELECT * FROM cae_compute_node",
        (org.springframework.jdbc.core.RowCallbackHandler)
            row -> {
              String node = row.getString("node_id");
              for (String field :
                  List.of(
                      "cpu_used",
                      "cpu_reserved",
                      "cpu_total",
                      "memory_used_gb",
                      "memory_reserved_gb",
                      "memory_total_gb"))
                values.put(node + ":" + field.replace('_', '.'), row.getDouble(field));
            });
    jdbc.query(
        "SELECT * FROM cae_license_pool",
        (org.springframework.jdbc.core.RowCallbackHandler)
            row -> {
              String feature = row.getString("feature");
              values.put(feature + ":reserved", row.getDouble("reserved_tokens"));
              values.put(feature + ":in.use", row.getDouble("in_use_tokens"));
              values.put(feature + ":total", row.getDouble("total_tokens"));
            });
    snapshot.set(Map.copyOf(values));
    updated.set(Instant.now().getEpochSecond());
  } catch (org.springframework.dao.DataAccessException error) {
    failures.increment();
  }
}

private double count(String sql) {
  return jdbc.queryForObject(sql, Double.class);
}

package com.example.cae.outbox;

import com.example.cae.common.JsonCodec;
import com.example.cae.outbox.OutboxRepository.ClaimedEvent;
import io.micrometer.core.instrument.Counter;
import io.micrometer.core.instrument.Gauge;
import io.micrometer.core.instrument.MeterRegistry;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.Date;
import java.util.List;
import java.util.UUID;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicLong;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.amqp.core.Message;
import org.springframework.amqp.core.MessageDeliveryMode;
import org.springframework.amqp.core.MessageProperties;
import org.springframework.amqp.rabbit.connection.CorrelationData;
import org.springframework.amqp.rabbit.core.RabbitTemplate;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

@Component
public class OutboxPublisher {
  private static final Logger LOG = LoggerFactory.getLogger(OutboxPublisher.class);
  private final OutboxRepository outbox;
  private final RabbitTemplate rabbit;
  private final JsonCodec json;
  private final boolean background;
  private final int batchSize;
  private final int maxRetries;
  private final long confirmTimeoutMs;
  private final Counter published;
  private final Counter retried;
  private final AtomicLong pending = new AtomicLong();

  public OutboxPublisher(
      OutboxRepository outbox,
      RabbitTemplate rabbit,
      JsonCodec json,
      MeterRegistry metrics,
      @Value("${cae.background.enabled:true}") boolean background,
      @Value("${cae.outbox.batch-size:20}") int batchSize,
      @Value("${cae.outbox.max-publish-attempts:8}") int maxRetries,
      @Value("${cae.outbox.confirm-timeout-ms:3000}") long confirmTimeoutMs) {
    this.outbox = outbox;
    this.rabbit = rabbit;
    this.json = json;
    this.background = background;
    this.batchSize = batchSize;
    this.maxRetries = maxRetries;
    this.confirmTimeoutMs = confirmTimeoutMs;
    if (batchSize < 1 || batchSize > 200 || maxRetries < 1 || confirmTimeoutMs < 1)
      throw new IllegalArgumentException("Outbox publisher configuration is invalid");
    rabbit.setMandatory(true);
    published = metrics.counter("cae.outbox.published");
    retried = metrics.counter("cae.outbox.publish.retry");
    Gauge.builder("cae.outbox.pending", pending, AtomicLong::get).register(metrics);
  }

@Scheduled(fixedDelayString = "${cae.outbox.scan-ms:500}")
public void scan() {
  if (background) publishBatch();
}

public int publishBatch() {
  return publish(outbox.claim(UUID.randomUUID().toString(), batchSize, lease()));
}

public int publishIds(List<Long> ids) {
  return publish(outbox.claimIds(UUID.randomUUID().toString(), ids, lease()));
}

private Duration lease() {
  return Duration.ofMillis(batchSize * (confirmTimeoutMs + 3000L) + 30_000);
}

private int publish(List<ClaimedEvent> events) {
  int sent = 0;
  for (ClaimedEvent event : events) {
    CorrelationData correlation = new CorrelationData(event.envelope().deliveryId());
    try {
      MessageProperties properties = new MessageProperties();
      properties.setContentType(MessageProperties.CONTENT_TYPE_JSON);
      properties.setContentEncoding(StandardCharsets.UTF_8.name());
      properties.setDeliveryMode(MessageDeliveryMode.PERSISTENT);
      properties.setMessageId(event.envelope().deliveryId());
      properties.setType(event.envelope().eventType());
      properties.setTimestamp(Date.from(event.envelope().occurredAt()));
      properties.setHeader("logicalEventId", event.envelope().eventId());
      properties.setHeader("deliveryAttempt", event.envelope().deliveryAttempt());
      Message message =
          new Message(
              json.write(event.envelope().asMap()).getBytes(StandardCharsets.UTF_8), properties);
      rabbit.send(event.exchange(), event.routing(), message, correlation);
      CorrelationData.Confirm confirm =
          correlation.getFuture().get(confirmTimeoutMs, TimeUnit.MILLISECONDS);
      if (!confirm.isAck())
        throw new IllegalStateException("Broker negatively acknowledged publication");
      if (correlation.getReturned() != null)
        throw new IllegalStateException("Mandatory publication was returned as unroutable");
      if (outbox.markSent(event)) {
        published.increment();
        sent++;
      }
    } catch (InterruptedException failure) {
      Thread.currentThread().interrupt();
      retry(event, "Publisher interrupted before confirmed delivery");
      break;
    } catch (Exception failure) {
      retry(event, failure.getClass().getSimpleName() + ": " + failure.getMessage());
    }
  }
  pending.set(outbox.pendingCount());
  return sent;
}

private void retry(ClaimedEvent event, String reason) {
  if (outbox.retryOrDead(event, reason, maxRetries, Duration.ofMillis(500))) retried.increment();
  LOG.warn(
      "Outbox delivery deferred eventId={} deliveryId={} reason={}",
      event.envelope().eventId(),
      event.envelope().deliveryId(),
      OutboxRepository.bounded(reason));
}

package com.example.cae.outbox;

import com.example.cae.common.JsonCodec;
import com.example.cae.common.SqlRows;
import com.example.cae.messaging.CommandEnvelope;
import com.example.cae.messaging.RabbitTopology;
import java.sql.Timestamp;
import java.time.Duration;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

@Repository
public class OutboxRepository {
  private final JdbcTemplate jdbc;
  private final JsonCodec json;

public OutboxRepository(JdbcTemplate jdbc, JsonCodec json) {
  this.jdbc = jdbc;
  this.json = json;
}

/** Invoked inside the transaction which updated the Job and inserted its journal entry. */
@Transactional(propagation = Propagation.MANDATORY)
public void appendJobEvent(
    long jobId,
    String eventType,
    String fromStatus,
    String toStatus,
    Map<String, Object> detail) {
  String jobNo = jobNo(jobId);
  Map<String, Object> eventPayload = new LinkedHashMap<>(detail == null ? Map.of() : detail);
  if (fromStatus != null) eventPayload.put("fromStatus", fromStatus);
  if (toStatus != null) eventPayload.put("toStatus", toStatus);
  append(
      CommandEnvelope.create(eventType, jobId, jobNo, eventPayload),
      RabbitTopology.EVENT_EXCHANGE,
      "job." + eventType,
      Instant.now());
  if (RabbitTopology.isCommand(eventType))
    appendCommand(jobId, eventType, detail == null ? Map.of() : detail);
  if (eventType.equals("EXECUTION_ALLOCATED"))
    appendCommand(jobId, "EXECUTION_SUBMIT_REQUESTED", detail);
}

@Transactional(propagation = Propagation.MANDATORY)
public String appendCommand(long jobId, String eventType, Map<String, Object> payload) {
  CommandEnvelope command = CommandEnvelope.create(eventType, jobId, jobNo(jobId), payload);
  append(
      command, RabbitTopology.COMMAND_EXCHANGE, RabbitTopology.route(eventType), Instant.now());
  return command.eventId();
}

@Transactional(propagation = Propagation.MANDATORY)
public String appendRetry(
    CommandEnvelope original, int attempt, Instant availableAt, String reason) {
  CommandEnvelope retry = original.retry(attempt);
  append(
      retry,
      RabbitTopology.COMMAND_EXCHANGE,
      RabbitTopology.route(retry.eventType()),
      availableAt);
  jdbc.update(
      "UPDATE cae_outbox_event SET last_error=? WHERE event_id=?",
      bounded(reason),
      retry.deliveryId());
  return retry.deliveryId();
}

@Transactional(propagation = Propagation.MANDATORY)
public void append(
    CommandEnvelope envelope, String exchange, String routing, Instant availableAt) {
  jdbc.update(
      "INSERT INTO cae_outbox_event(event_id,logical_event_id,aggregate_id,event_type,payload,exchange_name,routing_key,delivery_attempt,next_retry_time) VALUES(?,?,?,?,?,?,?,?,?)",
      envelope.deliveryId(),
      envelope.eventId(),
      envelope.jobId(),
      envelope.eventType(),
      json.write(envelope.asMap()),
      exchange,
      routing,
      envelope.deliveryAttempt(),
      Timestamp.from(availableAt));
}

@Transactional
public List<ClaimedEvent> claim(String owner, int limit, Duration lease) {
  if (limit < 1 || limit > 200) throw new IllegalArgumentException("Outbox batch must be 1..200");
  return claimEligible(owner, limit, lease, List.of());
}

/**
 * Scoped publication is useful for administration, benchmarks and tests without touching other
 * aggregates.
 */
@Transactional
public List<ClaimedEvent> claimIds(String owner, List<Long> ids, Duration lease) {
  if (ids.isEmpty()) return List.of();
  if (ids.size() > 200 || ids.stream().anyMatch(id -> id == null || id <= 0))
    throw new IllegalArgumentException("Outbox IDs must be a bounded positive list");
  return claimEligible(owner, ids.size(), lease, ids);
}

private List<ClaimedEvent> claimEligible(
    String owner, int limit, Duration lease, List<Long> ids) {
  if (owner == null
      || !owner.matches("[A-Za-z0-9_-]{1,64}")
      || lease.isNegative()
      || lease.isZero()) throw new IllegalArgumentException("Outbox lease is invalid");
  String scope =
      ids.isEmpty()
          ? ""
          : " AND id IN (" + String.join(",", ids.stream().map(id -> "?").toList()) + ")";
  List<Object> parameters = new ArrayList<>(ids);
  parameters.add(limit);
  List<Map<String, Object>> rows =
      jdbc.query(
          "SELECT * FROM cae_outbox_event WHERE ((status IN ('NEW','RETRY') AND next_retry_time<=UTC_TIMESTAMP(6)) OR (status='PUBLISHING' AND claim_until<=UTC_TIMESTAMP(6)))"
              + scope
              + " ORDER BY next_retry_time,id LIMIT ? FOR UPDATE SKIP LOCKED",
          SqlRows.MAPPER,
          parameters.toArray());
  Instant until = Instant.now().plus(lease);
  List<ClaimedEvent> result = new ArrayList<>();
  for (Map<String, Object> row : rows) {
    long id = SqlRows.id(row);
    jdbc.update(
        "UPDATE cae_outbox_event SET status='PUBLISHING',claim_owner=?,claim_until=? WHERE id=?",
        owner,
        Timestamp.from(until),
        id);
    result.add(
        new ClaimedEvent(
            id,
            owner,
            row.get("exchangeName").toString(),
            row.get("routingKey").toString(),
            CommandEnvelope.from(json.readMap(row.get("payload"))),
            ((Number) row.get("retryCount")).intValue()));
  }
  return result;
}

public boolean markSent(ClaimedEvent event) {
  return jdbc.update(
          "UPDATE cae_outbox_event SET status='SENT',published_at=UTC_TIMESTAMP(6),claim_owner=NULL,claim_until=NULL,last_error=NULL WHERE id=? AND status='PUBLISHING' AND claim_owner=?",
          event.id(),
          event.owner())
      == 1;
}

@Transactional
public boolean retryOrDead(ClaimedEvent event, String reason, int maxRetries, Duration base) {
  List<Map<String, Object>> rows =
      jdbc.query(
          "SELECT retry_count FROM cae_outbox_event WHERE id=? AND status='PUBLISHING' AND claim_owner=? FOR UPDATE",
          SqlRows.MAPPER,
          event.id(),
          event.owner());
  if (rows.isEmpty()) return false;
  int attempts = ((Number) rows.get(0).get("retryCount")).intValue() + 1;
  boolean dead = attempts >= maxRetries;
  jdbc.update(
      "UPDATE cae_outbox_event SET status=?,retry_count=?,next_retry_time=?,claim_owner=NULL,claim_until=NULL,last_error=? WHERE id=? AND claim_owner=?",
      dead ? "DEAD" : "RETRY",
      attempts,
      Timestamp.from(Instant.now().plus(backoff(base, attempts))),
      bounded(reason),
      event.id(),
      event.owner());
  return true;
}

public long pendingCount() {
  return jdbc.queryForObject(
      "SELECT COUNT(*) FROM cae_outbox_event WHERE status IN ('NEW','RETRY','PUBLISHING')",
      Long.class);
}

private String jobNo(long jobId) {
  return jdbc.queryForObject("SELECT job_no FROM cae_job WHERE id=?", String.class, jobId);
}

public static Duration backoff(Duration base, int failures) {
  long multiplier = 1L << Math.min(Math.max(failures - 1, 0), 16);
  return Duration.ofMillis(
      Math.min(30_000, Math.multiplyExact(Math.min(base.toMillis(), 30_000), multiplier)));
}

public static String bounded(String value) {
  if (value == null) return null;
  return value.length() <= 1000 ? value : value.substring(0, 1000);
}

package com.example.cae.project;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;
import java.util.List;
import java.util.Map;
import org.springframework.http.HttpStatus;
import org.springframework.security.core.Authentication;
import org.springframework.web.bind.annotation.*;

@RestController
@RequestMapping("/api/v1")
public class ProjectController {
  private final ProjectService projects;

public ProjectController(ProjectService projects) {
  this.projects = projects;
}

public record CreateProject(
    @NotBlank @Pattern(regexp = "[A-Za-z0-9_-]{1,64}") String code,
    @NotBlank @Size(max = 160) String name,
    @Size(max = 1000) String description) {}

public record CreateModel(
    @NotNull Long projectId,
    @NotBlank @Pattern(regexp = "[A-Za-z0-9_-]{1,64}") String code,
    @NotBlank @Size(max = 160) String name) {}

public record CreateRevision(
    @NotNull Long modelId,
    @NotBlank @Size(max = 64) String revision,
    @Size(max = 1000) String description) {}

  @GetMapping("/projects")
  public List<Map<String, Object>> projects(Authentication user) {
    return projects.projects(user);
  }

  @PostMapping("/projects")
  @ResponseStatus(HttpStatus.CREATED)
  public Map<String, Object> project(
      Authentication user, @Valid @RequestBody CreateProject request) {
    return projects.createProject(user, request.code(), request.name(), request.description());
  }

  @GetMapping("/models")
  public List<Map<String, Object>> models(
      Authentication user, @RequestParam(required = false) Long projectId) {
    return projects.models(user, projectId);
  }

  @PostMapping("/models")
  @ResponseStatus(HttpStatus.CREATED)
  public Map<String, Object> model(Authentication user, @Valid @RequestBody CreateModel request) {
    return projects.createModel(user, request.projectId(), request.code(), request.name());
  }

  @GetMapping("/model-revisions")
  public List<Map<String, Object>> revisions(
      Authentication user, @RequestParam(required = false) Long projectId) {
    return projects.revisions(user, projectId);
  }

  @PostMapping("/model-revisions")
  @ResponseStatus(HttpStatus.CREATED)
  public Map<String, Object> revision(
      Authentication user, @Valid @RequestBody CreateRevision request) {
    return projects.createRevision(
        user, request.modelId(), request.revision(), request.description());
  }
}

package com.example.cae.project;

import com.example.cae.auth.ProjectAccess;
import com.example.cae.common.ApiException;
import com.example.cae.common.SqlRows;
import java.sql.Statement;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class ProjectService {
  private final JdbcTemplate jdbc;
  private final ProjectAccess access;

public ProjectService(JdbcTemplate jdbc, ProjectAccess access) {
  this.jdbc = jdbc;
  this.access = access;
}

public List<Map<String, Object>> projects(Authentication user) {
  if (access.admin(user))
    return jdbc.query("SELECT * FROM cae_project ORDER BY id", SqlRows.MAPPER);
  return jdbc.query(
      "SELECT p.* FROM cae_project p JOIN cae_project_member m ON m.project_id=p.id WHERE m.username=? ORDER BY p.id",
      SqlRows.MAPPER,
      user.getName());
}

@Transactional
public Map<String, Object> createProject(
    Authentication user, String code, String name, String description) {
  long id =
      insert(
          "INSERT INTO cae_project(code,name,description,owner_id) VALUES(?,?,?,?)",
          code,
          name,
          description,
          user.getName());
  jdbc.update(
      "INSERT INTO cae_project_member(project_id,username,member_role) VALUES(?,?,?)",
      id,
      user.getName(),
      access.lead(user) ? "PROJECT_LEAD" : "CAE_ENGINEER");
  return jdbc.queryForObject("SELECT * FROM cae_project WHERE id=?", SqlRows.MAPPER, id);
}

public List<Map<String, Object>> models(Authentication user, Long projectId) {
  if (projectId != null) {
    access.require(user, projectId);
    return jdbc.query(
        "SELECT * FROM cae_model WHERE project_id=? ORDER BY id", SqlRows.MAPPER, projectId);
  }
  if (access.admin(user))
    return jdbc.query("SELECT * FROM cae_model ORDER BY id", SqlRows.MAPPER);
  return jdbc.query(
      "SELECT m.* FROM cae_model m JOIN cae_project_member p ON p.project_id=m.project_id WHERE p.username=? ORDER BY m.id",
      SqlRows.MAPPER,
      user.getName());
}

@Transactional
public Map<String, Object> createModel(
    Authentication user, long projectId, String code, String name) {
  access.require(user, projectId);
  long id =
      insert("INSERT INTO cae_model(project_id,code,name) VALUES(?,?,?)", projectId, code, name);
  return jdbc.queryForObject("SELECT * FROM cae_model WHERE id=?", SqlRows.MAPPER, id);
}

public List<Map<String, Object>> revisions(Authentication user, Long projectId) {
  if (projectId != null) {
    access.require(user, projectId);
    return jdbc.query(
        "SELECT r.*,m.project_id,m.name AS model_name,m.code AS model_code FROM cae_model_revision r JOIN cae_model m ON m.id=r.model_id WHERE m.project_id=? ORDER BY r.id",
        SqlRows.MAPPER,
        projectId);
  }
  if (access.admin(user))
    return jdbc.query(
        "SELECT r.*,m.project_id,m.name AS model_name,m.code AS model_code FROM cae_model_revision r JOIN cae_model m ON m.id=r.model_id ORDER BY r.id",
        SqlRows.MAPPER);
  return jdbc.query(
      "SELECT r.*,m.project_id,m.name AS model_name,m.code AS model_code FROM cae_model_revision r JOIN cae_model m ON m.id=r.model_id JOIN cae_project_member p ON p.project_id=m.project_id WHERE p.username=? ORDER BY r.id",
      SqlRows.MAPPER,
      user.getName());
}

@Transactional
public Map<String, Object> createRevision(
    Authentication user, long modelId, String revision, String description) {
  List<Long> projects =
      jdbc.queryForList("SELECT project_id FROM cae_model WHERE id=?", Long.class, modelId);
  if (projects.isEmpty()) throw ApiException.notFound("Model");
  access.require(user, projects.get(0));
  long id =
      insert(
          "INSERT INTO cae_model_revision(model_id,revision,description) VALUES(?,?,?)",
          modelId,
          revision,
          description);
  return jdbc.queryForObject("SELECT * FROM cae_model_revision WHERE id=?", SqlRows.MAPPER, id);
}

public void requireRevision(long projectId, long modelRevisionId) {
  Integer matching =
      jdbc.queryForObject(
          "SELECT COUNT(*) FROM cae_model_revision r JOIN cae_model m ON m.id=r.model_id WHERE r.id=? AND m.project_id=?",
          Integer.class,
          modelRevisionId,
          projectId);
  if (matching == null || matching == 0)
    throw ApiException.invalid("Model revision must belong to the selected project");
}

private long insert(String sql, Object... args) {
  GeneratedKeyHolder keys = new GeneratedKeyHolder();
  jdbc.update(
      connection -> {
        var statement = connection.prepareStatement(sql, Statement.RETURN_GENERATED_KEYS);
        for (int i = 0; i < args.length; i++) statement.setObject(i + 1, args[i]);
        return statement;
      },
      keys);
  return keys.getKey().longValue();
}

package com.example.cae.report;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Service;

/** All engineering arithmetic belongs to the control plane, never a report template. */
@Service
public class BaselineComparisonService {
  public List<Map<String, Object>> compare(
      List<Map<String, Object>> current, List<Map<String, Object>> baseline) {
    Map<String, Map<String, Object>> indexed = new LinkedHashMap<>();
    baseline.forEach(row -> indexed.put(row.get("metricCode").toString(), row));
    List<Map<String, Object>> comparisons = new ArrayList<>();
    for (Map<String, Object> metric : current) {
      Map<String, Object> row = new LinkedHashMap<>();
      row.put("metricCode", metric.get("metricCode"));
      row.put("unit", metric.get("unit"));
      BigDecimal now = decimal(metric.get("valueNum"));
      Map<String, Object> old = indexed.get(metric.get("metricCode"));
      BigDecimal before = old == null ? null : decimal(old.get("valueNum"));
      boolean compatible =
          old != null
              && metric.get("unit").equals(old.get("unit"))
              && metric.get("dimension").equals(old.get("dimension"));
      row.put("current", plain(now));
      row.put("baseline", compatible ? plain(before) : null);
      row.put("delta", null);
      row.put("deltaPercent", null);
      if (now == null) row.put("status", "TEXT");
      else if (old == null) row.put("status", baseline.isEmpty() ? "NO_BASELINE" : "MISSING");
      else if (!compatible || before == null) row.put("status", "MISSING");
      else {
        BigDecimal delta = now.subtract(before);
        row.put("delta", plain(delta));
        row.put("status", before.signum() == 0 ? "ZERO_BASELINE" : "MATCHED");
        if (before.signum() != 0)
          row.put(
              "deltaPercent",
              plain(
                  delta.multiply(BigDecimal.valueOf(100)).divide(before, 6, RoundingMode.HALF_UP)));
      }
      comparisons.add(row);
    }
    return comparisons;
  }

private static BigDecimal decimal(Object value) {
  return value == null ? null : new BigDecimal(value.toString());
}

public static String plain(BigDecimal value) {
  return value == null ? null : value.stripTrailingZeros().toPlainString();
}

package com.example.cae.report;

import com.example.cae.common.SqlRows;
import com.example.cae.job.domain.JobStatus;
import com.example.cae.job.repository.JobRepository;
import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;
import org.springframework.stereotype.Component;

/** Job locks guard the one pipeline allowed to advance its main state. */
@Component
public class PipelineBinding {
  private final JobRepository jobs;

public PipelineBinding(JobRepository jobs) {
  this.jobs = jobs;
}

public Map<String, Object> completed(Map<String, Object> job, Map<String, Object> parse) {
  if (job.get("activePipelineParseId") == null
      || Set.of("POST_PROCESS_FAILED", "REPORT_FAILED").contains(job.get("status"))) {
    Map<String, Object> fields = new LinkedHashMap<>();
    fields.put("activePipelineParseId", SqlRows.id(parse));
    fields.put("activePostVersion", 1);
    fields.put("activeReportVersion", 1);
    fields.put("pipelineGeneration", ((Number) job.get("pipelineGeneration")).longValue() + 1);
    fields.put("failureCode", null);
    fields.put("failureMessage", null);
    job = jobs.patch(job, fields);
    if (Set.of("POST_PROCESS_FAILED", "REPORT_FAILED").contains(job.get("status")))
      job =
          jobs.transition(
              job,
              JobStatus.POST_PROCESSING,
              "RESULT_PARSE_RECOVERED",
              Map.of("parseRecordId", SqlRows.id(parse)));
  }
  return job;
}

public boolean active(Map<String, Object> job, Map<String, Object> stage) {
  return java.util.Objects.equals(job.get("activePipelineParseId"), stage.get("parseRecordId"))
      && ((Number) job.get("pipelineGeneration")).longValue()
          == ((Number) stage.get("pipelineGeneration")).longValue()
      && ((Number)
                  job.get(
                      stage.get("kind").equals("POST")
                          ? "activePostVersion"
                          : "activeReportVersion"))
              .intValue()
          == ((Number) stage.get("stageVersion")).intValue();
}

public boolean canFailParse(Map<String, Object> job, long parseId) {
  return job.get("activePipelineParseId") == null
      || ((Number) job.get("activePipelineParseId")).longValue() == parseId;
}

package com.example.cae.report;

import com.example.cae.common.JsonCodec;
import com.example.cae.messaging.CommandEnvelope;
import com.example.cae.messaging.InboxRepository;
import com.rabbitmq.client.Channel;
import io.micrometer.core.instrument.MeterRegistry;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.time.Duration;
import java.util.concurrent.TimeUnit;
import org.springframework.amqp.core.Message;
import org.springframework.amqp.rabbit.annotation.RabbitListener;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.dao.DataAccessException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Component;

@Component
public class PipelineCommandListener {
  private final JsonCodec json;
  private final InboxRepository inbox;
  private final PipelineService pipeline;
  private final MeterRegistry metrics;
  private final int attempts;
  private final Duration retryBase;

  public PipelineCommandListener(
      JsonCodec json,
      InboxRepository inbox,
      PipelineService pipeline,
      MeterRegistry metrics,
      @Value("${cae.mq.max-delivery-attempts:4}") int attempts,
      @Value("${cae.mq.retry-base-ms:500}") long retryMs) {
    this.json = json;
    this.inbox = inbox;
    this.pipeline = pipeline;
    this.metrics = metrics;
    this.attempts = attempts;
    retryBase = Duration.ofMillis(retryMs);
  }

@RabbitListener(
    queues = "cae.job.postprocess",
    ackMode = "MANUAL",
    autoStartup = "${cae.mq.listeners-enabled:true}",
    concurrency = "2")
public void post(Message message, Channel channel) throws IOException {
  consume(message, channel, "POST");
}

@RabbitListener(
    queues = "cae.job.report",
    ackMode = "MANUAL",
    autoStartup = "${cae.mq.listeners-enabled:true}",
    concurrency = "2")
public void report(Message message, Channel channel) throws IOException {
  consume(message, channel, "REPORT");
}

private void consume(Message message, Channel channel, String kind) throws IOException {
  long tag = message.getMessageProperties().getDeliveryTag();
  CommandEnvelope command;
  try {
    command =
        CommandEnvelope.from(json.readMap(new String(message.getBody(), StandardCharsets.UTF_8)));
    if (!command
        .eventType()
        .equals(kind.equals("POST") ? "POST_PROCESS_REQUESTED" : "REPORT_REQUESTED"))
      throw new IllegalArgumentException("Wrong stage event");
  } catch (RuntimeException malformed) {
    metrics.counter("cae.mq.consume.failure").increment();
    channel.basicReject(tag, false);
    return;
  }
  String consumer = kind.equals("POST") ? "post-process-v1" : "draft-report-v1";
  try {
    var claim = inbox.claim(command, consumer, Duration.ofSeconds(60));
    switch (claim.disposition()) {
      case DONE -> ack(channel, tag, kind);
      case DEAD -> channel.basicReject(tag, false);
      case BUSY -> {
        inbox.defer(command, consumer);
        ack(channel, tag, kind);
      }
      case ACQUIRED -> {
        RuntimeException failure = null;
        try {
          pipeline.process(command, kind);
        } catch (PipelineService.StageBusyException busy) {
          inbox.await(command, consumer, claim.owner(), Duration.ofSeconds(5));
          ack(channel, tag, kind);
          return;
        } catch (DataIntegrityViolationException constraint) {
          failure = constraint;
        } catch (DataAccessException unavailable) {
          throw unavailable;
        } catch (RuntimeException business) {
          failure = business;
        }
        if (failure == null) {
          inbox.complete(command, consumer, claim.owner());
          ack(channel, tag, kind);
        } else {
          metrics.counter("cae.mq.consume.failure").increment();
          var disposition =
              inbox.fail(
                  command,
                  consumer,
                  claim.owner(),
                  failure.getClass().getSimpleName() + ": " + failure.getMessage(),
                  attempts,
                  retryBase,
                  () -> {});
          if (disposition == InboxRepository.FailureDisposition.RETRY) {
            metrics.counter("cae.mq.stage.retry", "stage", kind).increment();
            ack(channel, tag, kind);
          } else {
            metrics.counter("cae.mq.stage.dead", "stage", kind).increment();
            channel.basicReject(tag, false);
          }
        }
      }
    }
  } catch (DataAccessException | InboxRepository.LostLeaseException unavailable) {
    try {
      TimeUnit.MILLISECONDS.sleep(500);
    } catch (InterruptedException stopped) {
      Thread.currentThread().interrupt();
    }
    channel.basicNack(tag, false, true);
  } catch (IllegalArgumentException malformed) {
    channel.basicReject(tag, false);
  }
}

private void ack(Channel channel, long tag, String kind) throws IOException {
  channel.basicAck(tag, false);
  metrics.counter("cae.mq.stage.acked", "stage", kind).increment();
}

package com.example.cae.report;

import com.example.cae.common.ApiException;
import com.example.cae.common.JsonCodec;
import com.example.cae.common.SqlRows;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import java.util.UUID;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Repository;

@Repository
public class PipelineRepository {
  public List<Map<String, Object>> baselines(Map<String, Object> job, Map<String, Object> parse) {
    return jdbc.query(
        "SELECT j.job_no,j.id AS job_id,p.id AS parse_record_id,r.revision AS model_revision,j.created_at FROM cae_result_parse_record p JOIN cae_job j ON j.id=p.job_id JOIN cae_model_revision r ON r.id=j.model_revision_id WHERE j.status='SUCCESS' AND j.id<>? AND j.project_id=? AND r.model_id=(SELECT model_id FROM cae_model_revision WHERE id=?) AND j.analysis_type=? AND j.condition_code=? AND p.status='COMPLETE' AND p.parser_version=? AND p.subcase=? AND p.execution_id=j.current_execution_id ORDER BY j.id DESC LIMIT 100",
        SqlRows.MAPPER,
        SqlRows.id(job),
        job.get("projectId"),
        job.get("modelRevisionId"),
        job.get("analysisType"),
        job.get("conditionCode"),
        parse.get("parserVersion"),
        parse.get("subcase"));
  }

  public List<Map<String, Object>> templates() {
    return jdbc.query("SELECT * FROM cae_report_template ORDER BY code", SqlRows.MAPPER);
  }

public void template(String code, boolean enabled) {
  if (jdbc.update(
          "UPDATE cae_report_template SET enabled=? WHERE code=? AND version='v1'", enabled, code)
      != 1) throw ApiException.notFound("Report template");
}

public boolean templateEnabled(String code) {
  return jdbc.queryForObject(
          "SELECT COUNT(*) FROM cae_report_template WHERE code=? AND version='v1' AND enabled=TRUE",
          Integer.class,
          code)
      == 1;
}

public Optional<Map<String, Object>> intent(long job, String key) {
  return jdbc
      .query(
          "SELECT * FROM cae_report_generation_request WHERE job_id=? AND idempotency_key=?",
          SqlRows.MAPPER,
          job,
          key)
      .stream()
      .findFirst();
}

public void intent(long job, String key, String fingerprint, long parse, int version) {
  jdbc.update(
      "INSERT INTO cae_report_generation_request(job_id,idempotency_key,request_fingerprint,parse_record_id,stage_version) VALUES(?,?,?,?,?)",
      job,
      key,
      fingerprint,
      parse,
      version);
}

private final JdbcTemplate jdbc;
private final JsonCodec json;
private final RenderFingerprint fingerprints;

public PipelineRepository(JdbcTemplate jdbc, JsonCodec json, RenderFingerprint fingerprints) {
  this.jdbc = jdbc;
  this.json = json;
  this.fingerprints = fingerprints;
}

public Map<String, Object> parse(long id) {
  return jdbc
      .query("SELECT * FROM cae_result_parse_record WHERE id=?", SqlRows.MAPPER, id)
      .stream()
      .findFirst()
      .orElseThrow(() -> ApiException.notFound("Parse record"));
}

public List<Map<String, Object>> metrics(long parseId) {
  return jdbc.query(
      "SELECT * FROM result_metric WHERE parse_record_id=? ORDER BY metric_code",
      SqlRows.MAPPER,
      parseId);
}

public Map<String, Object> context(long jobId) {
  return jdbc.query(
          "SELECT p.code AS project_code,p.name AS project_name,m.code AS model_code,m.name AS model_name,r.revision AS model_revision FROM cae_job j JOIN cae_project p ON p.id=j.project_id JOIN cae_model_revision r ON r.id=j.model_revision_id JOIN cae_model m ON m.id=r.model_id WHERE j.id=?",
          SqlRows.MAPPER,
          jobId)
      .get(0);
}

public Optional<Map<String, Object>> baseline(
    Map<String, Object> job, Map<String, Object> parse, String explicit) {
  String suffix = explicit == null ? "AND j.id<? ORDER BY j.id DESC LIMIT 1" : "AND j.job_no=?";
  return jdbc
      .query(
          "SELECT p.*,j.job_no FROM cae_result_parse_record p JOIN cae_job j ON j.id=p.job_id JOIN cae_model_revision revision ON revision.id=j.model_revision_id WHERE j.status='SUCCESS' AND j.id<>? AND j.project_id=? AND revision.model_id=(SELECT model_id FROM cae_model_revision WHERE id=?) AND j.analysis_type=? AND j.condition_code=? AND p.status='COMPLETE' AND p.parser_version=? AND p.subcase=? "
              + suffix,
          SqlRows.MAPPER,
          SqlRows.id(job),
          job.get("projectId"),
          job.get("modelRevisionId"),
          job.get("analysisType"),
          job.get("conditionCode"),
          parse.get("parserVersion"),
          parse.get("subcase"),
          explicit == null ? SqlRows.id(job) : explicit)
      .stream()
      .findFirst();
}

public Optional<Map<String, Object>> find(long parse, String kind, int version, boolean lock) {
  return jdbc
      .query(
          "SELECT * FROM cae_pipeline_stage WHERE parse_record_id=? AND kind=? AND stage_version=?"
              + (lock ? " FOR UPDATE" : ""),
          SqlRows.MAPPER,
          parse,
          kind,
          version)
      .stream()
      .findFirst()
      .map(this::decode);
}

public Map<String, Object> create(
    Map<String, Object> job,
    Map<String, Object> parse,
    String kind,
    int version,
    int postVersion,
    Map<String, Object> request) {
  jdbc.update(
      "INSERT INTO cae_pipeline_stage(job_id,execution_id,parse_record_id,parser_version,kind,stage_version,post_version,request_json,request_fingerprint,pipeline_generation) VALUES(?,?,?,?,?,?,?,?,?,?)",
      SqlRows.id(job),
      parse.get("executionId"),
      SqlRows.id(parse),
      parse.get("parserVersion"),
      kind,
      version,
      postVersion,
      json.write(request),
      fingerprints.of(request),
      job.get("pipelineGeneration"));
  return find(SqlRows.id(parse), kind, version, true).orElseThrow();
}

public Map<String, Object> claim(Map<String, Object> row) {
  String owner = UUID.randomUUID().toString();
  jdbc.update(
      "UPDATE cae_pipeline_stage SET status='RUNNING',claim_owner=?,claim_generation=claim_generation+1,claim_until=?,failure_message=NULL,updated_at=UTC_TIMESTAMP(6) WHERE id=?",
      owner,
      Timestamp.from(Instant.now().plusSeconds(90)),
      SqlRows.id(row));
  return find(
          ((Number) row.get("parseRecordId")).longValue(),
          row.get("kind").toString(),
          ((Number) row.get("stageVersion")).intValue(),
          true)
      .orElseThrow();
}

public boolean owns(Map<String, Object> current, Map<String, Object> claim) {
  return "RUNNING".equals(current.get("status"))
      && java.util.Objects.equals(current.get("claimOwner"), claim.get("claimOwner"))
      && java.util.Objects.equals(current.get("claimGeneration"), claim.get("claimGeneration"))
      && current.get("claimUntil") != null
      && Instant.parse(current.get("claimUntil").toString()).isAfter(Instant.now());
}

public void complete(Map<String, Object> row, long manifestId) {
  jdbc.update(
      "UPDATE cae_pipeline_stage SET status='COMPLETE',manifest_artifact_id=?,claim_owner=NULL,claim_until=NULL,failure_message=NULL,completed_at=UTC_TIMESTAMP(6),updated_at=UTC_TIMESTAMP(6) WHERE id=?",
      manifestId,
      SqlRows.id(row));
}

public void fail(Map<String, Object> row, String reason) {
  jdbc.update(
      "UPDATE cae_pipeline_stage SET status='FAILED',claim_owner=NULL,claim_until=NULL,failure_message=?,updated_at=UTC_TIMESTAMP(6) WHERE id=?",
      reason.substring(0, Math.min(1000, reason.length())),
      SqlRows.id(row));
}

public void next(long id) {
  jdbc.update(
      "UPDATE cae_pipeline_stage SET next_requested_at=UTC_TIMESTAMP(6) WHERE id=? AND next_requested_at IS NULL",
      id);
}

public int nextVersion(long parse) {
  return jdbc.queryForObject(
      "SELECT COALESCE(MAX(stage_version),0)+1 FROM cae_pipeline_stage WHERE parse_record_id=?",
      Integer.class,
      parse);
}

public void reset(Map<String, Object> stage, long generation) {
  jdbc.update(
      "UPDATE cae_pipeline_stage SET status='REQUESTED',claim_owner=NULL,claim_until=NULL,pipeline_generation=?,failure_message=NULL WHERE id=?",
      generation,
      SqlRows.id(stage));
}

public List<Map<String, Object>> stages(long job) {
  return jdbc
      .query("SELECT * FROM cae_pipeline_stage WHERE job_id=? ORDER BY id", SqlRows.MAPPER, job)
      .stream()
      .map(this::decode)
      .toList();
}

  private Map<String, Object> publicReport(Map<String, Object> row) {
    row.put("context", json.readMap(row.remove("contextJson")));
    row.put("downloadUrl", "/api/v1/artifacts/" + row.get("artifactId") + "/download");
    return row;
  }

  private Map<String, Object> decode(Map<String, Object> row) {
    row.put("request", json.readMap(row.remove("requestJson")));
    return row;
  }
}

package com.example.cae.report;

import com.example.cae.artifact.ArtifactFileStore;
import com.example.cae.artifact.ArtifactRepository;
import com.example.cae.common.ApiException;
import com.example.cae.common.JsonCodec;
import com.example.cae.common.SqlRows;
import com.example.cae.job.validation.InputSnapshotService;
import java.math.BigDecimal;
import java.time.Instant;
import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.stereotype.Component;

@Component
public class PipelineRequestBuilder {
  private final PipelineRepository repository;
  private final ArtifactRepository artifacts;
  private final ArtifactFileStore files;
  private final InputSnapshotService snapshots;
  private final BaselineComparisonService comparison;
  private final JsonCodec json;

  public PipelineRequestBuilder(
      PipelineRepository repository,
      ArtifactRepository artifacts,
      ArtifactFileStore files,
      InputSnapshotService snapshots,
      BaselineComparisonService comparison,
      JsonCodec json) {
    this.repository = repository;
    this.artifacts = artifacts;
    this.files = files;
    this.snapshots = snapshots;
    this.comparison = comparison;
    this.json = json;
  }

  public Map<String, Object> post(
      Map<String, Object> job,
      Map<String, Object> execution,
      Map<String, Object> parse,
      int version,
      String baselineJob) {
    snapshots.verifySnapshot(job);
    Map<String, Object> result =
        artifacts.list(SqlRows.id(job)).stream()
            .filter(
                row ->
                    row.get("artifactType").equals("RESULT_JSON")
                        && java.util.Objects.equals(row.get("parseRecordId"), parse.get("id")))
            .findFirst()
            .orElseThrow(
                () ->
                    new IllegalArgumentException("Selected canonical result artifact is missing"));
    var descriptor =
        files.describe(files.requireJob(result.get("uri").toString(), job.get("jobNo").toString()));
    if (!descriptor.checksum().equals(result.get("checksum")))
      throw new IllegalArgumentException("Canonical result artifact changed");
    List<Map<String, Object>> metrics = repository.metrics(SqlRows.id(parse));
    if (metrics.size() != ((Number) parse.get("metricCount")).intValue())
      throw new IllegalArgumentException("Canonical metric set is incomplete");
    for (var row : metrics)
      if (!row.get("conditionCode").equals(parse.get("conditionCode"))
          || !row.get("subcase").equals(parse.get("subcase")))
        throw new IllegalArgumentException(
            "Canonical metric condition differs from selected parse");
    var base = repository.baseline(job, parse, baselineJob);
    if (baselineJob != null && base.isEmpty())
      throw ApiException.invalid("Baseline must be a compatible successful Job and parser version");
    List<Map<String, Object>> baseline =
        base.isEmpty() ? List.of() : repository.metrics(SqlRows.id(base.get()));
    Map<String, Object> body = new LinkedHashMap<>();
    body.put("schemaVersion", 1);
    body.put("jobNo", job.get("jobNo"));
    body.put("executionId", SqlRows.id(execution));
    body.put("executionRequestId", execution.get("submitRequestId"));
    body.put("externalExecutionId", execution.get("externalExecutionId"));
    body.put("nodeId", execution.get("nodeId"));
    body.put("pid", execution.get("pid"));
    body.put("processIdentity", execution.get("processIdentity"));
    body.put("parseRecordId", SqlRows.id(parse));
    body.put("parserVersion", parse.get("parserVersion"));
    body.put("postVersion", version);
    body.put("analysisType", parse.get("analysisType"));
    body.put("conditionCode", parse.get("conditionCode"));
    body.put("subcase", parse.get("subcase"));
    body.put("rawChecksum", parse.get("rawChecksum"));
    body.put("snapshotChecksum", job.get("inputChecksum"));
    body.put("resultJsonChecksum", descriptor.checksum());
    var context = new LinkedHashMap<>(repository.context(SqlRows.id(job)));
    context.put("maturity", parse.get("maturity"));
    body.put("context", context);
    List<Map<String, Object>> canonical = new ArrayList<>();
    for (var metric : metrics) {
      Map<String, Object> row = new LinkedHashMap<>();
      for (String key :
          List.of(
              "metricCode",
              "metricName",
              "valueText",
              "unit",
              "dimension",
              "status",
              "conditionCode",
              "subcase")) row.put(key, metric.get(key));
      row.put(
          "valueNum",
          metric.get("valueNum") == null
              ? null
              : BaselineComparisonService.plain(new BigDecimal(metric.get("valueNum").toString())));
      canonical.add(row);
    }
    body.put("metrics", canonical);
    body.put("comparisons", comparison.compare(metrics, baseline));
    body.put(
        "baseline",
        base.isEmpty()
            ? null
            : Map.of("jobNo", base.get().get("jobNo"), "parseRecordId", SqlRows.id(base.get())));
    List<Map<String, Object>> specs = new ArrayList<>();
    String[] kinds = {"CONTOUR", "MODE_SHAPE", "COMPARISON", "CURVE"};
    String[] names = {"contour.png", "mode-shape.png", "comparison.png", "curve.png"};
    for (int i = 0; i < 4; i++)
      specs.add(
          Map.of(
              "conditionCode",
              parse.get("conditionCode"),
              "resultType",
              kinds[i],
              "component",
              "SYNTHETIC_BODY",
              "subcase",
              parse.get("subcase"),
              "frame",
              0,
              "view",
              "ISOMETRIC",
              "selectionSet",
              "PUBLIC_DEMO",
              "outputName",
              names[i]));
    body.put("specs", specs);
    return body;
  }

  public Map<String, Object> report(Map<String, Object> post, int version) {
    if (!post.get("status").equals("COMPLETE")) throw new PipelineService.StageBusyException();
    Map<String, Object> request = new LinkedHashMap<>(json.readMap(post.get("request")));
    request.remove("specs");
    var manifest = artifacts.find(((Number) post.get("manifestArtifactId")).longValue());
    var descriptor = files.describe(files.safe(manifest.get("uri").toString()));
    if (!descriptor.checksum().equals(manifest.get("checksum")))
      throw new IllegalArgumentException("Selected post manifest changed");
    request.put("reportVersion", version);
    String template =
        request.get("analysisType").equals("STRUCTURE") ? "STRUCTURE_DRAFT" : "PILOT_DRAFT";
    if (!repository.templateEnabled(template))
      throw ApiException.conflict("The selected report template is disabled");
    request.put(
        "templateCode",
        request.get("analysisType").equals("STRUCTURE") ? "STRUCTURE_DRAFT" : "PILOT_DRAFT");
    request.put("templateVersion", "v1");
    request.put("generatedAt", Instant.now().toString());
    request.put("postManifestChecksum", descriptor.checksum());
    request.put("postRequestFingerprint", post.get("requestFingerprint"));
    return request;
  }
}

package com.example.cae.report;

import com.example.cae.artifact.ArtifactRepository;
import com.example.cae.common.ApiException;
import com.example.cae.common.JsonCodec;
import com.example.cae.common.SqlRows;
import com.example.cae.job.domain.JobStatus;
import com.example.cae.job.execution.ExecutionRepository;
import com.example.cae.job.repository.JobRepository;
import com.example.cae.messaging.CommandEnvelope;
import com.example.cae.result.ResultRepository;
import io.micrometer.core.instrument.MeterRegistry;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Objects;
import org.springframework.dao.DataAccessException;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

/** Short fenced transactions surround rendering; no stage allocates or submits a Solver. */
@Service
public class PipelineService {
  private final JobRepository jobs;
  private final ExecutionRepository executions;
  private final ResultRepository results;
  private final PipelineRepository repository;
  private final PipelineRequestBuilder builder;
  private final PipelineBinding binding;
  private final RenderClient client;
  private final WorkerResponseVerifier verifier;
  private final ArtifactRepository artifacts;
  private final JsonCodec json;
  private final TransactionTemplate tx;
  private final MeterRegistry metrics;

  public PipelineService(
      JobRepository jobs,
      ExecutionRepository executions,
      ResultRepository results,
      PipelineRepository repository,
      PipelineRequestBuilder builder,
      PipelineBinding binding,
      RenderClient client,
      WorkerResponseVerifier verifier,
      ArtifactRepository artifacts,
      JsonCodec json,
      TransactionTemplate tx,
      MeterRegistry metrics) {
    this.jobs = jobs;
    this.executions = executions;
    this.results = results;
    this.repository = repository;
    this.builder = builder;
    this.binding = binding;
    this.client = client;
    this.verifier = verifier;
    this.artifacts = artifacts;
    this.json = json;
    this.tx = tx;
    this.metrics = metrics;
  }

public void process(CommandEnvelope command, String kind) {
  Map<String, Object> job = jobs.findById(command.jobId());
  long parseId = positive(command.payload().get("parseRecordId"));
  Map<String, Object> parse = repository.parse(parseId);
  long executionId = positive(command.payload().get("executionId"));
  Map<String, Object> execution = executions.find(executionId);
  validate(command, job, parse, execution);
  if (!current(job, executionId) || "CANCELLED".equals(job.get("status"))) return;
  int version =
      Math.toIntExact(
          positive(command.payload().get(kind.equals("POST") ? "postVersion" : "reportVersion")));
  if (version > 10000) throw new IllegalArgumentException("Stage version out of range");
  var existing = repository.find(parseId, kind, version, false);
  if (existing.isPresent() && "COMPLETE".equals(existing.get().get("status"))) return;
  Map<String, Object> candidate = null;
  try {
    if (existing.isEmpty())
      candidate =
          kind.equals("POST")
              ? builder.post(job, execution, parse, version, null)
              : builder.report(
                  repository
                      .find(
                          parseId,
                          "POST",
                          Math.toIntExact(positive(command.payload().get("postVersion"))),
                          false)
                      .orElseThrow(StageBusyException::new),
                  version);
  } catch (DataAccessException unavailable) {
    throw unavailable;
  } catch (StageBusyException busy) {
    throw busy;
  } catch (RuntimeException failure) {
    preparationFailed(job, parse, kind, version, failure);
    throw failure;
  }
  Map<String, Object> prepared = candidate;
  Map<String, Object> claim =
      tx.execute(
          status -> {
            var locked = jobs.lockById(command.jobId());
            var confirmed = executions.locked(executionId);
            if (!current(locked, executionId)
                || !"SUCCESS".equals(confirmed.get("status"))
                || "CANCELLED".equals(locked.get("status"))) return Map.of();
            if (locked.get("activePipelineParseId") == null)
              locked = binding.completed(locked, parse);
            var prior = repository.find(parseId, kind, version, true);
            var stage =
                prior.isPresent()
                    ? prior.get()
                    : repository.create(
                        locked,
                        parse,
                        kind,
                        version,
                        Math.toIntExact(positive(command.payload().get("postVersion"))),
                        prepared);
            if ("COMPLETE".equals(stage.get("status"))) return Map.of();
            if ("RUNNING".equals(stage.get("status"))
                && stage.get("claimUntil") != null
                && Instant.parse(stage.get("claimUntil").toString()).isAfter(Instant.now()))
              throw new StageBusyException();
            if (binding.active(locked, stage)) {
              String failed = kind.equals("POST") ? "POST_PROCESS_FAILED" : "REPORT_FAILED";
              if (failed.equals(locked.get("status")))
                jobs.transition(
                    clear(locked),
                    kind.equals("POST") ? JobStatus.POST_PROCESSING : JobStatus.REPORTING,
                    "STAGE_AUTOMATIC_RETRY",
                    Map.of("stageId", SqlRows.id(stage)));
            }
            return repository.claim(stage);
          });
  if (claim.isEmpty()) return;
  long started = System.nanoTime();
  try {
    var response =
        client.render(
            execution.get("nodeId").toString(), kind, json.readMap(claim.get("request")));
    var checked = verifier.verify(claim, response);
    tx.executeWithoutResult(
        status -> {
          var locked = jobs.lockById(command.jobId());
          executions.locked(executionId);
          var stage = repository.find(parseId, kind, version, true).orElseThrow();
          if (!repository.owns(stage, claim)) throw new StageBusyException();
          if (!current(locked, executionId)) {
            repository.fail(stage, "Obsolete execution; stage cannot modify the current Job");
            return;
          }
          long manifestId = 0, reportArtifact = 0;
          for (var item : checked) {
            var metadata = new LinkedHashMap<>(item.metadata());
            metadata.put("parseRecordId", parseId);
            metadata.put("executionId", executionId);
            metadata.put("parserVersion", parse.get("parserVersion"));
            metadata.put("rawChecksum", parse.get("rawChecksum"));
            var artifact =
                artifacts.register(
                    command.jobId(),
                    executionId,
                    parseId,
                    parse.get("parserVersion").toString(),
                    version,
                    item.type(),
                    item.file(),
                    item.contentType(),
                    metadata);
            if (item.type().endsWith("MANIFEST")) manifestId = SqlRows.id(artifact);
            if (item.type().equals("REPORT_PPTX")) reportArtifact = SqlRows.id(artifact);
          }
          repository.complete(stage, manifestId);
          if (kind.equals("POST")) {
            if (stage.get("nextRequestedAt") == null) {
              jobs.recordEvent(
                  command.jobId(),
                  "REPORT_REQUESTED",
                  stageCommand(
                      parse, execution, ((Number) stage.get("postVersion")).intValue(), version));
              repository.next(SqlRows.id(stage));
            }
            if (binding.active(locked, stage) && "POST_PROCESSING".equals(locked.get("status")))
              jobs.transition(
                  clear(locked),
                  JobStatus.REPORTING,
                  "POST_PROCESS_COMPLETED",
                  Map.of("stageId", SqlRows.id(stage), "parseRecordId", parseId));
          } else {
            repository.report(stage, reportArtifact);
            if (binding.active(locked, stage) && "REPORTING".equals(locked.get("status"))) {
              var fields = new LinkedHashMap<String, Object>();
              fields.put("finishedAt", java.sql.Timestamp.from(Instant.now()));
              locked = jobs.patch(clear(locked), fields);
              jobs.transition(
                  locked,
                  JobStatus.SUCCESS,
                  "DRAFT_REPORT_COMPLETED",
                  Map.of(
                      "stageId",
                      SqlRows.id(stage),
                      "artifactId",
                      reportArtifact,
                      "reportStatus",
                      "DRAFT"));
            }
          }
          jobs.recordEvent(
              command.jobId(),
              kind.equals("POST") ? "POST_ARTIFACTS_REGISTERED" : "REPORT_ARTIFACTS_REGISTERED",
              Map.of("stageId", SqlRows.id(stage), "parseRecordId", parseId, "version", version));
        });
    metrics.counter("cae.stage.completed", "stage", kind).increment();
  } catch (StageBusyException busy) {
    throw busy;
  } catch (DataIntegrityViolationException constraint) {
    failed(command, claim, kind, constraint);
    throw new IllegalArgumentException("Stage violates a durable storage constraint", constraint);
  } catch (DataAccessException unavailable) {
    throw unavailable;
  } catch (RuntimeException failure) {
    failed(command, claim, kind, failure);
    throw failure;
  } finally {
    metrics
        .timer("cae.stage.duration", "stage", kind)
        .record(System.nanoTime() - started, java.util.concurrent.TimeUnit.NANOSECONDS);
  }
}

private void failed(
    CommandEnvelope command, Map<String, Object> claim, String kind, RuntimeException failure) {
  tx.executeWithoutResult(
      status -> {
        var job = jobs.lockById(command.jobId());
        executions.locked(((Number) claim.get("executionId")).longValue());
        var stage =
            repository
                .find(
                    ((Number) claim.get("parseRecordId")).longValue(),
                    kind,
                    ((Number) claim.get("stageVersion")).intValue(),
                    true)
                .orElseThrow();
        if (!repository.owns(stage, claim)) return;
        repository.fail(stage, reason(failure));
        failMain(job, stage, kind, failure);
      });
  metrics.counter("cae.stage.failed", "stage", kind).increment();
}

private void preparationFailed(
    Map<String, Object> job,
    Map<String, Object> parse,
    String kind,
    int version,
    RuntimeException failure) {
  tx.executeWithoutResult(
      status -> {
        var locked = jobs.lockById(SqlRows.id(job));
        executions.locked(((Number) parse.get("executionId")).longValue());
        var stage = new LinkedHashMap<String, Object>();
        stage.put("parseRecordId", SqlRows.id(parse));
        stage.put("kind", kind);
        stage.put("stageVersion", version);
        stage.put("pipelineGeneration", job.get("pipelineGeneration"));
        failMain(locked, stage, kind, failure);
      });
}

private void failMain(
    Map<String, Object> job, Map<String, Object> stage, String kind, RuntimeException failure) {
  if (!binding.active(job, stage)
      || !current(
          job,
          ((Number)
                  repository
                      .parse(((Number) stage.get("parseRecordId")).longValue())
                      .get("executionId"))
              .longValue())) return;
  String expected = kind.equals("POST") ? "POST_PROCESSING" : "REPORTING";
  if (!expected.equals(job.get("status"))) return;
  job =
      jobs.patch(
          job,
          Map.of(
              "failureCode",
              kind.equals("POST") ? "POST_PROCESS_FAILED" : "REPORT_GENERATION_FAILED",
              "failureMessage",
              reason(failure)));
  jobs.transition(
      job,
      kind.equals("POST") ? JobStatus.POST_PROCESS_FAILED : JobStatus.REPORT_FAILED,
      "STAGE_FAILED",
      Map.of("kind", kind, "parseRecordId", stage.get("parseRecordId")));
}

public Map<String, Object> retryLocked(Map<String, Object> job, String actor) {
  long jobId = SqlRows.id(job);
  long executionId = ((Number) job.get("currentExecutionId")).longValue();
  var execution = executions.locked(executionId);
  if (!"SUCCESS".equals(execution.get("status")))
    throw ApiException.conflict("Stage retry requires the original successful Solver");
  String kind = job.get("status").equals("REPORT_FAILED") ? "REPORT" : "POST";
  Object activeParseId = job.get("activePipelineParseId");
  var selected =
      results.history(jobId).stream()
          .filter(row -> Objects.equals(row.get("id"), activeParseId))
          .findFirst();
  if (selected.isEmpty() || !"COMPLETE".equals(selected.get().get("status"))) {
    var failed =
        results.history(jobId).stream()
            .filter(row -> "FAILED".equals(row.get("status")))
            .reduce((a, b) -> b)
            .orElseThrow(() -> ApiException.conflict("No failed parser stage to retry"));
    job =
        jobs.transition(
            clear(job),
            JobStatus.POST_PROCESSING,
            "PARSER_RETRY_REQUESTED",
            Map.of("parserVersion", failed.get("parserVersion")));
    jobs.recordEvent(
        jobId,
        "RESULT_PARSE_REQUESTED",
        Map.of(
            "executionId",
            executionId,
            "executionRequestId",
            execution.get("submitRequestId"),
            "parserVersion",
            failed.get("parserVersion")));
    return job;
  }
  var parse = selected.get();
  int version =
      ((Number) job.get(kind.equals("POST") ? "activePostVersion" : "activeReportVersion"))
          .intValue();
  var stage = repository.find(SqlRows.id(parse), kind, version, true);
  var fields = new LinkedHashMap<String, Object>();
  fields.put("pipelineGeneration", ((Number) job.get("pipelineGeneration")).longValue() + 1);
  job = jobs.patch(clear(job), fields);
  if (stage.isPresent())
    repository.reset(stage.get(), ((Number) job.get("pipelineGeneration")).longValue());
  job =
      jobs.transition(
          job,
          kind.equals("POST") ? JobStatus.POST_PROCESSING : JobStatus.REPORTING,
          "STAGE_RETRY_REQUESTED",
          Map.of("kind", kind, "actor", actor));
  jobs.recordEvent(
      jobId,
      kind.equals("POST") ? "POST_PROCESS_REQUESTED" : "REPORT_REQUESTED",
      stageCommand(
          parse, execution, ((Number) job.get("activePostVersion")).intValue(), version));
  return job;
}

public Map<String, Object> stageCommand(
    Map<String, Object> parse,
    Map<String, Object> execution,
    int postVersion,
    int reportVersion) {
  var command = new LinkedHashMap<String, Object>();
  command.put("jobNo", jobs.findById(((Number) parse.get("jobId")).longValue()).get("jobNo"));
  command.put("executionId", SqlRows.id(execution));
  command.put("executionRequestId", execution.get("submitRequestId"));
  command.put("parseRecordId", SqlRows.id(parse));
  command.put("parserVersion", parse.get("parserVersion"));
  command.put("rawChecksum", parse.get("rawChecksum"));
  command.put("conditionCode", parse.get("conditionCode"));
  command.put("subcase", parse.get("subcase"));
  command.put("postVersion", postVersion);
  command.put("reportVersion", reportVersion);
  return command;
}

private void validate(
    CommandEnvelope command,
    Map<String, Object> job,
    Map<String, Object> parse,
    Map<String, Object> execution) {
  if (!command.jobNo().equals(job.get("jobNo"))
      || ((Number) parse.get("jobId")).longValue() != command.jobId()
      || ((Number) execution.get("jobId")).longValue() != command.jobId()
      || !parse.get("executionId").equals(execution.get("id"))
      || !"COMPLETE".equals(parse.get("status"))
      || !"SUCCESS".equals(execution.get("status"))
      || !execution.get("submitRequestId").equals(command.payload().get("executionRequestId")))
    throw new IllegalArgumentException("Stage command source identity mismatch");
  for (String key : List.of("parserVersion", "rawChecksum", "conditionCode", "subcase"))
    if (!Objects.equals(parse.get(key), command.payload().get(key))
        && !(parse.get(key) instanceof Number
            && command.payload().get(key) instanceof Number
            && parse.get(key).toString().equals(command.payload().get(key).toString())))
      throw new IllegalArgumentException("Stage command parse metadata mismatch: " + key);
}

private Map<String, Object> clear(Map<String, Object> job) {
  var fields = new LinkedHashMap<String, Object>();
  fields.put("failureCode", null);
  fields.put("failureMessage", null);
  return jobs.patch(job, fields);
}

private static boolean current(Map<String, Object> job, long executionId) {
  return job.get("currentExecutionId") instanceof Number id && id.longValue() == executionId;
}

public static long positive(Object value) {
  if (!(value instanceof Number n)
      || !Double.isFinite(n.doubleValue())
      || n.longValue() < 1
      || n.doubleValue() != n.longValue())
    throw new IllegalArgumentException("Expected a positive integral stage identity");
  return n.longValue();
}

private static String reason(RuntimeException failure) {
  String message = failure.getClass().getSimpleName() + ": " + failure.getMessage();
  return message.substring(0, Math.min(1000, message.length()));
}

public StageBusyException() {
  super("The original stage is still being processed");
}

package com.example.cae.report;

import com.example.cae.agent.ComputeAgentClient;
import com.example.cae.common.JsonCodec;
import java.io.IOException;
import java.net.http.HttpClient;
import java.net.http.HttpRequest;
import java.net.http.HttpResponse;
import java.time.Duration;
import java.util.Map;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.stereotype.Component;

/** Rendering has its own timeout and never sends credentials to an unconfigured origin. */
@Component
public class RenderClient {
  private final ComputeAgentClient agents;
  private final JsonCodec json;
  private final String token;
  private final HttpClient client =
      HttpClient.newBuilder()
          .connectTimeout(Duration.ofSeconds(2))
          .followRedirects(HttpClient.Redirect.NEVER)
          .build();

public RenderClient(
    ComputeAgentClient agents,
    JsonCodec json,
    @Value("${SERVICE_TOKEN:demo-service-token}") String token) {
  this.agents = agents;
  this.json = json;
  this.token = token;
}

  public Map<String, Object> render(String node, String kind, Map<String, Object> payload) {
    var origin = agents.nodes().get(node);
    if (origin == null) throw new IllegalArgumentException("Render node is not configured");
    var request =
        HttpRequest.newBuilder(
                origin.resolve(
                    kind.equals("POST")
                        ? "/worker/v1/post/process"
                        : "/worker/v1/reports/generate"))
            .timeout(Duration.ofSeconds(30))
            .header("X-Service-Token", token)
            .header("Content-Type", "application/json")
            .POST(HttpRequest.BodyPublishers.ofString(json.write(payload)))
            .build();
    try {
      var response = client.send(request, HttpResponse.BodyHandlers.ofString());
      if (response.statusCode() != 200)
        throw new IllegalArgumentException("Renderer returned HTTP " + response.statusCode());
      if (response.body().length() > 2 * 1024 * 1024)
        throw new IllegalArgumentException("Render response is too large");
      return json.readMap(response.body());
    } catch (InterruptedException interrupted) {
      Thread.currentThread().interrupt();
      throw new IllegalStateException("Rendering interrupted", interrupted);
    } catch (IOException unavailable) {
      throw new IllegalArgumentException(
          "Render response unavailable; the same frozen stage can be replayed", unavailable);
    }
  }
}

package com.example.cae.report;

import com.example.cae.artifact.ArtifactFileStore;
import com.example.cae.common.JsonCodec;
import java.nio.charset.StandardCharsets;
import java.util.List;
import java.util.Map;
import java.util.TreeMap;
import org.springframework.stereotype.Component;

@Component
public class RenderFingerprint {
  private final JsonCodec json;

public RenderFingerprint(JsonCodec json) {
  this.json = json;
}

public String of(Map<String, Object> payload) {
  return ArtifactFileStore.hex(json.write(sorted(payload)).getBytes(StandardCharsets.UTF_8));
}

private Object sorted(Object value) {
  if (value instanceof Map<?, ?> map) {
    Map<String, Object> sorted = new TreeMap<>();
    map.forEach((key, item) -> sorted.put(key.toString(), sorted(item)));
    return sorted;
  }
  if (value instanceof List<?> list) return list.stream().map(this::sorted).toList();
  return value;
}

package com.example.cae.report;

import com.example.cae.auth.ProjectAccess;
import com.example.cae.common.ApiException;
import com.example.cae.common.SqlRows;
import com.example.cae.job.domain.JobStatus;
import com.example.cae.job.execution.ExecutionRepository;
import com.example.cae.job.repository.JobRepository;
import com.example.cae.result.ResultRepository;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;

@Service
public class ReportApplicationService {
  private final JobRepository jobs;
  private final ExecutionRepository executions;
  private final ProjectAccess access;
  private final ResultRepository results;
  private final PipelineRepository repository;
  private final PipelineRequestBuilder builder;
  private final PipelineService pipeline;
  private final RenderFingerprint fingerprints;
  private final TransactionTemplate tx;
  private final BaselineComparisonService comparisons;

  public ReportApplicationService(
      JobRepository jobs,
      ExecutionRepository executions,
      ProjectAccess access,
      ResultRepository results,
      PipelineRepository repository,
      PipelineRequestBuilder builder,
      PipelineService pipeline,
      RenderFingerprint fingerprints,
      TransactionTemplate tx,
      BaselineComparisonService comparisons) {
    this.jobs = jobs;
    this.executions = executions;
    this.access = access;
    this.results = results;
    this.repository = repository;
    this.builder = builder;
    this.pipeline = pipeline;
    this.fingerprints = fingerprints;
    this.tx = tx;
    this.comparisons = comparisons;
  }

  public List<Map<String, Object>> baselines(
      Authentication user, String jobNo, String parserVersion) {
    var job = jobs.findByNo(jobNo);
    access.requireJob(user, job);
    var parse =
        results
            .find(SqlRows.id(job), parserVersion)
            .orElseThrow(() -> com.example.cae.common.ApiException.notFound("Parser version"));
    return repository.baselines(job, parse);
  }

  public Map<String, Object> comparison(
      Authentication user, String jobNo, String parserVersion, String baselineJobNo) {
    var job = jobs.findByNo(jobNo);
    access.requireJob(user, job);
    if (baselineJobNo != null) access.requireJob(user, jobs.findByNo(baselineJobNo));
    var parse =
        results
            .find(SqlRows.id(job), parserVersion)
            .orElseThrow(() -> com.example.cae.common.ApiException.notFound("Parser version"));
    var base = repository.baseline(job, parse, baselineJobNo);
    if (baselineJobNo != null && base.isEmpty())
      throw com.example.cae.common.ApiException.invalid("Baseline is incompatible");
    var response = new java.util.LinkedHashMap<String, Object>();
    response.put(
        "baseline",
        base.isEmpty()
            ? null
            : Map.of("jobNo", base.get().get("jobNo"), "parseRecordId", SqlRows.id(base.get())));
    response.put(
        "comparisons",
        comparisons.compare(
            repository.metrics(SqlRows.id(parse)),
            base.isEmpty() ? List.of() : repository.metrics(SqlRows.id(base.get()))));
    return response;
  }

  public List<Map<String, Object>> reports(Authentication user, Long project, String jobNo) {
    Long jobId = null;
    if (jobNo != null) {
      var job = jobs.findByNo(jobNo);
      access.requireJob(user, job);
      jobId = SqlRows.id(job);
    }
    if (project != null) access.require(user, project);
    return repository.reports(jobId, project, user.getName(), access.admin(user));
  }

  public Map<String, Object> detail(Authentication user, long id) {
    var report = repository.report(id, false);
    access.require(user, ((Number) report.get("projectId")).longValue());
    return report;
  }

  public List<Map<String, Object>> stages(Authentication user, String jobNo) {
    var job = jobs.findByNo(jobNo);
    access.requireJob(user, job);
    return repository.stages(SqlRows.id(job));
  }

  public Map<String, Object> generate(
      Authentication user, String jobNo, String version, String baseline, String key) {
    var job = jobs.findByNo(jobNo);
    access.requireJob(user, job);
    if (baseline != null) {
      access.requireLead(user, ((Number) job.get("projectId")).longValue());
      access.requireJob(user, jobs.findByNo(baseline));
    }
    var parse =
        results
            .find(SqlRows.id(job), version)
            .orElseThrow(() -> ApiException.notFound("Parser version"));
    if (!"COMPLETE".equals(parse.get("status"))
        || !java.util.Objects.equals(job.get("currentExecutionId"), parse.get("executionId")))
      throw ApiException.conflict("A complete current parser version is required");
    var execution = executions.find(((Number) parse.get("executionId")).longValue());
    var intent = new LinkedHashMap<String, Object>();
    intent.put("parserVersion", version);
    intent.put("baselineJobNo", baseline);
    String fingerprint = fingerprints.of(intent);
    var old = repository.intent(SqlRows.id(job), key);
    if (old.isPresent()) return replay(old.get(), fingerprint);
    if (!Set.of("SUCCESS", "POST_PROCESS_FAILED", "REPORT_FAILED").contains(job.get("status")))
      throw ApiException.conflict("Wait for the current report pipeline to finish or fail");
    var prepared = builder.post(job, execution, parse, 1, baseline);
    return tx.execute(
        status -> {
          var locked = jobs.lockById(SqlRows.id(job));
          executions.locked(SqlRows.id(execution));
          var existing = repository.intent(SqlRows.id(job), key);
          if (existing.isPresent()) return replay(existing.get(), fingerprint);
          if (!java.util.Objects.equals(locked.get("currentExecutionId"), execution.get("id"))
              || !Set.of("SUCCESS", "POST_PROCESS_FAILED", "REPORT_FAILED")
                  .contains(locked.get("status")))
            throw ApiException.conflict("Job changed before report generation was requested");
          int next = repository.nextVersion(SqlRows.id(parse));
          prepared.put("postVersion", next);
          if (!"SUCCESS".equals(locked.get("status"))) {
            Map<String, Object> fields = new LinkedHashMap<>();
            fields.put("activePipelineParseId", SqlRows.id(parse));
            fields.put("activePostVersion", next);
            fields.put("activeReportVersion", next);
            fields.put(
                "pipelineGeneration", ((Number) locked.get("pipelineGeneration")).longValue() + 1);
            fields.put("failureCode", null);
            fields.put("failureMessage", null);
            locked = jobs.patch(locked, fields);
            locked =
                jobs.transition(
                    locked,
                    JobStatus.POST_PROCESSING,
                    "REPORT_PIPELINE_ACTIVATED",
                    Map.of("parseRecordId", SqlRows.id(parse), "version", next));
          }
          var stage = repository.create(locked, parse, "POST", next, next, prepared);
          repository.intent(SqlRows.id(job), key, fingerprint, SqlRows.id(parse), next);
          jobs.recordEvent(
              SqlRows.id(job),
              "POST_PROCESS_REQUESTED",
              pipeline.stageCommand(parse, execution, next, next));
          jobs.audit(
              user.getName(),
              "REPORT_GENERATE",
              "JOB",
              jobNo,
              null,
              Map.of("parseRecordId", SqlRows.id(parse), "version", next, "idempotencyKey", key));
          return stage;
        });
  }

  private Map<String, Object> replay(Map<String, Object> intent, String fingerprint) {
    if (!fingerprint.equals(intent.get("requestFingerprint")))
      throw ApiException.conflict("Report generation idempotency key belongs to different inputs");
    return repository
        .find(
            ((Number) intent.get("parseRecordId")).longValue(),
            "POST",
            ((Number) intent.get("stageVersion")).intValue(),
            false)
        .orElseThrow();
  }

  public Map<String, Object> review(Authentication user, long id, boolean approve) {
    var before = repository.report(id, false);
    long project = ((Number) before.get("projectId")).longValue();
    access.requireLead(user, project);
    if (approve && !access.admin(user)) throw ApiException.forbidden();
    return tx.execute(
        status -> {
          jobs.lockById(((Number) before.get("jobId")).longValue());
          var report = repository.report(id, true);
          String current = report.get("reportStatus").toString();
          if (approve && current.equals("DRAFT"))
            throw ApiException.conflict("Review the draft before approval");
          if ((approve && current.equals("APPROVED")) || (!approve && !current.equals("DRAFT")))
            return report;
          repository.review(id, user.getName(), approve);
          var updated = repository.report(id, false);
          jobs.audit(
              user.getName(),
              approve ? "REPORT_APPROVE" : "REPORT_REVIEW",
              "REPORT",
              Long.toString(id),
              Map.of("reportStatus", current),
              Map.of("reportStatus", updated.get("reportStatus")));
          return updated;
        });
  }
}

