    @Pattern(regexp = "v[12]") String parserVersion,
    @Pattern(regexp = "CAE-[0-9]{8}-[0-9]{6,}") String baselineJobNo,
    @Pattern(regexp = "[A-Za-z0-9_-]{1,100}") String idempotencyKey) {}

