package com.example.cae.resource;

import com.example.cae.auth.ProjectAccess;
import com.example.cae.common.ApiException;
import com.example.cae.common.JsonCodec;
import com.example.cae.common.SqlRows;
import com.example.cae.job.domain.AnalysisType;
import com.example.cae.job.repository.JobRepository;
import jakarta.validation.constraints.Max;
import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/** Editable admission defaults; each Job retains the version and values selected at creation. */
@Service
public class ResourceProfileRegistry {

public record Definition(
    @Pattern(regexp = "[A-Z][A-Z0-9_]{1,31}") @NotNull String name,
    @Min(1) @Max(32) int cpu,
    @Min(1) @Max(64) int memoryGb,
    @Min(1) @Max(120) int walltimeMin,
    @Min(1) @Max(16) int licenseTokens,
    @NotEmpty List<@NotNull AnalysisType> allowedAnalysisTypes,
    boolean enabled,
    @Min(0) long version) {}

private final JdbcTemplate jdbc;
private final JsonCodec json;
private final ProjectAccess access;
private final JobRepository jobs;

public ResourceProfileRegistry(
    JdbcTemplate jdbc, JsonCodec json, ProjectAccess access, JobRepository jobs) {
  this.jdbc = jdbc;
  this.json = json;
  this.access = access;
  this.jobs = jobs;
}

public List<Map<String, Object>> list() {
  var rows = jdbc.query("SELECT * FROM cae_resource_profile ORDER BY name", SqlRows.MAPPER);
  rows.forEach(this::decode);
  return rows;
}

public Map<String, Object> find(String name) {
  var rows = jdbc.query("SELECT * FROM cae_resource_profile WHERE name=?", SqlRows.MAPPER, name);
  if (rows.isEmpty()) throw ApiException.notFound("Resource profile");
  return decode(rows.get(0));
}

public Snapshot select(String name, AnalysisType analysis, Map<String, Object> requested) {
  Map<String, Object> profile = find(name);
  if (!Boolean.TRUE.equals(profile.get("enabled"))
      && !(profile.get("enabled") instanceof Number n && n.intValue() != 0))
    throw ApiException.invalid("Resource profile is disabled");
  if (!((List<?>) profile.get("allowedAnalysisTypes")).contains(analysis.name()))
    throw ApiException.invalid("Resource profile does not support the requested analysis type");
  Map<String, Object> values =
      new java.util.LinkedHashMap<>(
          Map.of(
              "cpu",
              profile.get("cpu"),
              "memoryGb",
              profile.get("memoryGb"),
              "walltimeMin",
              profile.get("walltimeMin")));
  if (requested != null) {
    for (String key : requested.keySet())
      if (!values.containsKey(key))
        throw ApiException.invalid("Unsupported resource field: " + key);
    values.putAll(requested);
  }
  range(values, "cpu", 32);
  range(values, "memoryGb", 64);
  range(values, "walltimeMin", 120);
  return new Snapshot(
      name,
      ((Number) profile.get("version")).longValue(),
      ((Number) profile.get("licenseTokens")).intValue(),
      values);
}

@Transactional
public Map<String, Object> create(Authentication user, Definition value) {
  requireAdmin(user);
  jdbc.update(
      "INSERT INTO cae_resource_profile(name,cpu,memory_gb,walltime_min,license_tokens,allowed_analysis_types,enabled) VALUES(?,?,?,?,?,?,?)",
      value.name(),
      value.cpu(),
      value.memoryGb(),
      value.walltimeMin(),
      value.licenseTokens(),
      json.write(value.allowedAnalysisTypes()),
      value.enabled());
  Map<String, Object> result = find(value.name());
  audit(user, "RESOURCE_PROFILE_CREATE", value.name(), null, result);
  return result;
}

@Transactional
public Map<String, Object> update(Authentication user, String name, Definition value) {
  requireAdmin(user);
  if (!name.equals(value.name()))
    throw ApiException.invalid("Resource profile name is immutable");
  Map<String, Object> before = find(name);
  int count =
      jdbc.update(
          "UPDATE cae_resource_profile SET cpu=?,memory_gb=?,walltime_min=?,license_tokens=?,allowed_analysis_types=?,enabled=?,version=version+1,updated_at=CURRENT_TIMESTAMP(6) WHERE name=? AND version=?",
          value.cpu(),
          value.memoryGb(),
          value.walltimeMin(),
          value.licenseTokens(),
          json.write(value.allowedAnalysisTypes()),
          value.enabled(),
          name,
          value.version());
  if (count != 1)
    throw ApiException.conflict("Resource profile changed concurrently; refresh its version");
  Map<String, Object> result = find(name);
  audit(user, "RESOURCE_PROFILE_UPDATE", name, before, result);
  return result;
}

@Transactional
public void delete(Authentication user, String name, long version) {
  requireAdmin(user);
  Map<String, Object> before = find(name);
  if (jdbc.update("DELETE FROM cae_resource_profile WHERE name=? AND version=?", name, version)
      != 1)
    throw ApiException.conflict("Resource profile changed concurrently; refresh its version");
  audit(user, "RESOURCE_PROFILE_DELETE", name, before, null);
}

private Map<String, Object> decode(Map<String, Object> row) {
  row.put(
      "allowedAnalysisTypes",
      json.readMap("{\"items\":" + row.get("allowedAnalysisTypes") + "}").get("items"));
  return row;
}

private void requireAdmin(Authentication user) {
  if (!access.admin(user)) throw ApiException.forbidden();
}

private void audit(
    Authentication user, String operation, String name, Object before, Object after) {
  jobs.audit(user.getName(), operation, "RESOURCE_PROFILE", name, before, after);
}

private void range(Map<String, Object> values, String key, int max) {
  Object value = values.get(key);
  if (!(value instanceof Number n)
      || n.doubleValue() != n.intValue()
      || n.intValue() < 1
      || n.intValue() > max)
    throw ApiException.invalid("Resource " + key + " must be an integer between 1 and " + max);
}

package com.example.cae.resource;

import com.example.cae.common.ApiException;
import com.example.cae.common.SqlRows;
import java.sql.Statement;
import java.util.List;
import java.util.Map;
import java.util.Optional;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Propagation;
import org.springframework.transaction.annotation.Transactional;

/**
 * Durable mock license and resource accounting; all operations lock Job → license → node →
 * reservation.
 */
@Service
public class ResourceReservationService {

public ResourceReservationService(
    JdbcTemplate jdbc, @Value("${cae.nodes.suspect-seconds:10}") long freshHeartbeatSeconds) {
  this.jdbc = jdbc;
  this.freshHeartbeatSeconds = freshHeartbeatSeconds;
}

@Transactional(propagation = Propagation.MANDATORY)
public Optional<Reservation> reserve(
    long jobId, String nodeId, int cpu, int memoryGb, String feature, int tokens) {
  if (cpu < 1 || memoryGb < 1 || tokens < 1)
    throw ApiException.invalid("Reservation requests must be positive");
  Map<String, Object> job = lockJob(jobId);
  List<Map<String, Object>> active =
      jdbc.query(
          "SELECT * FROM cae_resource_reservation WHERE job_id=? AND status IN ('RESERVED','IN_USE')",
          SqlRows.MAPPER,
          jobId);
  if (!active.isEmpty()) {
    Reservation prior = reservation(active.get(0));
    if (!prior.nodeId().equals(nodeId)
        || prior.cpu() != cpu
        || prior.memoryGb() != memoryGb
        || !prior.feature().equals(feature)
        || prior.tokens() != tokens)
      throw ApiException.conflict(
          "Job already has an active reservation with a different request");
    return Optional.of(prior);
  }
  int licensed =
      jdbc.update(
          "UPDATE cae_license_pool SET reserved_tokens=reserved_tokens+? WHERE feature=? AND reserved_tokens+in_use_tokens+?<=total_tokens",
          tokens,
          feature,
          tokens);
  if (licensed == 0) return Optional.empty();
  int reserved =
      jdbc.update(
          "UPDATE cae_compute_node SET cpu_reserved=cpu_reserved+?,memory_reserved_gb=memory_reserved_gb+? WHERE node_id=? AND status='ONLINE' AND drained=FALSE AND workspace_reachable=TRUE AND last_heartbeat>=TIMESTAMPADD(SECOND,?,CURRENT_TIMESTAMP(6)) AND JSON_CONTAINS(solver_tags,JSON_QUOTE(?)) AND GREATEST(cpu_used,observed_cpu_used)+cpu_reserved+?<=cpu_total AND GREATEST(memory_used_gb,observed_memory_used_gb)+memory_reserved_gb+?<=memory_total_gb",
          cpu,
          memoryGb,
          nodeId,
          -freshHeartbeatSeconds,
          job.get("analysisType"),
          cpu,
          memoryGb);
  if (reserved == 0) {
    checked(
        jdbc.update(
            "UPDATE cae_license_pool SET reserved_tokens=reserved_tokens-? WHERE feature=? AND reserved_tokens>=?",
            tokens,
            feature,
            tokens));
    return Optional.empty();
  }
  GeneratedKeyHolder keys = new GeneratedKeyHolder();
  jdbc.update(
      connection -> {
        var statement =
            connection.prepareStatement(
                "INSERT INTO cae_resource_reservation(job_id,node_id,feature,token_count,cpu,memory_gb,status) VALUES(?,?,?,?,?,?,'RESERVED')",
                Statement.RETURN_GENERATED_KEYS);
        statement.setLong(1, jobId);
        statement.setString(2, nodeId);
        statement.setString(3, feature);
        statement.setInt(4, tokens);
        statement.setInt(5, cpu);
        statement.setInt(6, memoryGb);
        return statement;
      },
      keys);
  return Optional.of(
      new Reservation(keys.getKey().longValue(), jobId, nodeId, cpu, memoryGb, feature, tokens));
}

@Transactional(propagation = Propagation.MANDATORY)
public void associateExecution(long reservationId, long executionId) {
  int updated =
      jdbc.update(
          "UPDATE cae_resource_reservation r JOIN cae_job_execution e ON e.id=? AND e.job_id=r.job_id AND e.node_id=r.node_id AND e.reservation_id=r.id SET r.execution_id=? WHERE r.id=? AND r.status='RESERVED' AND r.execution_id IS NULL",
          executionId,
          executionId,
          reservationId);
  if (updated == 0) {
    Long existing =
        jdbc.queryForObject(
            "SELECT execution_id FROM cae_resource_reservation WHERE id=?",
            Long.class,
            reservationId);
    if (existing == null || existing.longValue() != executionId)
      throw ApiException.conflict("Reservation cannot be associated with this execution");
  }
}

@Transactional
public boolean accepted(long reservationId) {
  Map<String, Object> row = lockLedger(reservationId);
  String status = row.get("status").toString();
  if (status.equals("IN_USE") || status.equals("RELEASED")) return false;
  if (!status.equals("RESERVED")) throw new IllegalStateException("Unknown reservation status");
  int tokens = integer(row, "tokenCount"),
      cpu = integer(row, "cpu"),
      memory = integer(row, "memoryGb");
  String feature = row.get("feature").toString(), node = row.get("nodeId").toString();
  checked(
      jdbc.update(
          "UPDATE cae_license_pool SET reserved_tokens=reserved_tokens-?,in_use_tokens=in_use_tokens+? WHERE feature=? AND reserved_tokens>=?",
          tokens,
          tokens,
          feature,
          tokens));
  checked(
      jdbc.update(
          "UPDATE cae_compute_node SET cpu_reserved=cpu_reserved-?,memory_reserved_gb=memory_reserved_gb-?,cpu_used=cpu_used+?,memory_used_gb=memory_used_gb+? WHERE node_id=? AND cpu_reserved>=? AND memory_reserved_gb>=?",
          cpu,
          memory,
          cpu,
          memory,
          node,
          cpu,
          memory));
  checked(
      jdbc.update(
          "UPDATE cae_resource_reservation SET status='IN_USE',accepted_at=CURRENT_TIMESTAMP(6) WHERE id=? AND status='RESERVED'",
          reservationId));
  return true;
}

@Transactional
public boolean release(long reservationId) {
  Map<String, Object> row = lockLedger(reservationId);
  String status = row.get("status").toString();
  if (status.equals("RELEASED")) return false;
  boolean reserved = status.equals("RESERVED");
  if (!reserved && !status.equals("IN_USE"))
    throw new IllegalStateException("Unknown reservation status");
  int tokens = integer(row, "tokenCount"),
      cpu = integer(row, "cpu"),
      memory = integer(row, "memoryGb");
  String feature = row.get("feature").toString(), node = row.get("nodeId").toString();
  String tokenColumn = reserved ? "reserved_tokens" : "in_use_tokens";
  checked(
      jdbc.update(
          "UPDATE cae_license_pool SET "
              + tokenColumn
              + "="
              + tokenColumn
              + "-? WHERE feature=? AND "
              + tokenColumn
              + ">=?",
          tokens,
          feature,
          tokens));
  String cpuColumn = reserved ? "cpu_reserved" : "cpu_used",
      memoryColumn = reserved ? "memory_reserved_gb" : "memory_used_gb";
  checked(
      jdbc.update(
          "UPDATE cae_compute_node SET "
              + cpuColumn
              + "="
              + cpuColumn
              + "-?,"
              + memoryColumn
              + "="
              + memoryColumn
              + "-? WHERE node_id=? AND "
              + cpuColumn
              + ">=? AND "
              + memoryColumn
              + ">=?",
          cpu,
          memory,
          node,
          cpu,
          memory));
  checked(
      jdbc.update(
          "UPDATE cae_resource_reservation SET status='RELEASED',released_at=CURRENT_TIMESTAMP(6) WHERE id=? AND status=?",
          reservationId,
          status));
  return true;
}

@Transactional
public boolean releaseByExecution(long executionId) {
  List<Long> ids =
      jdbc.queryForList(
          "SELECT id FROM cae_resource_reservation WHERE execution_id=?",
          Long.class,
          executionId);
  return !ids.isEmpty() && release(ids.get(0));
}

public List<Map<String, Object>> licenses() {
  return jdbc.query("SELECT * FROM cae_license_pool ORDER BY feature", SqlRows.MAPPER);
}

private Map<String, Object> lockJob(long jobId) {
  List<Map<String, Object>> rows =
      jdbc.query("SELECT * FROM cae_job WHERE id=? FOR UPDATE", SqlRows.MAPPER, jobId);
  if (rows.isEmpty()) throw ApiException.notFound("Job");
  return rows.get(0);
}

private Map<String, Object> lockLedger(long id) {
  List<Map<String, Object>> rows =
      jdbc.query("SELECT * FROM cae_resource_reservation WHERE id=?", SqlRows.MAPPER, id);
  if (rows.isEmpty()) throw ApiException.notFound("Reservation");
  Map<String, Object> immutable = rows.get(0);
  lockJob(((Number) immutable.get("jobId")).longValue());
  jdbc.queryForObject(
      "SELECT total_tokens FROM cae_license_pool WHERE feature=? FOR UPDATE",
      Integer.class,
      immutable.get("feature"));
  jdbc.queryForObject(
      "SELECT cpu_total FROM cae_compute_node WHERE node_id=? FOR UPDATE",
      Integer.class,
      immutable.get("nodeId"));
  return jdbc.queryForObject(
      "SELECT * FROM cae_resource_reservation WHERE id=? FOR UPDATE", SqlRows.MAPPER, id);
}

private Reservation reservation(Map<String, Object> row) {
  return new Reservation(
      ((Number) row.get("id")).longValue(),
      ((Number) row.get("jobId")).longValue(),
      row.get("nodeId").toString(),
      integer(row, "cpu"),
      integer(row, "memoryGb"),
      row.get("feature").toString(),
      integer(row, "tokenCount"));
}

private int integer(Map<String, Object> value, String field) {
  return ((Number) value.get(field)).intValue();
}

private void checked(int rows) {
  if (rows != 1)
    throw new IllegalStateException(
        "Resource ledger invariants were violated; transaction is rolled back");
}

package com.example.cae.result;

import com.example.cae.job.domain.AnalysisType;
import java.math.BigDecimal;
import java.util.Map;

abstract class AbstractResultParser implements ResultParser {
  private final String version;
  private final AnalysisType analysis;
  private final String solver;

AbstractResultParser(String version, AnalysisType analysis, String solver) {
  if (!version.equals("v1") && !version.equals("v2"))
    throw new IllegalArgumentException("Unsupported parser version");
  this.version = version;
  this.analysis = analysis;
  this.solver = solver;
}

@Override
public String version() {
  return version;
}

@Override
public boolean supports(AnalysisType analysisType, String solverType) {
  return analysis == analysisType && solver.equals(solverType);
}

protected void validate(ParseContext context) {
  Map<String, Object> raw = context.raw();
  if (!supports(
          AnalysisType.valueOf(context.job().get("analysisType").toString()),
          context.job().get("solverType").toString())
      || !analysis.name().equals(raw.get("analysisType"))
      || !context.job().get("conditionCode").equals(raw.get("conditionCode"))
      || !context.job().get("solverProfile").equals(raw.get("solverProfile"))
      || integer(raw.get("schemaVersion"), "schemaVersion") != 1
      || integer(raw.get("subcase"), "subcase") != context.subcase())
    throw new IllegalArgumentException(
        "Raw result analysis, condition, subcase or schema mismatch");
}

static int integer(Object value, String name) {
  if (!(value instanceof Number number)
      || !Double.isFinite(number.doubleValue())
      || number.doubleValue() != number.longValue()
      || number.longValue() < Integer.MIN_VALUE
      || number.longValue() > Integer.MAX_VALUE)
    throw new IllegalArgumentException("Expected integral " + name);
  return number.intValue();
}

  protected CanonicalMetric metric(
      ParseContext context,
      String code,
      String name,
      Object raw,
      String unit,
      String dimension,
      boolean positive) {
    if (!(raw instanceof Number number) || !Double.isFinite(number.doubleValue()))
      throw new IllegalArgumentException("Missing or non-finite numeric metric " + code);
    BigDecimal value = new BigDecimal(number.toString()).stripTrailingZeros();
    if (positive && value.signum() <= 0)
      throw new IllegalArgumentException("Expected positive engineering metric " + code);
    return new CanonicalMetric(
        code,
        name,
        value,
        null,
        unit,
        dimension,
        "VALID",
        context.job().get("conditionCode").toString(),
        context.subcase());
  }
}

/** A typed value with its engineering condition; a boolean is never converted to a number. */
public record CanonicalMetric(
    String metricCode,
    String metricName,
    BigDecimal valueNum,
    String valueText,
    String unit,
    String dimension,
    String status,
    String conditionCode,
    int subcase) {
  public CanonicalMetric {
    if (metricCode == null
        || !metricCode.matches("[A-Z][A-Z0-9_]{0,63}")
        || metricName == null
        || metricName.isBlank()
        || (valueNum == null) == (valueText == null)
        || unit == null
        || dimension == null
        || status == null
        || conditionCode == null
        || !conditionCode.matches("[A-Za-z0-9_-]{1,64}")
        || subcase < 1
        || subcase > 1000)
      throw new IllegalArgumentException("Invalid canonical engineering metric");
    if (valueNum != null && (valueNum.precision() - valueNum.scale() > 20 || valueNum.scale() > 10))
      throw new IllegalArgumentException("Canonical numeric value exceeds the storage precision");
  }
}

