import com.example.cae.project.ProjectService;
import com.example.cae.report.RenderFingerprint;
import com.example.cae.resource.ResourceProfileRegistry;
import com.example.cae.scheduler.SchedulerService;
import java.time.LocalDate;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import org.springframework.security.core.Authentication;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
public class JobApplicationService {
  private final JobRepository jobs;
  private final ProjectAccess access;
  private final ProjectService projects;
  private final ResourceProfileRegistry profiles;
  private final CreateRequestRepository creates;
  private final RenderFingerprint fingerprints;
  private final JsonCodec json;
  private final JobQueryCache cache;

  public JobApplicationService(
      JobRepository jobs,
      ProjectAccess access,
      ProjectService projects,
      ResourceProfileRegistry profiles,
      CreateRequestRepository creates,
      RenderFingerprint fingerprints,
      JsonCodec json,
      JobQueryCache cache) {
    this.jobs = jobs;
    this.access = access;
    this.projects = projects;
    this.profiles = profiles;
    this.creates = creates;
    this.fingerprints = fingerprints;
    this.json = json;
    this.cache = cache;
  }

  @Transactional
  public Map<String, Object> create(Authentication user, CreateJobRequest request) {
    return create(user, request, null);
  }

  @Transactional
  public Map<String, Object> create(Authentication user, CreateJobRequest request, String key) {
    access.require(user, request.projectId());
    projects.requireRevision(request.projectId(), request.modelRevisionId());
    if (key != null) {
      var normalized = new LinkedHashMap<>(json.readMap(json.write(request)));
      normalized.put("priority", request.priority() == null ? 50 : request.priority());
      Long previous = creates.claim(user.getName(), key, fingerprints.of(normalized));
      if (previous != null) return jobs.lockById(previous);
    }
    String profile =
        request.solverProfile() == null
            ? request.analysisType().name() + "_STANDARD"
            : request.solverProfile();
    String solver =
        request.solverType() == null
            ? switch (request.analysisType()) {
              case STRUCTURE -> "MOCK_OPTISTRUCT";
              case NVH -> "MOCK_NVH";
              case CRASH -> "MOCK_CRASH";
              case CFD -> "MOCK_CFD";
            }
            : request.solverType();
    String expectedSolver =
        switch (request.analysisType()) {
          case STRUCTURE -> "MOCK_OPTISTRUCT";
          case NVH -> "MOCK_NVH";
          case CRASH -> "MOCK_CRASH";
          case CFD -> "MOCK_CFD";
        };
    if (!profile.equals(request.analysisType().name() + "_STANDARD")
        || !solver.equals(expectedSolver))
      throw ApiException.invalid("Solver profile and solver type must match the analysis type");
    String resourceProfile =
        request.resourceProfile() == null ? "STANDARD" : request.resourceProfile();
    ResourceProfileRegistry.Snapshot selected =
        profiles.select(resourceProfile, request.analysisType(), request.resource());
    Map<String, Object> resource = selected.resource();
    Map<String, Object> input = request.input() == null ? Map.of() : request.input();
    Object manifest = input.get("manifest");
    if (manifest != null && !(manifest instanceof String))
      throw ApiException.invalid("Input manifest must be a relative path string");
    Object entryDeck = input.get("entryDeck");
    if (entryDeck != null && !(entryDeck instanceof String))
      throw ApiException.invalid("Input entryDeck must be a relative path string");
    String casePath = request.casePath();
    if (casePath == null && manifest instanceof String path) {
      path = path.replace('\\', '/');
      if (path.startsWith("demo-data/")) path = path.substring("demo-data/".length());
      int slash = path.lastIndexOf('/');
      if (slash >= 0) casePath = path.substring(0, slash);
    }
    if (casePath != null
        && (casePath.startsWith("/")
            || casePath.startsWith("\\")
            || casePath.contains("..")
            || casePath.indexOf('\u0000') >= 0
            || casePath.contains(":")))
      throw ApiException.invalid("Case path must be a relative path inside the demo case root");
    Map<String, Object> fields = new LinkedHashMap<>();
    fields.put("projectId", request.projectId());
    fields.put("modelRevisionId", request.modelRevisionId());
    fields.put("analysisType", request.analysisType().name());
    fields.put("conditionCode", request.conditionCode());
    fields.put("solverType", solver);
    fields.put("solverProfile", profile);
    fields.put("priority", request.priority() == null ? 50 : request.priority());
    fields.put("submitterId", user.getName());
    fields.put("casePath", casePath);
    fields.put("inputManifestUri", manifest);
    fields.put("input", input);
    fields.put("resource", resource);
    fields.put("resourceProfileId", resourceProfile);
    fields.put("resourceProfileVersion", selected.version());
    fields.put("licenseFeature", SchedulerService.feature(solver));
    fields.put("licenseTokenCount", selected.licenseTokens());
    fields.put("mock", request.mock() == null ? Map.of() : request.mock());
    Map<String, Object> created = jobs.create(fields);
    if (key != null) creates.complete(user.getName(), key, SqlRows.id(created));
    jobs.audit(
        user.getName(),
        "JOB_CREATE",
        "JOB",
        created.get("jobNo").toString(),
        null,
        Map.of("status", created.get("status"), "projectId", created.get("projectId")));
    return created;
  }

  public Map<String, Object> get(Authentication user, String jobNo) {
    return cache.get(user, jobNo, () -> jobs.findByNo(jobNo));
  }

  public List<Map<String, Object>> events(Authentication user, String jobNo) {
    return jobs.events(SqlRows.id(get(user, jobNo)));
  }

  public Map<String, Object> list(
      Authentication user, Map<String, Object> requested, int page, int size) {
    if (page < 0 || size < 1 || size > 100 || (long) page * size > Integer.MAX_VALUE)
      throw ApiException.invalid("Page must be >= 0 and size must be between 1 and 100");
    Map<String, Object> filters = new LinkedHashMap<>(requested);
    if (!access.admin(user)) filters.put("username", user.getName());
    Object project = filters.get("projectId");
    if (project != null) {
      try {
        access.require(user, Long.parseLong(project.toString()));
      } catch (NumberFormatException e) {
        throw ApiException.invalid("Project id must be a positive integer");
      }
    }
    Object from = filters.get("dateFrom");
    java.time.ZoneId zone;
    try {
      zone = java.time.ZoneId.of(filters.getOrDefault("timeZone", "UTC").toString());
    } catch (java.time.DateTimeException invalid) {
      throw ApiException.invalid("Unknown time zone");
    }
    if (from != null)
      filters.put(
          "createdFrom",
          java.sql.Timestamp.from(date(from.toString()).atStartOfDay(zone).toInstant()));
    Object to = filters.get("dateTo");
    if (to != null)
      filters.put(
          "createdTo",
          java.sql.Timestamp.from(date(to.toString()).plusDays(1).atStartOfDay(zone).toInstant()));
    return Map.of(
        "items",
        jobs.list(filters, page * size, size),
        "total",
        jobs.count(filters),
        "page",
        page,
        "size",
        size);
  }

private LocalDate date(String value) {
  try {
    return LocalDate.parse(value);
  } catch (java.time.format.DateTimeParseException e) {
    throw ApiException.invalid("Date filters must use yyyy-MM-dd");
  }
}

  @Transactional
  public Map<String, Object> changePriority(Authentication user, String jobNo, int priority) {
    Map<String, Object> job = get(user, jobNo);
    access.requireLead(user, ((Number) job.get("projectId")).longValue());
    if (priority < 0 || priority > 100)
      throw ApiException.invalid("Priority must be between 0 and 100");
    Map<String, Object> result = jobs.patch(SqlRows.id(job), Map.of("priority", priority));
    jobs.recordEvent(SqlRows.id(job), "JOB_PRIORITY_CHANGED", Map.of("priority", priority));
    jobs.audit(
        user.getName(),
        "PRIORITY_CHANGE",
        "JOB",
        jobNo,
        Map.of("priority", job.get("priority")),
        Map.of("priority", priority));
    return result;
  }
}

package com.example.cae.job.application;

import com.example.cae.artifact.ArtifactFileStore;
import com.example.cae.auth.ProjectAccess;
import com.example.cae.common.ApiException;
import com.example.cae.job.execution.ExecutionRepository;
import com.example.cae.job.repository.JobRepository;
import java.io.IOException;
import java.nio.ByteBuffer;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.security.core.Authentication;

@org.springframework.stereotype.Service
public class JobLogService {
  private final JobRepository jobs;
  private final ExecutionRepository executions;
  private final ProjectAccess access;
  private final ArtifactFileStore files;
  private final String token;

public JobLogService(
    JobRepository jobs,
    ExecutionRepository executions,
    ProjectAccess access,
    ArtifactFileStore files,
    @Value("${SERVICE_TOKEN:demo-service-token}") String token) {
  this.jobs = jobs;
  this.executions = executions;
  this.access = access;
  this.files = files;
  this.token = token;
}

public Map<String, Object> logs(Authentication user, String jobNo, Long executionId, int lines) {
  var job = jobs.findByNo(jobNo);
  access.requireJob(user, job);
  if (lines < 1 || lines > 500) throw ApiException.invalid("Log tail supports 1–500 lines");
  if (executionId == null && job.get("currentExecutionId") == null)
    return Map.of("jobNo", jobNo, "lines", List.of(), "truncated", false);
  long id =
      executionId == null ? ((Number) job.get("currentExecutionId")).longValue() : executionId;
  var execution = executions.find(id);
  if (((Number) execution.get("jobId")).longValue() != ((Number) job.get("id")).longValue())
    throw ApiException.notFound("Execution for this Job");
  String request = execution.get("submitRequestId").toString();
  if (!request.matches("[A-Za-z0-9_-]{1,100}"))
    throw ApiException.invalid("Unsafe execution identity");
  try {
    Path path =
        files.requireJob("jobs/" + jobNo + "/executions/" + request + "/solver.log", jobNo);
    if (!Files.exists(path, LinkOption.NOFOLLOW_LINKS))
      return Map.of("jobNo", jobNo, "executionId", id, "lines", List.of(), "truncated", false);
    if (!Files.isRegularFile(path, LinkOption.NOFOLLOW_LINKS))
      throw ApiException.conflict("Log must be a regular file");

try (var channel =
    Files.newByteChannel(path, Set.of(StandardOpenOption.READ, LinkOption.NOFOLLOW_LINKS))) {
  long size = channel.size();
  long offset = Math.max(0, size - 256 * 1024);
  channel.position(offset);
  ByteBuffer buffer = ByteBuffer.allocate((int) Math.min(size - offset, 256 * 1024));
  while (buffer.hasRemaining() && channel.read(buffer) > 0) {}
  buffer.flip();
  String text = StandardCharsets.UTF_8.decode(buffer).toString();
  if (offset > 0) {
    int newline = text.indexOf('\n');
    text = newline < 0 ? "" : text.substring(newline + 1);
  }
  text =
      text.replaceAll("\\x1b\\[[0-?]*[ -/]*[@-~]", "")
          .replaceAll("[\\p{Cntrl}&&[^\\n\\t]]", "");
  if (!token.isBlank()) text = text.replace(token, "[REDACTED]");
  text =
      text.replaceAll("(?i)(authorization\\s*[=:]\\s*)[^\\n]+", "$1[REDACTED]")
          .replaceAll(
              "(?i)((?:password|service[_-]?token)\\s*[=:]\\s*)[^\\s,;]+", "$1[REDACTED]");
  List<String> all = text.lines().toList();
  return Map.of(
      "jobNo",
      jobNo,
      "executionId",
      id,
      "lines",
      all.subList(Math.max(0, all.size() - lines), all.size()),
      "truncated",
      offset > 0 || all.size() > lines,
      "updatedAt",
      Files.getLastModifiedTime(path).toInstant().toString());
}

    } catch (IllegalArgumentException unsafe) {
      throw ApiException.conflict("Solver log path is unsafe");
    } catch (IOException unavailable) {
      throw ApiException.conflict("Solver log is temporarily unavailable");
    }
  }
}

