import com.example.cae.common.ApiException;
import java.util.Map;

/** Domain state is the only authority deciding legal business transitions. */
public class CaeJob {
  private final long id;
  private final String jobNo;
  private final long version;
  private JobStatus status;
  private final JobTransitionPolicy policy;

public CaeJob(long id, String jobNo, JobStatus status, long version, JobTransitionPolicy policy) {
  this.id = id;
  this.jobNo = jobNo;
  this.status = status;
  this.version = version;
  this.policy = policy;
}

public static CaeJob from(Map<String, Object> row, JobTransitionPolicy policy) {
  return new CaeJob(
      ((Number) row.get("id")).longValue(),
      row.get("jobNo").toString(),
      JobStatus.valueOf(row.get("status").toString()),
      ((Number) row.get("version")).longValue(),
      policy);
}

/** Duplicate delivery of the current status is idempotent and does not append an event. */
public boolean transitTo(JobStatus target) {
  if (status == target) return false;
  if (!policy.canTransit(status, target))
    throw ApiException.conflict("Job cannot transit from " + status + " to " + target);
  status = target;
  return true;
}

public long id() {
  return id;
}

public String jobNo() {
  return jobNo;
}

public JobStatus status() {
  return status;
}

public long version() {
  return version;
}

package com.example.cae.job.domain;

import java.util.EnumMap;
import java.util.Map;
import java.util.Set;
import org.springframework.stereotype.Component;

@Component
public class DefaultJobTransitionPolicy implements JobTransitionPolicy {
  private static final Map<JobStatus, Set<JobStatus>> EDGES = new EnumMap<>(JobStatus.class);

  static {
    allow(JobStatus.CREATED, JobStatus.VALIDATING, JobStatus.CANCEL_REQUESTED);
    allow(
        JobStatus.VALIDATING,
        JobStatus.READY,
        JobStatus.VALIDATION_FAILED,
        JobStatus.CANCEL_REQUESTED);
    allow(
        JobStatus.READY, JobStatus.WAITING_RESOURCE, JobStatus.QUEUED, JobStatus.CANCEL_REQUESTED);
    allow(JobStatus.WAITING_RESOURCE, JobStatus.QUEUED, JobStatus.CANCEL_REQUESTED);
    allow(
        JobStatus.QUEUED,
        JobStatus.SUBMITTING,
        JobStatus.WAITING_RESOURCE,
        JobStatus.CANCEL_REQUESTED);
    allow(
        JobStatus.SUBMITTING,
        JobStatus.SUBMITTED,
        JobStatus.SUBMIT_FAILED,
        JobStatus.UNKNOWN,
        JobStatus.CANCEL_REQUESTED);
    allow(
        JobStatus.SUBMITTED,
        JobStatus.RUNNING,
        JobStatus.POST_PROCESSING,
        JobStatus.RUNTIME_FAILED,
        JobStatus.UNKNOWN,
        JobStatus.CANCEL_REQUESTED);
    allow(
        JobStatus.RUNNING,
        JobStatus.POST_PROCESSING,
        JobStatus.RUNTIME_FAILED,
        JobStatus.UNKNOWN,
        JobStatus.CANCEL_REQUESTED);
    allow(
        JobStatus.POST_PROCESSING,
        JobStatus.REPORTING,
        JobStatus.POST_PROCESS_FAILED,
        JobStatus.CANCEL_REQUESTED);
    allow(
        JobStatus.REPORTING,
        JobStatus.SUCCESS,
        JobStatus.REPORT_FAILED,
        JobStatus.CANCEL_REQUESTED);
    allow(
        JobStatus.CANCEL_REQUESTED,
        JobStatus.CANCELLED,
        JobStatus.UNKNOWN,
        JobStatus.POST_PROCESSING,
        JobStatus.RUNTIME_FAILED);
    allow(
        JobStatus.UNKNOWN,
        JobStatus.SUBMITTED,
        JobStatus.RUNNING,
        JobStatus.POST_PROCESSING,
        JobStatus.RUNTIME_FAILED,
        JobStatus.SUBMIT_FAILED,
        JobStatus.CANCEL_REQUESTED,
        JobStatus.CANCELLED);
    // Retry edges are explicit; even a failed or cancelled job can never jump to RUNNING.
    allow(JobStatus.VALIDATION_FAILED, JobStatus.VALIDATING);
    allow(JobStatus.SUBMIT_FAILED, JobStatus.READY);
    allow(JobStatus.RUNTIME_FAILED, JobStatus.READY);
    allow(JobStatus.POST_PROCESS_FAILED, JobStatus.POST_PROCESSING);
    allow(JobStatus.REPORT_FAILED, JobStatus.REPORTING, JobStatus.POST_PROCESSING);
    allow(JobStatus.CANCELLED, JobStatus.READY, JobStatus.VALIDATING);
  }

private static void allow(JobStatus from, JobStatus... to) {
  EDGES.put(from, Set.of(to));
}

@Override
public boolean canTransit(JobStatus from, JobStatus to) {
  return EDGES.getOrDefault(from, Set.of()).contains(to);
}

public boolean terminal() {
  return TERMINAL.contains(this);
}

