import java.util.LinkedHashMap;
import java.util.Map;
import java.util.Set;

public static Map<String, Object> validate(Map<String, Object> requested) {
  Map<String, Object> options =
      new LinkedHashMap<>(
          Map.of(
              "runtimeSeconds",
              3,
              "successProbability",
              1,
              "failureMode",
              "NONE",
              "progressInterval",
              0.2,
              "responseDelayOnceSeconds",
              0));
  if (requested != null) {
    for (String key : requested.keySet())
      if (!Set.of(
              "runtimeSeconds",
              "successProbability",
              "failureMode",
              "progressInterval",
              "responseDelayOnceSeconds",
              "seed")
          .contains(key)) throw ApiException.invalid("Unsupported mock execution option: " + key);
    options.putAll(requested);
  }
  number(options, "runtimeSeconds", 0.05, 600);
  number(options, "successProbability", 0, 1);
  number(options, "progressInterval", 0.02, 10);
  number(options, "responseDelayOnceSeconds", 0, 30);
  if (!(options.get("failureMode") instanceof String mode)
      || !Set.of("NONE", "RUNTIME_FAILED", "TIMEOUT").contains(mode))
    throw ApiException.invalid("Unknown mock solver failure mode");
  if (options.get("seed") != null) {
    number(options, "seed", 0, 4294967295L);
    Number seed = (Number) options.get("seed");
    if (seed.doubleValue() != seed.longValue())
      throw ApiException.invalid("Mock seed must be an integer");
  }
  return options;
}

private static void number(
    Map<String, Object> value, String key, double minimum, double maximum) {
  if (!(value.get(key) instanceof Number n)
      || !Double.isFinite(n.doubleValue())
      || n.doubleValue() < minimum
      || n.doubleValue() > maximum) throw ApiException.invalid("Invalid mock option: " + key);
}

package com.example.cae.job.submission;

import com.example.cae.job.repository.JobRepository;
import jakarta.annotation.PreDestroy;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.beans.factory.annotation.Value;
import org.springframework.scheduling.annotation.Scheduled;
import org.springframework.stereotype.Component;

/** Re-scan durable waiting work; RabbitMQ commands own remote submission delivery. */
@Component
public class SubmissionLoop {
  private static final Logger LOG = LoggerFactory.getLogger(SubmissionLoop.class);
  private final FairAdmissionRepository admission;
  private final JobRepository jobs;
  private final JobCommandService commands;
  private final JobAllocationService allocation;
  private final JobCancellationService cancellation;
  private final boolean enabled;
  private final Set<Long> inFlight = ConcurrentHashMap.newKeySet();
  private final ExecutorService executor = Executors.newFixedThreadPool(4);

  public SubmissionLoop(
      JobRepository jobs,
      FairAdmissionRepository admission,
      JobCommandService commands,
      JobAllocationService allocation,
      JobCancellationService cancellation,
      @Value("${cae.background.enabled:true}") boolean enabled) {
    this.jobs = jobs;
    this.admission = admission;
    this.commands = commands;
    this.allocation = allocation;
    this.cancellation = cancellation;
    this.enabled = enabled;
  }

@Scheduled(fixedDelayString = "${cae.scheduler.scan-ms:1000}")
public void scan() {
  if (!enabled) return;
  commands.pendingValidation().stream().limit(8).forEach(this::dispatch);
  admission.cancellations().forEach(this::dispatch);
  admission.waiting(12).forEach(this::dispatch);
}

private void dispatch(long id) {
  if (inFlight.size() >= 20 || !inFlight.add(id)) return;
  executor.execute(
      () -> {
        try {
          if ("CANCEL_REQUESTED".equals(jobs.findById(id).get("status")))
            cancellation.continueCancel(id);
          else {
            if (commands.pendingValidation().contains(id)) commands.finishValidation(id);
            allocation.allocate(id);
          }
        } catch (RuntimeException e) {
          LOG.warn(
              "Deferred Job orchestration jobId={} cause={}", id, e.getClass().getSimpleName());
        } finally {
          inFlight.remove(id);
        }
      });
}

@PreDestroy
public void close() {
  executor.shutdownNow();
}

