def _save_current_answer(self) -> None:
    q = self._questions[self._q_idx]
    options = q.get("options", [])
    cursor = self._cursors[self._q_idx]
    is_multi = q.get("multiSelect", False)

    if cursor == len(options):  # "Other"（自定义输入）
