/** eventId identifies business handling; deliveryId identifies one physical outbox publication. */
public record CommandEnvelope(
    String eventId,
    String deliveryId,
    String eventType,
    long jobId,
    String jobNo,
    Instant occurredAt,
    int payloadVersion,
    int deliveryAttempt,
    Map<String, Object> payload) {

  public CommandEnvelope {
    identifier(eventId);
    identifier(deliveryId);
    if (eventType == null
        || !eventType.matches("[A-Z][A-Z0-9_]{0,63}")
        || jobId <= 0
        || jobNo == null
        || !jobNo.matches("CAE-[0-9]{8}-[0-9]{6,}")
        || occurredAt == null
        || payloadVersion != 1
        || deliveryAttempt < 0
        || deliveryAttempt > 100
        || payload == null)
      throw new IllegalArgumentException("Message violates command envelope version 1");
    payload = Collections.unmodifiableMap(new LinkedHashMap<>(payload));
  }

